def companion_veteran_tip_reply(status_context: dict[str, object] | None = None) -> str:
    context = dict(status_context or {})
    personality = str(context.get("personality_label", "보통형") or "보통형")
    tactic = str(context.get("tactic_label", "균형") or "균형")
    return f"숙련 운용은 역할보다 전술을 먼저 보시면 됩니다. 저는 {personality}/{tactic} 세팅이라, 필요하면 공격 우선·메즈 우선·리더 보호 같은 용도로 바꿔 쓰는 쪽이 좋습니다."


def companion_post_combat_reflection_line(
    personality: str,
    outcome: str,
    *,
    trust: object = 50,
    target_name: str = "",
) -> str:
    personality_key = str(personality or "").strip().lower()
    trust_stage = mercenary_trust_stage_label(trust)
    target = short_text(str(target_name or "대상"), 40)
    if outcome in {"target_removed", "party_objective_complete"}:
        by_personality = {
            "calm_support": f"{target} 정리됐습니다. 체력만 다시 안정시키겠습니다.",
            "bold_vanguard": f"{target} 끝났습니다. 다음 표적도 바로 받을 수 있습니다.",
            "sharp_striker": f"{target} 처리 완료. 빈틈 보이면 바로 이어가겠습니다.",
            "cautious_scout": f"{target} 정리했습니다. 주변 애드부터 다시 살피겠습니다.",
            "sly_opportunist": f"{target} 마무리했습니다. 이득은 챙기되 무리하진 마시죠.",
            "cunning_opportunist": f"{target} 마무리했습니다. 이득은 챙기되 무리하진 마시죠.",
            "shifty_traitor": f"{target}은 끝났습니다. 아직 계약은 괜찮게 굴러가네요.",
            "reckless_berserker": f"{target} 쓰러졌습니다. 아직 더 밀 수 있습니다.",
            "lazy_veteran": f"{target} 끝났습니다... 잠깐 숨 돌리고 갑시다.",
        }
        if trust_stage in {"충성", "두터운 신뢰"} and personality_key not in {"shifty_traitor", "sly_opportunist", "cunning_opportunist"}:
            return f"{by_personality.get(personality_key, f'{target} 정리됐습니다. 다음 지시 기다리겠습니다.')} 리더 판단 좋았습니다."
        return by_personality.get(personality_key, f"{target} 정리됐습니다. 다음 지시 기다리겠습니다.")
    if outcome in {"flee", "critical_health_drop_aggro", "safe_exit_flee"}:
        return "위험해서 빠졌습니다. 다시 붙기 전에 체력과 거리를 먼저 보겠습니다."
    if outcome == "player_death":
        return "방금 전투는 안 좋았습니다. 부활과 안전거리부터 다시 맞추겠습니다."
    if outcome in {"target_lost", "server_los_failure", "combat_chase_overextended"}:
        return "대상을 놓쳤습니다. 시야와 거리를 다시 잡겠습니다."
    return ""


def party_snapshot_with_companion_attack_command(
    party_snapshot: dict,
    *,
    command_attack_active: bool,
    now: float,
) -> dict:
    if not command_attack_active:
        return party_snapshot
    snapshot = dict(party_snapshot)
    snapshot["companion_command_attack_active"] = True
    if int(snapshot.get("leader_target_id", 0) or 0) > 0:
        snapshot["leader_target_engaged_at"] = float(now)
    return snapshot


def party_snapshot_companion_command_attack_active(party_snapshot: dict[str, object] | None) -> bool:
    return bool((party_snapshot or {}).get("companion_command_attack_active"))


def should_force_stationary_cast_for_companion_command(
    rotation: str,
    party_snapshot: dict[str, object] | None,
) -> bool:
    return bool(rotation == "healer-support" and party_snapshot_companion_command_attack_active(party_snapshot))


def companion_role_can_heal(role: str) -> bool:
    role_key = normalize_target_name(role)
    if not role_key:
        return True
    return "healer" in role_key or "healersupport" in role_key


def companion_role_can_resurrect(role: str) -> bool:
    return companion_role_can_heal(role)


def companion_role_can_cure(role: str) -> bool:
    return companion_role_can_heal(role)


def choose_dialogue_line(
    lines: list[str],
    rng: random.Random,
    *,
    recent: list[str] | None = None,
) -> str:
    candidates = [line for line in lines if line]
    if not candidates:
        candidates = list(DEFAULT_COMPANION_CHAT_REPLY_LINES)
    if recent and len(candidates) > len(recent):
        recent_set = set(recent)
        filtered = [line for line in candidates if line not in recent_set]
        if filtered:
            candidates = filtered
    return rng.choice(candidates)


def choose_companion_chat_reply(
    body: str,
    lines: list[str],
    rng: random.Random,
    *,
    pools: dict[str, list[str]] | None = None,
    personality_pools: dict[str, list[str]] | None = None,
    recent: list[str] | None = None,
    role: str = "",
    status_context: dict[str, object] | None = None,
) -> str:
    intent = companion_chat_intent(body)
    pool_intent = intent
    if intent == "help":
        return companion_command_help_line()
    if intent == "status":
        return companion_status_reply(status_context)
    if intent == "record":
        return companion_record_reply(status_context)
    if intent == "journal":
        return companion_journal_reply(status_context)
    if intent == "tactic":
        return companion_tactic_reply(status_context)
    if intent == "beginner_tip":
        return companion_beginner_tip_reply(status_context)
    if intent == "veteran_tip":
        return companion_veteran_tip_reply(status_context)
    if intent == "next_action":
        return companion_next_action_reply(status_context)
    if intent == "combat" and companion_role_uses_one_shot_combat_command(role):
        if personality_pools:
            category_lines = personality_pools.get("combat_healer") or []
            if category_lines:
                return choose_dialogue_line(category_lines, rng, recent=recent)
        return "한 번 받아칠게요. 그 다음은 치유랑 해제부터 보겠습니다."
    if intent == "heal" and not companion_role_can_heal(role):
        pool_intent = "unable_heal"
    elif intent == "resurrect" and not companion_role_can_resurrect(role):
        pool_intent = "unable_resurrect"
    elif intent == "cure" and not companion_role_can_cure(role):
        pool_intent = "unable_cure"

    if personality_pools:
        category_lines = personality_pools.get(pool_intent) or []
        if category_lines:
            return choose_dialogue_line(category_lines, rng, recent=recent)

    if pools:
        category_lines = pools.get(pool_intent) or pools.get("chatter") or []
        if category_lines:
            return choose_dialogue_line(category_lines, rng, recent=recent)

    fallback_by_intent = {
        "unable_resurrect": "저는 부활은 못 합니다. 대신 주변 어그로를 잡고 안전하게 만들겠습니다.",
        "unable_heal": "저는 치유는 못 합니다. 대신 앞에서 막고 위험한 대상을 붙잡겠습니다.",
        "unable_cure": "저는 해제는 못 합니다. 대신 위험한 대상을 붙잡고 시간을 벌겠습니다.",
        "resurrect": "알겠습니다. 부활 대상부터 확인하겠습니다.",
        "cure": "알겠습니다. 해제 가능한 상태부터 확인하겠습니다.",
        "heal": "알겠습니다. 체력과 부활 먼저 보겠습니다.",
        "flee": "알겠습니다. 전투가 아니면 바로 안전한 쪽으로 빠지겠습니다.",
        "follow": "네, 따라가겠습니다. 거리 벌어지면 바로 붙을게요.",
        "go": "좋습니다. 이동하겠습니다. 뒤처지면 바로 따라붙겠습니다.",
        "summon": "바로 붙겠습니다. 멀어지면 따라잡겠습니다.",
        "combat": "전투 지시 확인했습니다. {player}{이가} 찍은 대상부터 제가 먼저 들어가겠습니다.",
        "passive": "수동으로 전환하겠습니다. 먼저 공격하지 않고 지시를 기다리겠습니다.",
        "defensive": "방어로 전환하겠습니다. 누가 맞으면 바로 떼어내겠습니다.",
        "wait": "여기서 대기하겠습니다. 준비되면 다시 움직일게요.",
        "help": companion_command_help_line(),
        "status": companion_status_reply(status_context),
        "record": companion_record_reply(status_context),
        "journal": companion_journal_reply(status_context),
        "tactic": companion_tactic_reply(status_context),
        "beginner_tip": companion_beginner_tip_reply(status_context),
        "veteran_tip": companion_veteran_tip_reply(status_context),
        "next_action": companion_next_action_reply(status_context),
        "thanks": "천만에요. 계속 옆에서 맞춰가겠습니다.",
    }
    if pool_intent in fallback_by_intent:
        return fallback_by_intent[pool_intent]
    return choose_dialogue_line(lines or DEFAULT_COMPANION_CHAT_REPLY_LINES, rng, recent=recent)


def companion_auto_speech_intent(state: str, text: str) -> str:
    state_key = str(state or "")
    text_key = normalize_target_name(text)
    if state_key == "combat_reposition":
        return "combat_reposition"
    if state_key in {"peel_request", "party_rescue_request"}:
        return "party_rescue_request"
    if state_key.startswith("combat:") or "attacking" in text_key:
        return "combat_start"
    if state_key in {"flee", "flee_recovered", "return_home"}:
        return state_key
    if "train" in text_key:
        return "status"
    return "status"


def choose_companion_auto_speech(
    state: str,
    text: str,
    rng: random.Random,
    *,
    personality_state_pools: dict[str, list[str]] | None = None,
    recent: list[str] | None = None,
) -> str:
    intent = companion_auto_speech_intent(state, text)
    if personality_state_pools:
        lines = personality_state_pools.get(intent) or personality_state_pools.get("status") or []
        if lines:
            return choose_dialogue_line(lines, rng, recent=recent)
    return text


LIVE_CONTROL_ALLOWED_COMMAND_PREFIXES = (
    "/invite ",
    "/g ",
    "/say ",
    "/sprint",
    "/stick",
    "/follow",
    "/face",
    "/sit",
    "/quit",
)


def safe_live_control_command(command: object) -> str:
    text = " ".join(str(command or "").split())
    if not text.startswith("/"):
        return ""
    lowered = text.lower()
    if any(lowered == prefix or lowered.startswith(prefix) for prefix in LIVE_CONTROL_ALLOWED_COMMAND_PREFIXES):
        return text
    return ""


def parse_live_control_bool(value: object) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    text = str(value or "").strip().lower()
    if text in {"0", "false", "no", "off", "disable", "disabled"}:
        return False
    if text in {"1", "true", "yes", "on", "enable", "enabled"}:
        return True
    return bool(value)


def normalize_live_control_intent_hint(value: object) -> str:
    return str(value or "none").strip().lower().replace("-", "_").replace(" ", "_")


def live_control_intent_timer_updates(intent_hint: object) -> set[str]:
    hint = normalize_live_control_intent_hint(intent_hint)
    if hint == "heal_priority":
        return {"party_heal"}
    if hint == "resurrect_priority":
        return {"party_resurrect"}
    if hint == "cc_add":
        return {"crowd_control"}
    if hint == "cure_priority":
        return {"party_cure"}
    return set()


LIVE_CONTROL_NUMERIC_FIELDS = {
    "combat_chase_max_distance": float,
    "combat_direct_move_distance": float,
    "combat_home_leash_distance": float,
    "hunter_target_api_engage_distance": float,
    "hunter_target_api_radius": float,
    "hunter_target_max_ground_z_delta": float,
    "max_target_distance": float,
    "min_target_level": int,
    "max_target_level_delta": int,
    "required_target_home_hunt_distance": float,
    "target_home_max_distance": float,
    "target_timeout_approach_progress_distance": float,
    "target_timeout": float,
}


LIVE_CONTROL_BOOL_FIELDS = {
    "allow_avoid_target_fallback",
    "current_target_api_refresh",
    "hunter_target_api_scout",
    "reject_target_on_server_los_failure",
}


def normalize_live_control_key(key: object) -> str:
    return str(key or "").strip().replace("-", "_")


def live_control_revision(payload: dict[str, object], mtime_ns: int) -> str:
    revision = payload.get("revision", payload.get("rev", ""))
    return str(revision) if str(revision).strip() else str(mtime_ns)


def read_live_control_payload(path: str) -> tuple[dict[str, object] | None, int]:
    if not path:
        return None, 0

    control_path = Path(path)
    try:
        stat = control_path.stat()
    except FileNotFoundError:
        return None, 0

    try:
        payload = json.loads(control_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None, stat.st_mtime_ns

    return (payload if isinstance(payload, dict) else None), stat.st_mtime_ns


def apply_live_control_overrides(args: argparse.Namespace, payload: dict[str, object]) -> dict[str, tuple[object, object]]:
    updates: dict[str, tuple[object, object]] = {}
    normalized = {normalize_live_control_key(key): value for key, value in payload.items()}

    for field, caster in LIVE_CONTROL_NUMERIC_FIELDS.items():
        if field not in normalized:
            continue
        try:
            value = caster(normalized[field])
        except (TypeError, ValueError):
            continue
        if field == "min_target_level" and "baseline_min_target_level" in normalized:
            try:
                value = max(value, caster(normalized["baseline_min_target_level"]))
            except (TypeError, ValueError):
                pass
        if field == "max_target_level_delta" and "baseline_max_target_level" in normalized:
            try:
                baseline_max = int(normalized["baseline_max_target_level"])
                player_level = int(getattr(args, "player_level", 0) or 0)
                if player_level > 0:
                    value = min(value, baseline_max - player_level)
            except (TypeError, ValueError):
                pass
        previous = getattr(args, field, None)
        if previous != value:
            setattr(args, field, value)
            updates[field] = (previous, value)

    for field in LIVE_CONTROL_BOOL_FIELDS:
        if field not in normalized:
            continue
        value = parse_live_control_bool(normalized[field])
        previous = getattr(args, field, None)
        if previous != value:
            setattr(args, field, value)
            updates[field] = (previous, value)

    return updates


