@dataclass
class CombatMetric:
    target_id: int
    target_name: str
    target_level: int
    outcome: str
    duration: float
    attacks: int = 0
    skills: int = 0
    start_distance: float = 0.0
    end_distance: float = 0.0


POST_ABANDON_TARGET_REMOVED_OUTCOMES = frozenset(
    {
        "critical_health_drop_aggro",
        "flee",
        "travel_aggro_drop",
    }
)
POST_ABANDON_TARGET_REMOVED_GRACE_SECONDS = 8.0


def promote_recent_finished_combat_to_target_removed(
    metric: CombatMetric,
    *,
    finished_at: float,
    now: float,
    damage_done: int,
    grace_seconds: float = POST_ABANDON_TARGET_REMOVED_GRACE_SECONDS,
) -> bool:
    if metric.outcome not in POST_ABANDON_TARGET_REMOVED_OUTCOMES:
        return False
    if damage_done <= 0:
        return False
    if now - finished_at > grace_seconds:
        return False

    metric.duration += max(0.0, now - finished_at)
    metric.outcome = "target_removed"
    return True


def target_removed_creditable(args: argparse.Namespace, active_combat: dict[str, object] | None, final_distance: float) -> bool:
    if active_combat is None:
        return False

    if int(active_combat.get("damage_done", 0) or 0) > 0:
        return True
    if int(active_combat.get("attacks", 0) or 0) > 0:
        return True
    if int(active_combat.get("skills", 0) or 0) > 0:
        return True

    credit_distance = max(
        float(getattr(args, "attack_range", 0.0) or 0.0),
        float(getattr(args, "max_target_distance", 0.0) or 0.0),
        float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0),
        float(getattr(args, "party_rescue_objective_max_distance", 0.0) or 0.0),
    )
    return credit_distance <= 0.0 or float(final_distance or 0.0) <= credit_distance


def confirmed_target_removed_combats(
    combats: list[CombatMetric],
    action_counts: dict[str, int] | None,
) -> list[CombatMetric]:
    target_removed = [combat for combat in combats if combat.outcome == "target_removed"]
    if target_removed:
        return target_removed

    actions = action_counts or {}
    confirmed_completion = any(
        int(actions.get(action, 0) or 0) > 0
        for action in (
            "required_target_complete_exit",
            "dynamic_quest_complete_verified",
            "dynamic_quest_reward_observed",
            "dynamic_quest_final_inactive",
        )
    )
    if not confirmed_completion:
        return []

    return [combat for combat in combats if combat.outcome == "target_removed_pending_confirmation"]


@dataclass(frozen=True)
class Waypoint:
    x: int
    y: int
    z: int


@dataclass(frozen=True)
class MovementDestination:
    key: str
    x: int
    y: int
    z: int


@dataclass
class MovementOutcome:
    moved: bool
    arrived: bool
    actions: int = 0
    reason: str = ""


def movement_position_arrived(
    client,
    x: int,
    y: int,
    z: int,
    stop_distance: float,
) -> bool:
    del z
    dx = int(x) - int(getattr(client, "x", 0) or 0)
    dy = int(y) - int(getattr(client, "y", 0) or 0)
    return math.sqrt(dx * dx + dy * dy) <= max(0.0, float(stop_distance))


def movement_outcome_from_position_attempt(
    client,
    x: int,
    y: int,
    z: int,
    *,
    moved: bool,
    stop_distance: float,
    actions: int = 0,
    reason: str = "",
) -> MovementOutcome:
    return MovementOutcome(
        moved=moved,
        arrived=(not moved and movement_position_arrived(client, x, y, z, stop_distance)),
        actions=actions,
        reason=reason,
    )


