class PartyState:
    def __init__(
        self,
        leader_name: str,
        member_names: list[str],
        *,
        active_tank_handoff_health_percent: int = 0,
    ) -> None:
        self.leader_name = leader_name
        self.member_names = member_names
        self.active_tank_handoff_health_percent = max(0, int(active_tank_handoff_health_percent or 0))
        self.lock = threading.Lock()
        self.leader_session_id = 0
        self.leader_object_id = 0
        self.leader_x = 0
        self.leader_y = 0
        self.leader_z = 0
        self.leader_heading = 0
        self.leader_health_percent = 100
        self.leader_target_id = 0
        self.leader_target_name = ""
        self.leader_target_x = 0
        self.leader_target_y = 0
        self.leader_target_z = 0
        self.leader_target_health_percent = 0.0
        self.leader_target_health = 0
        self.leader_target_max_health = 0
        self.leader_target_can_attack: bool | None = None
        self.leader_target_relation = ""
        self.leader_target_type = ""
        self.leader_target_updated_at = 0.0
        self.leader_target_engaged_at = 0.0
        self.leader_target_focus_name = ""
        self.leader_target_focus_updated_at = 0.0
        self.objective_complete_target_id = 0
        self.objective_complete_name = ""
        self.objective_completed_at = 0.0
        self.managed_member_names: list[str] = list(member_names)
        self.external_member_names: list[str] = []
        self.member_object_ids: dict[str, int] = {name: 0 for name in member_names}
        self.member_health_percents: dict[str, int] = {name: 100 for name in member_names}
        self.member_positions: dict[str, tuple[int, int, int]] = {name: (0, 0, 0) for name in member_names}
        self.member_roles: dict[str, str] = {name: "" for name in member_names}
        self.member_conditions: dict[str, PlayerConditionSnapshot] = {}
        self.rescue_target_id = 0
        self.rescue_target_name = ""
        self.rescue_target_x = 0
        self.rescue_target_y = 0
        self.rescue_target_z = 0
        self.rescue_target_level = 0
        self.rescue_target_objective_add = False
        self.rescue_member_name = ""
        self.rescue_requested_at = 0.0
        self.rescue_threats: dict[int, dict[str, int | float | str | bool]] = {}
        self.ready_names = {leader_name}
        self.invited_names: set[str] = set()
        self.accepted_names = {leader_name}
        self.encounter_death_count = 0
        self.last_encounter_death_at = 0.0
        self.updated_at = 0.0

    def _ensure_member_locked(self, member_name: str, *, managed: bool = False, role: str = "") -> bool:
        member_name = str(member_name or "").strip()
        if not member_name:
            return False

        if member_name not in self.member_names:
            self.member_names.append(member_name)
            self.member_object_ids[member_name] = 0
            self.member_health_percents[member_name] = 100
            self.member_positions[member_name] = (0, 0, 0)
            self.member_roles[member_name] = role

        if managed:
            if member_name not in self.managed_member_names:
                self.managed_member_names.append(member_name)
            if member_name in self.external_member_names:
                self.external_member_names.remove(member_name)
        elif member_name not in self.managed_member_names and member_name not in self.external_member_names:
            self.external_member_names.append(member_name)

        existing_role = self.member_roles.get(member_name, "")
        if role and (not existing_role or existing_role == "external" or role != "external"):
            self.member_roles[member_name] = role

        return True

    def _update_member_actor_locked(self, member_name: str, actor, *, managed: bool, role: str = "") -> None:
        if not self._ensure_member_locked(member_name, managed=managed, role=role):
            return

        previous_health_percent = self.member_health_percents.get(member_name, 100)
        if hasattr(actor, "health_percent"):
            health_percent = int(getattr(actor, "health_percent", previous_health_percent) or 0)
        else:
            health_percent = previous_health_percent
        object_id = int(getattr(actor, "player_object_id", 0) or getattr(actor, "object_id", 0) or 0)
        # Identity is sticky: never clobber a previously-learned object_id with 0.
        # A member only ever has one object id per session, and we must keep it so a
        # corpse (which often reports 0 / no longer appears in visible players) can
        # still be resolved as a resurrection target after death.
        if object_id > 0:
            self.member_object_ids[member_name] = object_id
        self.member_health_percents[member_name] = health_percent
        # Position is sticky too: a (0,0,0) update means "unknown", not "at origin".
        # Keep the last known position so the corpse location survives a stale update.
        new_x = int(getattr(actor, "x", 0) or 0)
        new_y = int(getattr(actor, "y", 0) or 0)
        new_z = int(getattr(actor, "z", 0) or 0)
        if new_x or new_y or new_z:
            self.member_positions[member_name] = (new_x, new_y, new_z)
        existing_role = self.member_roles.get(member_name, "")
        if role and (not existing_role or existing_role == "external" or role != "external"):
            self.member_roles[member_name] = role
        if self.leader_target_id > 0 and previous_health_percent > 0 and health_percent <= 0:
            self.encounter_death_count += 1
            self.last_encounter_death_at = time.monotonic()

    def update_leader(self, client, target=None, *, engaged: bool = False) -> None:
        with self.lock:
            self.leader_session_id = client.session_id
            self.leader_object_id = getattr(client, "player_object_id", 0)
            self.leader_x = client.x
            self.leader_y = client.y
            self.leader_z = client.z
            self.leader_heading = client.heading
            self.leader_health_percent = getattr(client, "health_percent", 100)
            self._update_member_locked(self.leader_name, client)

            if target is not None:
                self._update_leader_target_locked(target, engaged=engaged)

            self.updated_at = time.monotonic()

    def _update_leader_target_locked(self, target, engaged: bool = False) -> None:
        target_id = int(getattr(target, "object_id", 0) or 0)
        target_name = str(getattr(target, "name", "") or "")
        target_x = int(getattr(target, "x", 0) or 0)
        target_y = int(getattr(target, "y", 0) or 0)
        target_z = int(getattr(target, "z", 0) or 0)
        target_health_percent = float(getattr(target, "health_percent", 0.0) or 0.0)
        target_health = int(getattr(target, "health", 0) or 0)
        target_max_health = int(getattr(target, "max_health", 0) or 0)
        target_can_attack = getattr(target, "can_attack", None)
        if target_can_attack is None:
            target_can_attack = getattr(target, "target_can_attack", None)
        target_relation = str(getattr(target, "relation", "") or getattr(target, "target_relation", "") or "")
        target_type = str(getattr(target, "target_type", "") or getattr(target, "type", "") or "")
        target_changed = self.leader_target_id != target_id
        position_changed = (
            self.leader_target_x != target_x
            or self.leader_target_y != target_y
            or self.leader_target_z != target_z
        )

        if target_changed or position_changed:
            updated_at = time.monotonic()
            if updated_at <= self.leader_target_updated_at:
                updated_at = self.leader_target_updated_at + 0.001
            self.leader_target_updated_at = updated_at

        if target_changed:
            self.leader_target_engaged_at = 0.0
            self.leader_target_focus_name = ""
            self.leader_target_focus_updated_at = 0.0
            self.encounter_death_count = 0
            self.last_encounter_death_at = 0.0

        self.leader_target_id = target_id
        self.leader_target_name = target_name
        self.leader_target_x = target_x
        self.leader_target_y = target_y
        self.leader_target_z = target_z
        self.leader_target_health_percent = target_health_percent
        self.leader_target_health = target_health
        self.leader_target_max_health = target_max_health
        self.leader_target_can_attack = target_can_attack
        self.leader_target_relation = target_relation
        self.leader_target_type = target_type

        if engaged and self.leader_target_engaged_at <= 0.0:
            self.leader_target_engaged_at = time.monotonic()

        focus_name = str(getattr(target, "target", "") or "").strip()
        if focus_name:
            self.leader_target_focus_name = focus_name
            self.leader_target_focus_updated_at = time.monotonic()

    def update_shared_target(self, target, engaged: bool = False) -> None:
        with self.lock:
            if self.objective_completed_at > 0.0:
                return

            self._update_leader_target_locked(target, engaged=engaged)
            self.updated_at = time.monotonic()

    def update_leader_target_focus_from_attack(self, attacker_name: str, victim_name: str) -> bool:
        with self.lock:
            if self.leader_target_id <= 0:
                return False

            normalized_attacker = normalize_target_name(attacker_name)
            normalized_target = normalize_target_name(self.leader_target_name)
            if not normalized_attacker or not normalized_target:
                return False

            if normalized_attacker != normalized_target and normalized_attacker not in normalized_target and normalized_target not in normalized_attacker:
                return False

            if victim_name not in self.member_names:
                return False

            self.leader_target_focus_name = victim_name
            self.leader_target_focus_updated_at = time.monotonic()
            self.updated_at = self.leader_target_focus_updated_at
            return True

    def _update_member_locked(self, member_name: str, client) -> None:
        if member_name not in self.managed_member_names:
            return

        self._update_member_actor_locked(member_name, client, managed=True)

    def update_member(self, member_name: str, client) -> None:
        with self.lock:
            self._update_member_locked(member_name, client)
            self.updated_at = time.monotonic()

    def update_external_member(self, member_name: str, actor, *, role: str = "external") -> None:
        with self.lock:
            self._update_member_actor_locked(member_name, actor, managed=False, role=role)
            self.updated_at = time.monotonic()

    def update_member_role(self, member_name: str, role: str) -> None:
        with self.lock:
            if self._ensure_member_locked(member_name, managed=member_name in self.managed_member_names, role=role):
                self.member_roles[member_name] = role
            self.updated_at = time.monotonic()

    def update_member_condition(self, member_name: str, condition: PlayerConditionSnapshot) -> None:
        with self.lock:
            if member_name not in self.member_names:
                return

            self.member_conditions[member_name] = condition
            if condition.object_id > 0:
                self.member_object_ids[member_name] = condition.object_id
            if not condition.is_alive:
                self.member_health_percents[member_name] = 0
            elif condition.health_percent >= 0:
                self.member_health_percents[member_name] = int(condition.health_percent)
            if condition.x or condition.y or condition.z:
                self.member_positions[member_name] = (int(condition.x), int(condition.y), int(condition.z))
            if normalize_target_name(member_name) == normalize_target_name(self.leader_name):
                if condition.object_id > 0:
                    self.leader_object_id = condition.object_id
                if condition.x or condition.y or condition.z:
                    self.leader_x = int(condition.x)
                    self.leader_y = int(condition.y)
                    self.leader_z = int(condition.z)
                if not condition.is_alive:
                    self.leader_health_percent = 0
                elif condition.health_percent >= 0:
                    self.leader_health_percent = int(condition.health_percent)
                if condition.target_object_id > 0:
                    self._update_leader_target_locked(
                        SimpleNamespace(
                            object_id=condition.target_object_id,
                            name=condition.target_name or "leader target",
                            x=0,
                            y=0,
                            z=0,
                            level=0,
                            health=0,
                            max_health=0,
                            health_percent=0,
                            target_can_attack=condition.target_can_attack,
                            target_relation=condition.target_relation,
                            target_type=condition.target_type,
                            target="",
                        ),
                        engaged=condition.in_combat,
                    )
                else:
                    self._clear_leader_target_locked()
            self.updated_at = time.monotonic()

    def _is_tank_role_locked(self, member_name: str) -> bool:
        role = self.member_roles.get(member_name, "")
        tank_roles = {"melee-basic", "melee-burst", "hybrid"}
        if member_name == self.leader_name:
            return role in {"", "external"} or role in tank_roles
        return role in tank_roles

    def _tank_role_priority_locked(self, member_name: str) -> int:
        role = self.member_roles.get(member_name, "")
        if role == "melee-basic":
            return 0
        if role == "hybrid":
            return 1
        if role == "melee-burst":
            return 2
        if member_name == self.leader_name and role in {"", "external"}:
            return 1
        return 3

    def _is_external_melee_burst_locked(self, member_name: str) -> bool:
        return member_name in self.external_member_names and self.member_roles.get(member_name, "") == "melee-burst"

    def _is_dedicated_tank_candidate_locked(self, member_name: str) -> bool:
        role = self.member_roles.get(member_name, "")
        if member_name == self.leader_name:
            return role in {"", "external", "melee-basic", "hybrid"}
        return role in {"melee-basic", "hybrid"}

    def _active_tank_emergency_handoff_threshold_locked(self) -> int:
        handoff_threshold = self.active_tank_handoff_health_percent
        if handoff_threshold <= 0:
            return 0

        return max(35, min(60, int(handoff_threshold * 0.65)))

    def _active_tank_locked(self) -> dict[str, int | str]:
        candidates: list[tuple[int, int, str, int, int, int, int]] = []

        for order, member_name in enumerate(self.member_names):
            object_id = self.member_object_ids.get(member_name, 0)
            health_percent = self.member_health_percents.get(member_name, 0)

            if not object_id or health_percent <= 0 or not self._is_tank_role_locked(member_name):
                continue

            x, y, z = self.member_positions.get(member_name, (0, 0, 0))
            priority = 0 if member_name == self.leader_name else 1
            candidates.append((priority, order, member_name, object_id, health_percent, x, y, z))

        if not candidates:
            return {"name": "", "object_id": 0, "health_percent": 0, "x": 0, "y": 0, "z": 0}

        dedicated_tank_available = any(
            self._is_dedicated_tank_candidate_locked(member_name)
            for _priority, _order, member_name, _object_id, _health_percent, _x, _y, _z in candidates
        )
        handoff_threshold = self.active_tank_handoff_health_percent
        healthy_tank_available = handoff_threshold > 0 and any(
            member_name != self.leader_name and health_percent > 0
            for _priority, _order, member_name, _object_id, health_percent, _x, _y, _z in candidates
        )
        emergency_handoff_threshold = self._active_tank_emergency_handoff_threshold_locked()
        healthy_backup_tank_available = emergency_handoff_threshold > 0 and any(
            member_name != self.leader_name
            and health_percent > emergency_handoff_threshold
            for _priority, _order, member_name, _object_id, health_percent, _x, _y, _z in candidates
        )

        _, _, _, _, _, _, member_name, object_id, health_percent, x, y, z = min(
            (
                (
                    1 if dedicated_tank_available and self._is_external_melee_burst_locked(member_name) else 0,
                    1
                    if healthy_backup_tank_available
                    and health_percent <= emergency_handoff_threshold
                    else 0,
                    1
                    if healthy_tank_available
                    and member_name == self.leader_name
                    and health_percent <= handoff_threshold
                    else 0,
                    priority,
                    self._tank_role_priority_locked(member_name),
                    order,
                    member_name,
                    object_id,
                    health_percent,
                    x,
                    y,
                    z,
                )
                for priority, order, member_name, object_id, health_percent, x, y, z in candidates
            )
        )
        return {
            "name": member_name,
            "object_id": object_id,
            "health_percent": health_percent,
            "x": x,
            "y": y,
            "z": z,
        }

    def _rescue_tank_locked(self) -> dict[str, int | str]:
        candidates: list[tuple[int, int, str, int, int, int, int]] = []

        for order, member_name in enumerate(self.member_names):
            object_id = self.member_object_ids.get(member_name, 0)
            health_percent = self.member_health_percents.get(member_name, 0)

            if not object_id or health_percent <= 0 or not self._is_tank_role_locked(member_name):
                continue

            x, y, z = self.member_positions.get(member_name, (0, 0, 0))
            priority = 1 if member_name == self.leader_name else 0
            candidates.append((priority, order, member_name, object_id, health_percent, x, y, z))

        if not candidates:
            return {"name": "", "object_id": 0, "health_percent": 0, "x": 0, "y": 0, "z": 0}

        dedicated_tank_available = any(
            self._is_dedicated_tank_candidate_locked(member_name)
            for _priority, _order, member_name, _object_id, _health_percent, _x, _y, _z in candidates
        )
        _, _, _, member_name, object_id, health_percent, x, y, z = min(
            (
                (
                    1 if dedicated_tank_available and self._is_external_melee_burst_locked(member_name) else 0,
                    priority,
                    order,
                    member_name,
                    object_id,
                    health_percent,
                    x,
                    y,
                    z,
                )
                for priority, order, member_name, object_id, health_percent, x, y, z in candidates
            )
        )
        return {
            "name": member_name,
            "object_id": object_id,
            "health_percent": health_percent,
            "x": x,
            "y": y,
            "z": z,
        }

    def active_tank(self) -> dict[str, int | str]:
        with self.lock:
            return self._active_tank_locked()

    def rescue_tank(self) -> dict[str, int | str]:
        with self.lock:
            return self._rescue_tank_locked()

    def lowest_hurt_member(
        self,
        max_health_percent: int,
        exclude_name: str = "",
        exclude_names: frozenset[str] | None = None,
    ) -> dict[str, int | str] | None:
        with self.lock:
            candidates: list[tuple[int, str, int, int, int, int]] = []

            for member_name in self.member_names:
                if member_name == exclude_name:
                    continue
                if exclude_names and normalize_target_name(member_name) in exclude_names:
                    continue

                object_id = self.member_object_ids.get(member_name, 0)
                health_percent = self.member_health_percents.get(member_name, 100)

                if object_id and 0 < health_percent <= max_health_percent:
                    x, y, z = self.member_positions.get(member_name, (0, 0, 0))
                    candidates.append((health_percent, member_name, object_id, x, y, z))

            if not candidates:
                return None

            health_percent, member_name, object_id, x, y, z = min(candidates)
            return {
                "name": member_name,
                "object_id": object_id,
                "health_percent": health_percent,
                "x": x,
                "y": y,
                "z": z,
            }

    def focused_hurt_member(
        self,
        max_health_percent: int,
        exclude_name: str = "",
        exclude_names: frozenset[str] | None = None,
    ) -> dict[str, int | str] | None:
        with self.lock:
            focus_name = normalize_target_name(self.leader_target_focus_name)
            if not focus_name:
                return None

            for member_name in self.member_names:
                if member_name == exclude_name or normalize_target_name(member_name) != focus_name:
                    continue
                if exclude_names and normalize_target_name(member_name) in exclude_names:
                    continue

                object_id = self.member_object_ids.get(member_name, 0)
                health_percent = self.member_health_percents.get(member_name, 100)
                if object_id and 0 < health_percent <= max_health_percent:
                    x, y, z = self.member_positions.get(member_name, (0, 0, 0))
                    return {
                        "name": member_name,
                        "object_id": object_id,
                        "health_percent": health_percent,
                        "x": x,
                        "y": y,
                        "z": z,
                    }

            return None

    def buff_targets(self, exclude_name: str = "") -> list[dict[str, int | str]]:
        with self.lock:
            targets: list[dict[str, int | str]] = []

            for member_name in self.member_names:
                if member_name == exclude_name:
                    continue

                object_id = self.member_object_ids.get(member_name, 0)

                if object_id:
                    targets.append({"name": member_name, "object_id": object_id})

            return targets

    def resurrection_targets(self, exclude_name: str = "") -> list[dict[str, int | str]]:
        with self.lock:
            candidates: list[tuple[int, int, str, int, int, int, int]] = []

            for order, member_name in enumerate(self.member_names):
                if member_name == exclude_name:
                    continue

                object_id = self.member_object_ids.get(member_name, 0)
                health_percent = self.member_health_percents.get(member_name, 100)
                if not object_id or health_percent > 0:
                    continue

                x, y, z = self.member_positions.get(member_name, (0, 0, 0))
                leader_priority = 0 if member_name == self.leader_name else 1
                candidates.append((leader_priority, order, member_name, object_id, health_percent, x, y, z))

            return [
                {
                    "name": member_name,
                    "object_id": object_id,
                    "health_percent": health_percent,
                    "x": x,
                    "y": y,
                    "z": z,
                }
                for leader_priority, order, member_name, object_id, health_percent, x, y, z in sorted(candidates)
            ]

    def request_rescue(
        self,
        member_name: str,
        attacker,
        leader_target_id: int = 0,
        min_hold: float = 0.0,
        objective_add: bool = False,
    ) -> bool:
        attacker_id = int(getattr(attacker, "object_id", 0) or 0)

        if not attacker_id or attacker_id == leader_target_id:
            return False

        with self.lock:
            if member_name not in self.member_names:
                return False

            now = time.monotonic()
            if (
                self.rescue_target_id
                and self.rescue_target_id != attacker_id
                and min_hold > 0
                and now - self.rescue_requested_at < min_hold
            ):
                self._record_rescue_threat_locked(member_name, attacker, objective_add=objective_add, now=now)
                self.updated_at = now
                return False

            if self.rescue_target_id == attacker_id:
                self.rescue_target_name = str(getattr(attacker, "name", ""))
                self.rescue_target_x = int(getattr(attacker, "x", 0) or 0)
                self.rescue_target_y = int(getattr(attacker, "y", 0) or 0)
                self.rescue_target_z = int(getattr(attacker, "z", 0) or 0)
                self.rescue_target_level = int(getattr(attacker, "level", 0) or 0)
                self.rescue_target_objective_add = self.rescue_target_objective_add or objective_add
                self.rescue_member_name = member_name
                if self.rescue_requested_at <= 0.0:
                    self.rescue_requested_at = now
                self._record_rescue_threat_locked(member_name, attacker, objective_add=objective_add, now=now)
                self.updated_at = now
                return True

            self.rescue_target_id = attacker_id
            self.rescue_target_name = str(getattr(attacker, "name", ""))
            self.rescue_target_x = int(getattr(attacker, "x", 0) or 0)
            self.rescue_target_y = int(getattr(attacker, "y", 0) or 0)
            self.rescue_target_z = int(getattr(attacker, "z", 0) or 0)
            self.rescue_target_level = int(getattr(attacker, "level", 0) or 0)
            self.rescue_target_objective_add = objective_add
            self.rescue_member_name = member_name
            self.rescue_requested_at = now
            self._record_rescue_threat_locked(member_name, attacker, objective_add=objective_add, now=now)
            self.updated_at = self.rescue_requested_at
            return True

    def _record_rescue_threat_locked(
        self,
        member_name: str,
        attacker,
        objective_add: bool = False,
        now: float | None = None,
    ) -> bool:
        attacker_id = int(getattr(attacker, "object_id", 0) or 0)
        if not attacker_id:
            return False

        now = time.monotonic() if now is None else now
        self.rescue_threats[attacker_id] = {
            "object_id": attacker_id,
            "name": str(getattr(attacker, "name", "")),
            "x": int(getattr(attacker, "x", 0) or 0),
            "y": int(getattr(attacker, "y", 0) or 0),
            "z": int(getattr(attacker, "z", 0) or 0),
            "level": int(getattr(attacker, "level", 0) or 0),
            "member_name": member_name,
            "requested_at": now,
            "objective_add": bool(objective_add),
        }
        return True

    def record_rescue_threat(self, member_name: str, attacker, objective_add: bool = False) -> bool:
        with self.lock:
            if member_name not in self.member_names:
                return False

            recorded = self._record_rescue_threat_locked(member_name, attacker, objective_add=objective_add)
            if recorded:
                self.updated_at = time.monotonic()
            return recorded

    def clear_rescue_target(self, target_id: int = 0) -> None:
        with self.lock:
            if target_id and self.rescue_target_id != target_id:
                return

            self.rescue_target_id = 0
            self.rescue_target_name = ""
            self.rescue_target_x = 0
            self.rescue_target_y = 0
            self.rescue_target_z = 0
            self.rescue_target_level = 0
            self.rescue_target_objective_add = False
            self.rescue_member_name = ""
            self.rescue_requested_at = 0.0
            if target_id:
                self.rescue_threats.pop(target_id, None)
            self.updated_at = time.monotonic()

    def mark_leader_target_engaged(self, target_id: int) -> None:
        with self.lock:
            if self.leader_target_id == target_id and self.leader_target_engaged_at <= 0.0:
                self.leader_target_engaged_at = time.monotonic()
            self.updated_at = time.monotonic()

    def _clear_leader_target_locked(self) -> None:
        self.leader_target_id = 0
        self.leader_target_name = ""
        self.leader_target_x = 0
        self.leader_target_y = 0
        self.leader_target_z = 0
        self.leader_target_health_percent = 0.0
        self.leader_target_health = 0
        self.leader_target_max_health = 0
        self.leader_target_can_attack = None
        self.leader_target_relation = ""
        self.leader_target_type = ""
        self.leader_target_updated_at = 0.0
        self.leader_target_engaged_at = 0.0
        self.leader_target_focus_name = ""
        self.leader_target_focus_updated_at = 0.0
        self.updated_at = time.monotonic()

    def clear_leader_target(self) -> None:
        with self.lock:
            self._clear_leader_target_locked()

    def clear_leader_target_if_match(self, target_id: int) -> bool:
        target_id = int(target_id or 0)
        if target_id <= 0:
            return False

        with self.lock:
            if self.leader_target_id != target_id:
                return False
            self._clear_leader_target_locked()
            return True

    def mark_objective_complete(self, target_id: int, target_name: str = "") -> None:
        with self.lock:
            if self.objective_completed_at <= 0.0:
                self.objective_completed_at = time.monotonic()
                self.objective_complete_target_id = int(target_id or 0)
                self.objective_complete_name = str(target_name or "")

            self.leader_target_id = 0
            self.leader_target_name = ""
            self.leader_target_x = 0
            self.leader_target_y = 0
            self.leader_target_z = 0
            self.leader_target_health_percent = 0.0
            self.leader_target_health = 0
            self.leader_target_max_health = 0
            self.leader_target_can_attack = None
            self.leader_target_relation = ""
            self.leader_target_type = ""
            self.leader_target_updated_at = 0.0
            self.leader_target_engaged_at = 0.0
            self.leader_target_focus_name = ""
            self.leader_target_focus_updated_at = 0.0
            self.rescue_target_id = 0
            self.rescue_target_name = ""
            self.rescue_target_x = 0
            self.rescue_target_y = 0
            self.rescue_target_z = 0
            self.rescue_target_level = 0
            self.rescue_target_objective_add = False
            self.rescue_member_name = ""
            self.rescue_requested_at = 0.0
            self.rescue_threats.clear()
            self.updated_at = time.monotonic()

    def clear_objective_complete(self) -> None:
        with self.lock:
            self.objective_complete_target_id = 0
            self.objective_complete_name = ""
            self.objective_completed_at = 0.0
            self.updated_at = time.monotonic()

    def mark_ready(self, member_name: str) -> None:
        with self.lock:
            if member_name in self.managed_member_names:
                self.ready_names.add(member_name)
            self.updated_at = time.monotonic()

    def mark_invited(self, member_name: str) -> None:
        with self.lock:
            if member_name in self.managed_member_names and member_name != self.leader_name:
                self.invited_names.add(member_name)
            self.updated_at = time.monotonic()

    def member_has_invite(self, member_name: str) -> bool:
        with self.lock:
            return member_name in self.invited_names

    def mark_accepted(self, member_name: str) -> None:
        with self.lock:
            if member_name in self.managed_member_names:
                self.accepted_names.add(member_name)
            self.updated_at = time.monotonic()

    def member_has_accepted(self, member_name: str) -> bool:
        with self.lock:
            return member_name in self.accepted_names

    def clear_ready(self, member_name: str) -> None:
        with self.lock:
            if member_name != self.leader_name:
                self.ready_names.discard(member_name)
            self.updated_at = time.monotonic()

    def managed_invite_names(self) -> list[str]:
        with self.lock:
            return [member_name for member_name in self.managed_member_names if member_name != self.leader_name]

    def snapshot(self) -> dict[str, int | float | str]:
        with self.lock:
            active_tank = self._active_tank_locked()
            rescue_tank = self._rescue_tank_locked()
            managed_member_names = list(self.managed_member_names)
            external_member_names = list(self.external_member_names)
            return {
                "leader_name": self.leader_name,
                "leader_session_id": self.leader_session_id,
                "leader_object_id": self.leader_object_id,
                "leader_x": self.leader_x,
                "leader_y": self.leader_y,
                "leader_z": self.leader_z,
                "leader_heading": self.leader_heading,
                "leader_health_percent": self.leader_health_percent,
                "leader_target_id": self.leader_target_id,
                "leader_target_name": self.leader_target_name,
                "leader_target_x": self.leader_target_x,
                "leader_target_y": self.leader_target_y,
                "leader_target_z": self.leader_target_z,
                "leader_target_health_percent": self.leader_target_health_percent,
                "leader_target_health": self.leader_target_health,
                "leader_target_max_health": self.leader_target_max_health,
                "leader_target_can_attack": self.leader_target_can_attack,
                "leader_target_relation": self.leader_target_relation,
                "leader_target_type": self.leader_target_type,
                "leader_target_updated_at": self.leader_target_updated_at,
                "leader_target_engaged_at": self.leader_target_engaged_at,
                "leader_target_focus_name": self.leader_target_focus_name,
                "leader_target_focus_updated_at": self.leader_target_focus_updated_at,
                "objective_complete_target_id": self.objective_complete_target_id,
                "objective_complete_name": self.objective_complete_name,
                "objective_completed_at": self.objective_completed_at,
                "active_tank_name": active_tank["name"],
                "active_tank_object_id": active_tank["object_id"],
                "active_tank_health_percent": active_tank["health_percent"],
                "active_tank_x": active_tank["x"],
                "active_tank_y": active_tank["y"],
                "active_tank_z": active_tank["z"],
                "rescue_tank_name": rescue_tank["name"],
                "rescue_tank_object_id": rescue_tank["object_id"],
                "rescue_tank_health_percent": rescue_tank["health_percent"],
                "rescue_tank_x": rescue_tank["x"],
                "rescue_tank_y": rescue_tank["y"],
                "rescue_tank_z": rescue_tank["z"],
                "rescue_target_id": self.rescue_target_id,
                "rescue_target_name": self.rescue_target_name,
                "rescue_target_x": self.rescue_target_x,
                "rescue_target_y": self.rescue_target_y,
                "rescue_target_z": self.rescue_target_z,
                "rescue_target_level": self.rescue_target_level,
                "rescue_target_objective_add": self.rescue_target_objective_add,
                "rescue_member_name": self.rescue_member_name,
                "rescue_requested_at": self.rescue_requested_at,
                "rescue_threats": list(self.rescue_threats.values()),
                "managed_member_names": managed_member_names,
                "external_member_names": external_member_names,
                "invited_names": list(self.invited_names),
                "accepted_names": list(self.accepted_names),
                "members": [
                    {
                        "name": member_name,
                        "object_id": self.member_object_ids.get(member_name, 0),
                        "health_percent": self.member_health_percents.get(member_name, 0),
                        "x": self.member_positions.get(member_name, (0, 0, 0))[0],
                        "y": self.member_positions.get(member_name, (0, 0, 0))[1],
                        "z": self.member_positions.get(member_name, (0, 0, 0))[2],
                        "role": self.member_roles.get(member_name, ""),
                    }
                    for member_name in self.member_names
                ],
                "ready_names": list(self.ready_names),
                "encounter_death_count": self.encounter_death_count,
                "last_encounter_death_at": self.last_encounter_death_at,
                "ready_count": len(self.ready_names),
                "updated_at": self.updated_at,
            }


def party_ready_for_pull(args: argparse.Namespace, party_state: PartyState | None) -> bool:
    if party_state is None or getattr(args, "party_min_ready", 0) <= 0:
        return True

    snapshot = party_state.snapshot()
    max_leader_distance = float(getattr(args, "party_ready_max_leader_distance", 0.0) or 0.0)
    if max_leader_distance <= 0.0:
        return int(snapshot["ready_count"]) >= args.party_min_ready

    ready_names = set(snapshot.get("ready_names", []) or [])
    leader_name = str(snapshot.get("leader_name", "") or "")
    leader_x = int(snapshot.get("leader_x", 0) or 0)
    leader_y = int(snapshot.get("leader_y", 0) or 0)
    near_ready_count = 1 if leader_name in ready_names else 0
    for member in snapshot.get("members", []) or []:
        member_name = str(member.get("name", "") or "")
        if member_name == leader_name or member_name not in ready_names:
            continue
        if int(member.get("object_id", 0) or 0) <= 0 or int(member.get("health_percent", 0) or 0) <= 0:
            continue
        distance = horizontal_distance_between_points(
            leader_x,
            leader_y,
            int(member.get("x", 0) or 0),
            int(member.get("y", 0) or 0),
        )
        if distance <= max_leader_distance:
            near_ready_count += 1

    return near_ready_count >= args.party_min_ready


def party_form_up_timeout_seconds(args: argparse.Namespace) -> float:
    return max(0.0, float(getattr(args, "party_form_up_timeout", 0.0) or 0.0))


def party_form_up_force_pull_active(
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    party_forming_since: float,
    now: float,
) -> bool:
    if party_state is None or party_ready_for_pull(args, party_state):
        return False

    timeout = party_form_up_timeout_seconds(args)
    if timeout <= 0.0 or party_forming_since <= 0.0:
        return False

    return now - party_forming_since >= timeout


def effective_party_ready_for_pull(
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    party_forming_since: float = 0.0,
    now: float = 0.0,
) -> bool:
    if party_ready_for_pull(args, party_state):
        return True

    return party_form_up_force_pull_active(
        args,
        party_state,
        party_forming_since=party_forming_since,
        now=now,
    )


def party_ready_count(party_state: PartyState | None) -> int:
    if party_state is None:
        return 0

    return int(party_state.snapshot()["ready_count"])


def party_member_ready_for_pull(client, args: argparse.Namespace) -> bool:
    if required_target_home_destination(args) is None:
        return True

    if required_target_home_reached(client, args):
        return True

    if (
        int(getattr(args, "party_size", 0) or 0) > 1
        and getattr(args, "party_assist_only", False)
        and float(getattr(args, "party_pre_pull_home_stop_distance", 0.0) or 0.0) > 0.0
    ):
        hunt_distance = float(getattr(args, "required_target_home_hunt_distance", 0.0) or 0.0)
        if hunt_distance <= 0.0:
            hunt_distance = float(getattr(args, "target_home_max_distance", 0.0) or 0.0)
        if hunt_distance > 0.0 and required_target_home_distance(client, args) <= hunt_distance:
            return True

    return required_target_home_hunt_ready(client, args)


def should_mark_party_ready_after_follow(
    client,
    args: argparse.Namespace,
    *,
    is_party_follower: bool,
    current_target: int,
) -> bool:
    return bool(is_party_follower and party_member_ready_for_pull(client, args))


def should_start_party_form_up_delay(
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    is_party_leader: bool,
    current_target: int,
    party_forming_since: float = 0.0,
    now: float = 0.0,
) -> bool:
    if not should_approach_required_target_home(
        args,
        is_party_leader=is_party_leader,
        current_target=current_target,
    ):
        return False

    if int(getattr(args, "party_min_ready", 0) or 0) <= 0:
        return False

    if party_form_up_force_pull_active(
        args,
        party_state,
        party_forming_since=party_forming_since,
        now=now,
    ):
        return True

    return bool(
        effective_party_ready_for_pull(
            args,
            party_state,
            party_forming_since=party_forming_since,
            now=now,
        )
        and float(getattr(args, "party_form_up_delay", 0.0) or 0.0) > 0.0
    )


def should_suppress_party_follower_waypoint(
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    is_party_follower: bool,
    current_target: int,
) -> bool:
    return bool(
        is_party_follower
        and party_state is not None
        and current_target <= 0
        and getattr(args, "party_assist_only", False)
        and int(getattr(args, "party_min_ready", 0) or 0) > 0
    )


def should_defer_objective_move_until_follow_anchor(
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    is_party_follower: bool,
    current_target: int,
    follow_player_last_visible_at: float,
    now: float,
) -> bool:
    if not getattr(args, "follow_player_required_for_objective_move", False):
        return False
    if current_target > 0:
        return False
    if not getattr(args, "follow_nearby_player", False) and not is_party_follower:
        return False

    max_age = max(
        1.0,
        float(getattr(args, "player_state_max_age", 0.0) or 0.0),
        float(getattr(args, "party_state_max_age", 0.0) or 0.0),
        float(getattr(args, "player_follow_interval", 0.0) or 0.0) * 4.0,
    )

    if is_party_follower and party_state is not None:
        snapshot = party_state.snapshot()
        if party_leader_anchor_position_valid(snapshot):
            updated_at = float(snapshot.get("updated_at", 0.0) or 0.0)
            if updated_at <= 0.0 or now - updated_at <= max_age:
                return False

    return follow_player_last_visible_at <= 0.0 or now - follow_player_last_visible_at > max_age


def follow_anchor_wait_destination(args: argparse.Namespace, client=None) -> MovementDestination | None:
    home = getattr(args, "flee_home", None)
    if home is not None:
        danger = required_target_home_destination(args)
        if client is not None and danger is not None:
            danger_radius = max(
                4500.0,
                float(getattr(args, "flee_safe_threat_radius", 0.0) or 0.0),
                float(getattr(args, "target_home_max_distance", 0.0) or 0.0),
                float(getattr(args, "required_target_home_hunt_distance", 0.0) or 0.0),
                float(getattr(args, "combat_home_leash_distance", 0.0) or 0.0),
            )
            distance_to_danger = horizontal_distance_between_points(client.x, client.y, danger.x, danger.y)
            if distance_to_danger > danger_radius:
                return None
        return destination_from_point("follow-anchor-wait", home.x, home.y, home.z)
    return flee_escape_destination(args, client)


def should_defer_required_home_move_for_party_anchor(
    client,
    args: argparse.Namespace,
    party_state: PartyState | None,
    *,
    is_party_follower: bool,
    current_target: int,
    member_name: str = "",
    action_rotation: str = "",
) -> bool:
    if (
        not is_party_follower
        or party_state is None
        or current_target > 0
        or not getattr(args, "party_assist_only", False)
        or (
            int(getattr(args, "party_min_ready", 0) or 0) <= 0
            and not getattr(args, "party_require_leader_engaged", False)
        )
    ):
        return False

    home = required_target_home_destination(args)
    if home is None:
        return False

    snapshot = party_state.snapshot()
    if not party_anchor_position_valid(snapshot, member_name=member_name):
        return False

    if (
        int(snapshot.get("leader_target_id", 0) or 0) > 0
        and float(snapshot.get("leader_target_engaged_at", 0.0) or 0.0) > 0.0
    ):
        if str(action_rotation or "") == "healer-support":
            return False
        return True

    anchor = party_anchor_from_snapshot(snapshot, member_name=member_name)
    anchor_home_distance = horizontal_distance_between_points(
        int(anchor.get("x", 0) or 0),
        int(anchor.get("y", 0) or 0),
        home.x,
        home.y,
    )
    anchor_near_home_distance = max(
        float(getattr(args, "party_pre_pull_home_stop_distance", 0.0) or 0.0),
        float(getattr(args, "required_target_home_stop_distance", 0.0) or 0.0),
        float(getattr(args, "party_follow_distance", 0.0) or 0.0),
    )
    if anchor_home_distance <= anchor_near_home_distance:
        return False

    return True


def initial_behavior_state_for_objective(
    client,
    args: argparse.Namespace,
    *,
    is_party_leader: bool,
    current_target: int,
) -> DummyBehaviorState:
    if current_target > 0:
        return DummyBehaviorState.HuntObjective

    if required_target_home_destination(args) is None:
        return DummyBehaviorState.HuntObjective

    if is_party_leader or int(getattr(args, "party_size", 0) or 0) == 1:
        if should_approach_required_target_home(
            args,
            is_party_leader=is_party_leader,
            current_target=current_target,
        ) and not required_target_home_hunt_ready(client, args):
            return DummyBehaviorState.TravelToObjective
        return DummyBehaviorState.HuntObjective

    return DummyBehaviorState.TravelToObjective


def character_name_from_account(username: str) -> str:
    if username.lower().startswith("dummy"):
        return "Dummy" + username[5:]

    return username[:1].upper() + username[1:]


def expand_startup_command(command: str, account: DummyAccount) -> str:
    character = account.character_name or character_name_from_account(account.username)
    return (
        command.replace("{character}", character)
        .replace("{account}", account.username)
        .replace("{CHARACTER}", character)
        .replace("{ACCOUNT}", account.username)
    )


def probable_account_from_character_name(character_name: str) -> str:
    name = str(character_name or "").strip()
    if not name:
        return ""
    return name.lower()


def choose_hunter_target(
    client,
    rng: random.Random,
    args: argparse.Namespace,
    rejected_targets: dict[int, float],
    rejected_target_kinds: dict[tuple[str, int], float],
    now: float,
):
    max_level = args.max_target_level if args.max_target_level >= 0 else args.player_level + args.max_target_level_delta
    ideal_level = args.ideal_target_level or args.player_level
    prefer_tokens = [token.strip().lower() for token in args.prefer_target_name.split(",") if token.strip()]
    require_tokens = [token.strip().lower() for token in getattr(args, "require_target_name", "").split(",") if token.strip()]
    avoid_tokens = [token.strip().lower() for token in args.avoid_target_name.split(",") if token.strip()]
    target_home = getattr(args, "required_target_home", None)
    target_home_max_distance = float(getattr(args, "target_home_max_distance", 0.0) or 0.0)

    def within_target_home(npc) -> bool:
        if target_home is None or target_home_max_distance <= 0.0:
            return True

        return (
            horizontal_distance_between_points(
                int(getattr(target_home, "x", 0) or 0),
                int(getattr(target_home, "y", 0) or 0),
                int(getattr(npc, "x", 0) or 0),
                int(getattr(npc, "y", 0) or 0),
            )
            <= target_home_max_distance
        )

    def is_avoided(npc) -> bool:
        return any(token in npc.name.lower() for token in avoid_tokens)

    def ground_z_ok(npc) -> bool:
        return hunter_target_ground_z_aligned(args, client, npc)

    def candidate_npcs(*, allow_avoided: bool) -> list[object]:
        return [
            npc
            for npc in client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
            if rejected_targets.get(npc.object_id, 0.0) <= now
            and rejected_target_kinds.get((npc.name.lower(), npc.level), 0.0) <= now
            and npc.level >= args.min_target_level
            and npc.level <= max_level
            and (args.max_target_distance <= 0 or combat_distance_to(client, npc) <= args.max_target_distance)
            and within_target_home(npc)
            and (not require_tokens or any(token in npc.name.lower() for token in require_tokens))
            and ground_z_ok(npc)
            and (allow_avoided or not is_avoided(npc))
        ]

    candidates = candidate_npcs(allow_avoided=False)
    if not candidates and getattr(args, "allow_avoid_target_fallback", False):
        candidates = candidate_npcs(allow_avoided=True)

    if candidates and prefer_tokens and getattr(args, "target_auto_lowest_visible_level", False):
        preferred_candidates = [npc for npc in candidates if any(token in npc.name.lower() for token in prefer_tokens)]
        if preferred_candidates:
            preferred_candidates.sort(key=lambda npc: (npc.level, combat_distance_to(client, npc)))
            return preferred_candidates[0]
        if not preferred_candidates:
            fallback_candidates = [
                npc
                for npc in client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
                if rejected_targets.get(npc.object_id, 0.0) <= now
                and rejected_target_kinds.get((npc.name.lower(), npc.level), 0.0) <= now
                and npc.level >= args.min_target_level
                and npc.level <= max_level
                and (args.max_target_distance <= 0 or combat_distance_to(client, npc) <= args.max_target_distance)
                and within_target_home(npc)
                and (not require_tokens or any(token in npc.name.lower() for token in require_tokens))
                and ground_z_ok(npc)
                and not any(token in npc.name.lower() for token in avoid_tokens)
            ]
            if fallback_candidates:
                fallback_candidates.sort(key=lambda npc: (npc.level, combat_distance_to(client, npc)))
                return fallback_candidates[0]

    if not candidates:
        if not getattr(args, "target_auto_lowest_visible_level", False):
            return None

        fallback_candidates = [
            npc
            for npc in client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
            if rejected_targets.get(npc.object_id, 0.0) <= now
            and rejected_target_kinds.get((npc.name.lower(), npc.level), 0.0) <= now
            and npc.level >= args.min_target_level
            and npc.level <= max_level
            and (args.max_target_distance <= 0 or combat_distance_to(client, npc) <= args.max_target_distance)
            and within_target_home(npc)
            and (not require_tokens or any(token in npc.name.lower() for token in require_tokens))
            and ground_z_ok(npc)
            and not any(token in npc.name.lower() for token in avoid_tokens)
        ]

        if not fallback_candidates:
            if getattr(args, "allow_preferred_low_con_fallback", False) and prefer_tokens:
                preferred_low_con_candidates = [
                    npc
                    for npc in client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
                    if rejected_targets.get(npc.object_id, 0.0) <= now
                    and rejected_target_kinds.get((npc.name.lower(), npc.level), 0.0) <= now
                    and any(token in npc.name.lower() for token in prefer_tokens)
                    and preferred_low_con_fallback_allowed(args, client, npc)
                    and (not require_tokens or any(token in npc.name.lower() for token in require_tokens))
                    and ground_z_ok(npc)
                    and not any(token in npc.name.lower() for token in avoid_tokens)
                ]
                if preferred_low_con_candidates:
                    preferred_low_con_candidates.sort(key=lambda npc: (combat_distance_to(client, npc), npc.level))
                    return preferred_low_con_candidates[0]
            return None

        fallback_candidates.sort(key=lambda npc: (npc.level, combat_distance_to(client, npc)))
        return fallback_candidates[0]

    nearest_candidates = sorted(candidates, key=lambda npc: combat_distance_to(client, npc))
    pool = nearest_candidates[: max(args.target_pool, 1)]

    if args.target_selection == "random":
        return rng.choice(pool)

    def score(npc) -> float:
        distance = combat_distance_to(client, npc)
        level_delta = abs(npc.level - ideal_level)
        value = 1000.0
        value -= level_delta * args.target_level_weight
        value -= distance / max(args.target_distance_weight, 1.0)

        if npc.level < args.min_target_level:
            value -= 500.0

        if prefer_tokens and any(token in npc.name.lower() for token in prefer_tokens):
            value += args.prefer_target_bonus

        if is_avoided(npc):
            value -= args.prefer_target_bonus * 2.0

        value += rng.uniform(0.0, args.target_randomness)
        return value

    if args.target_selection == "nearest":
        return min(pool, key=lambda npc: combat_distance_to(client, npc))

    return max(pool, key=score)


def hunter_target_scan_snapshot(
    client,
    args: argparse.Namespace,
    rejected_targets: dict[int, float],
    rejected_target_kinds: dict[tuple[str, int], float],
    now: float,
    *,
    limit: int = 5,
) -> dict[str, object]:
    max_level = args.max_target_level if args.max_target_level >= 0 else args.player_level + args.max_target_level_delta
    prefer_tokens = [token.strip().lower() for token in args.prefer_target_name.split(",") if token.strip()]
    require_tokens = [token.strip().lower() for token in getattr(args, "require_target_name", "").split(",") if token.strip()]
    avoid_tokens = [token.strip().lower() for token in args.avoid_target_name.split(",") if token.strip()]
    target_home = getattr(args, "required_target_home", None)
    target_home_max_distance = float(getattr(args, "target_home_max_distance", 0.0) or 0.0)
    visible = client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
    counts = {
        "visible": len(visible),
        "rejected_recent": 0,
        "kind_rejected_recent": 0,
        "level": 0,
        "distance": 0,
        "home": 0,
        "require_name": 0,
        "avoid_name": 0,
        "ground_z": 0,
        "eligible": 0,
    }

    def home_distance(npc) -> float:
        if target_home is None:
            return 0.0

        return horizontal_distance_between_points(
            int(getattr(target_home, "x", 0) or 0),
            int(getattr(target_home, "y", 0) or 0),
            int(getattr(npc, "x", 0) or 0),
            int(getattr(npc, "y", 0) or 0),
        )

    def compact(npc, *, reason: str = "") -> dict[str, object]:
        item: dict[str, object] = {
            "id": int(getattr(npc, "object_id", 0) or 0),
            "name": str(getattr(npc, "name", "") or ""),
            "level": int(getattr(npc, "level", 0) or 0),
            "distance": round(combat_distance_to(client, npc), 1),
            "home_distance": round(home_distance(npc), 1),
            "flags": int(getattr(npc, "flags", 0) or 0),
            "x": int(getattr(npc, "x", 0) or 0),
            "y": int(getattr(npc, "y", 0) or 0),
            "z": int(getattr(npc, "z", 0) or 0),
        }
        ground_delta = hunter_target_ground_z_delta(args, client, npc)
        if ground_delta is not None:
            item["ground_z_delta"] = round(ground_delta, 1)
        if reason:
            item["reason"] = reason
        return item

    nearest_visible = [compact(npc) for npc in visible[:limit]]
    eligible = []
    nearest_rejected = []
    for npc in visible:
        reason = ""
        name = npc.name.lower()
        distance = combat_distance_to(client, npc)
        npc_home_distance = home_distance(npc)

        if rejected_targets.get(npc.object_id, 0.0) > now:
            counts["rejected_recent"] += 1
            reason = "rejected_recent"
        elif rejected_target_kinds.get((name, npc.level), 0.0) > now:
            counts["kind_rejected_recent"] += 1
            reason = "kind_rejected_recent"
        elif args.max_target_distance > 0 and distance > args.max_target_distance:
            counts["distance"] += 1
            reason = "distance"
        elif npc.level < args.min_target_level or npc.level > max_level:
            counts["level"] += 1
            reason = "level"
        elif target_home_max_distance > 0 and npc_home_distance > target_home_max_distance:
            counts["home"] += 1
            reason = "home"
        elif require_tokens and not any(token in name for token in require_tokens):
            counts["require_name"] += 1
            reason = "require_name"
        elif any(token in name for token in avoid_tokens):
            counts["avoid_name"] += 1
            reason = "avoid_name"
        elif not hunter_target_ground_z_aligned(args, client, npc):
            counts["ground_z"] += 1
            reason = "ground_z"
        else:
            eligible.append(npc)
            continue

        if len(nearest_rejected) < limit:
            nearest_rejected.append(compact(npc, reason=reason))

    counts["eligible"] = len(eligible)
    return {
        "hunter_visible_npcs": counts["visible"],
        "hunter_eligible_npcs": counts["eligible"],
        "hunter_reject_counts": counts,
        "hunter_nearest_visible": nearest_visible,
        "hunter_nearest_rejected": nearest_rejected,
        "hunter_nearest_eligible": [compact(npc) for npc in sorted(eligible, key=lambda npc: combat_distance_to(client, npc))[:limit]],
        "hunter_prefer_tokens": prefer_tokens,
        "hunter_require_tokens": require_tokens,
        "hunter_avoid_tokens": avoid_tokens,
        "hunter_min_level": int(args.min_target_level),
        "hunter_max_level": int(max_level),
        "hunter_max_distance": float(args.max_target_distance),
        "hunter_home_max_distance": float(target_home_max_distance),
        "hunter_include_peace": bool(should_scan_peace_npcs(args)),
    }


def choose_party_assist_target(npcs, leader_target_id: int):
    if leader_target_id <= 0:
        return None

    return next((npc for npc in npcs if npc.object_id == leader_target_id), None)


def choose_current_visible_target(npcs, current_target: int):
    if current_target <= 0:
        return None

    return next((npc for npc in npcs if npc.object_id == current_target), None)


def classify_combat_server_message(text: str) -> set[str]:
    normalized = text.lower()
    categories: set[str] = set()

    if (
        "사거리" in normalized
        or "너무 멀" in normalized
        or "out of range" in normalized
        or "too far" in normalized
    ):
        categories.add("out_of_range")
    if (
        "보이지" in normalized
        or "시야" in normalized
        or "not visible" in normalized
        or "not in view" in normalized
    ):
        categories.add("not_visible")
    if "피해" in normalized or "damage" in normalized or "hit" in normalized:
        categories.add("damage")
    if (
        "주문이 중단" in normalized
        or "시전이 중단" in normalized
        or "spell was interrupted" in normalized
        or "casting was interrupted" in normalized
        or "you are interrupted" in normalized
    ):
        categories.add("cast_interrupted")
    if (
        "주문을 시전하려면" in normalized
        or "wait before casting" in normalized
        or "must wait" in normalized
    ):
        categories.add("spell_not_ready")
    if (
        "같은 렐름 구성원은 공격할 수 없습니다" in normalized
        or "same realm" in normalized
        or "same realm member" in normalized
    ):
        categories.add("friendly_target")

    return categories


def parse_optional_bool(value) -> bool | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "no", "n", "off"}:
        return False
    return None


def leader_party_assist_target_attackable(
    *,
    target_name: str = "",
    target_can_attack: bool | None = None,
    target_relation: str = "",
    target_type: str = "",
) -> bool:
    del target_type
    normalized_name = normalize_target_name(target_name)
    if normalized_name in {"용병 고용관", "왕국 용병 관리인", "companion hiring officer", "companion steward"}:
        return False

    relation = str(target_relation or "").strip().lower()
    if relation:
        return relation in {"hostile", "enemy"}

    if target_can_attack is not None:
        return bool(target_can_attack)

    # Older in-process party tests do not carry server relation metadata.
    return True


def party_snapshot_leader_target_attackable(party_snapshot: dict[str, object] | None) -> bool:
    if not isinstance(party_snapshot, dict):
        return True
    return leader_party_assist_target_attackable(
        target_name=str(party_snapshot.get("leader_target_name", "") or ""),
        target_can_attack=parse_optional_bool(party_snapshot.get("leader_target_can_attack")),
        target_relation=str(party_snapshot.get("leader_target_relation", "") or ""),
        target_type=str(party_snapshot.get("leader_target_type", "") or ""),
    )


def is_active_target_combat_contact_message(
    active_combat: dict[str, object] | None,
    text: str,
    chat_type: int,
) -> bool:
    if active_combat is None:
        return False

    active_target_name = normalize_target_name(str(active_combat.get("target_name", "") or ""))
    normalized_message = normalize_target_name(text)
    if not active_target_name or active_target_name not in normalized_message:
        return False

    if int(chat_type or 0) == 30:
        return True

    lower = normalized_message.lower()
    return any(token in lower for token in ("miss", "evade", "parry", "block"))


def server_los_failure_count_distance(args: argparse.Namespace, action_rotation: str) -> float:
    if is_melee_rotation(action_rotation):
        return max(
            120.0,
            float(getattr(args, "minimum_melee_stop_distance", 60.0) or 60.0) + 80.0,
            float(getattr(args, "attack_range", 350.0) or 350.0) * 0.4,
        )

    return max(
        float(getattr(args, "attack_range", 350.0) or 350.0),
        float(getattr(args, "spell_range", 1500.0) or 0.0),
    )


def server_los_retry_stop_distance(args: argparse.Namespace, action_rotation: str) -> float:
    if is_melee_rotation(action_rotation):
        return max(24.0, float(getattr(args, "minimum_melee_stop_distance", 60.0) or 60.0) * 0.5)

    return combat_stop_distance(args, action_rotation)


def should_count_server_los_failure(
    combat_categories: set[str],
    *,
    target_distance: float | None = None,
    close_distance: float | None = None,
) -> bool:
    if "not_visible" not in combat_categories:
        return False

    if target_distance is not None and close_distance is not None and close_distance > 0:
        return target_distance <= close_distance

    return True


def choose_required_visible_target(client, npcs, args: argparse.Namespace):
    if not required_target_home_allows_selection(client, args):
        return None

    targets = [
        npc
        for npc in npcs
        if is_required_target(args, npc)
        and target_within_required_home(args, npc)
        and target_within_selection_distance(client, args, npc)
        and required_target_level_allowed(args, npc)
    ]

    if not targets:
        return None

    return min(targets, key=lambda npc: combat_distance_to(client, npc))


def pre_objective_add_target_allowed(
    args: argparse.Namespace,
    client,
    npc,
    *,
    rejected_targets: dict[int, float] | None = None,
    rejected_target_kinds: dict[tuple[str, int], float] | None = None,
    now: float = 0.0,
) -> bool:
    if npc is None:
        return False

    object_id = int(getattr(npc, "object_id", 0) or 0)
    if object_id <= 0:
        return False

    if rejected_targets is not None and rejected_targets.get(object_id, 0.0) > now:
        return False

    name = str(getattr(npc, "name", "") or "").lower()
    level = int(getattr(npc, "level", 0) or 0)
    if rejected_target_kinds is not None and rejected_target_kinds.get((name, level), 0.0) > now:
        return False

    if is_avoid_target(args, npc):
        return False

    if getattr(args, "party_encounter_mode", "standard") == "standard" and not is_objective_add_target(args, npc):
        return False

    if not should_accept_party_rescue_target(args, npc):
        return False

    return hunter_target_ground_z_aligned(args, client, npc)


def choose_pre_objective_add_target(
    npcs,
    client,
    args: argparse.Namespace,
    objective_npc=None,
    *,
    rejected_targets: dict[int, float] | None = None,
    rejected_target_kinds: dict[tuple[str, int], float] | None = None,
    now: float = 0.0,
):
    if not getattr(args, "party_clear_objective_adds_before_engage", False):
        return None

    if objective_npc is not None:
        objective_id = int(getattr(objective_npc, "object_id", 0) or 0)
        objective_x = int(getattr(objective_npc, "x", 0) or 0)
        objective_y = int(getattr(objective_npc, "y", 0) or 0)
    else:
        objective_id = 0
        if required_target_tokens(args):
            return None
        objective_home = getattr(args, "required_target_home", None)
        if objective_home is None:
            return None
        objective_x = int(getattr(objective_home, "x", 0) or 0)
        objective_y = int(getattr(objective_home, "y", 0) or 0)

    max_distance = float(getattr(args, "party_rescue_objective_max_distance", 0.0) or 0.0)
    candidates = [
        npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
        and int(getattr(npc, "object_id", 0) or 0) != objective_id
        and not is_required_target(args, npc)
        and pre_objective_add_target_allowed(
            args,
            client,
            npc,
            rejected_targets=rejected_targets,
            rejected_target_kinds=rejected_target_kinds,
            now=now,
        )
        and (
            max_distance <= 0.0
            or horizontal_distance_between_points(
                objective_x,
                objective_y,
                int(getattr(npc, "x", 0) or 0),
                int(getattr(npc, "y", 0) or 0),
            )
            <= max_distance
        )
    ]

    if not candidates:
        return None

    return min(candidates, key=lambda npc: (combat_distance_to(client, npc), int(getattr(npc, "object_id", 0) or 0)))


def choose_shared_objective_visible_target(client, npcs, args: argparse.Namespace, shared_target_id: int):
    if not required_target_home_allows_selection(client, args):
        return None

    if shared_target_id > 0:
        target = choose_party_assist_target(npcs, shared_target_id)
        if target is None:
            return None

        if (
            target is not None
            and target_within_required_home(args, target)
            and target_within_selection_distance(client, args, target)
        ):
            return target

    return choose_required_visible_target(client, npcs, args)


def should_reacquire_shared_objective_visible_target(
    args: argparse.Namespace,
    party_snapshot: dict[str, object],
    *,
    is_party_follower: bool,
) -> bool:
    if not should_preserve_party_target_on_loss(args):
        return False

    if (
        is_party_follower
        and getattr(args, "party_require_leader_engaged", False)
        and (
            int(party_snapshot.get("leader_target_id", 0) or 0) <= 0
            or float(party_snapshot.get("leader_target_engaged_at", 0.0) or 0.0) <= 0.0
        )
    ):
        return False

    return True


def required_target_level_allowed(args: argparse.Namespace, npc) -> bool:
    if getattr(args, "party_encounter_mode", "standard") != "standard" and is_required_target(args, npc):
        min_level = getattr(args, "min_target_level", None)
        if min_level is not None and int(getattr(npc, "level", 0) or 0) < int(min_level or 0):
            return False
        return True

    has_explicit_level_window = (
        hasattr(args, "min_target_level")
        or hasattr(args, "max_target_level")
        or hasattr(args, "player_level")
        or hasattr(args, "max_target_level_delta")
    )
    return not has_explicit_level_window or passes_hunter_target_level_filter(args, npc)


def required_target_home_allows_selection(client, args: argparse.Namespace) -> bool:
    if required_target_home_destination(args) is None:
        return True

    return required_target_home_reached(client, args) or required_target_home_hunt_ready(client, args)


def target_within_required_home(args: argparse.Namespace, npc) -> bool:
    target_home = getattr(args, "required_target_home", None)
    target_home_max_distance = float(getattr(args, "target_home_max_distance", 0.0) or 0.0)
    if target_home is None or target_home_max_distance <= 0.0:
        return True

    return (
        horizontal_distance_between_points(
            int(getattr(target_home, "x", 0) or 0),
            int(getattr(target_home, "y", 0) or 0),
            int(getattr(npc, "x", 0) or 0),
            int(getattr(npc, "y", 0) or 0),
        )
        <= target_home_max_distance
    )


def target_position_known(npc) -> bool:
    if npc is None:
        return False

    return bool(int(getattr(npc, "x", 0) or 0) or int(getattr(npc, "y", 0) or 0))


def target_within_selection_distance(client, args: argparse.Namespace, npc) -> bool:
    max_distance = float(getattr(args, "max_target_distance", 0.0) or 0.0)
    return max_distance <= 0.0 or combat_distance_to(client, npc) <= max_distance


def combat_tracking_start_distance(args: argparse.Namespace, action_rotation: str) -> float:
    attack_range = float(getattr(args, "attack_range", 350.0) or 350.0)
    direct_move_distance = float(getattr(args, "combat_direct_move_distance", 450.0) or 450.0)
    if is_melee_rotation(action_rotation):
        stick_attack_distance = float(getattr(args, "melee_stick_attack_distance", 0.0) or 0.0)
        melee_stop = max(
            float(getattr(args, "minimum_melee_stop_distance", 70.0) or 70.0),
            attack_range - float(getattr(args, "melee_range_buffer", 250.0) or 250.0),
        )
        melee_distance = max(melee_stop + 25.0, float(getattr(args, "minimum_melee_stop_distance", 70.0) or 70.0))
        if bool(getattr(args, "melee_stick_attack", False)) and stick_attack_distance > 0.0:
            melee_distance = max(melee_distance, stick_attack_distance)
        return melee_distance

    return max(attack_range, direct_move_distance)


def should_start_combat_after_target_commit(
    args: argparse.Namespace,
    distance: float,
    action_rotation: str = "melee-basic",
) -> bool:
    return float(distance or 0.0) <= combat_tracking_start_distance(args, action_rotation)


def should_start_combat_after_required_target_api_retarget(
    args: argparse.Namespace,
    observed,
    *,
    retargeted: bool,
    active_combat,
    distance: float,
) -> bool:
    if not retargeted or observed is None:
        return False

    if int(getattr(observed, "object_id", 0) or 0) <= 0:
        return False

    if active_combat is not None:
        return False

    return should_start_combat_after_target_commit(args, distance)


def hunter_target_ground_z_delta(
    args: argparse.Namespace,
    client,
    npc,
    *,
    region: int | None = None,
) -> float | None:
    max_delta = float(getattr(args, "hunter_target_max_ground_z_delta", 0.0) or 0.0)
    if max_delta <= 0.0:
        return None

    sampler = getattr(client, "ground_z_sampler", None)
    if sampler is None or npc is None:
        return None

    x = int(getattr(npc, "x", 0) or 0)
    y = int(getattr(npc, "y", 0) or 0)
    if x <= 0 or y <= 0:
        return None

    npc_z = int(getattr(npc, "z", 0) or 0)
    sample_region = int(region or getattr(client, "zone_id", 0) or getattr(args, "path_region", 0) or 0)
    try:
        sampled_z = sampler(x, y, sample_region)
    except TypeError:
        try:
            sampled_z = sampler(x, y)
        except Exception:
            return None
    except Exception:
        return None

    if sampled_z is None:
        return None

    return abs(float(sampled_z) - float(npc_z))


def hunter_target_ground_z_aligned(
    args: argparse.Namespace,
    client,
    npc,
    *,
    region: int | None = None,
) -> bool:
    max_delta = float(getattr(args, "hunter_target_max_ground_z_delta", 0.0) or 0.0)
    if max_delta <= 0.0:
        return True

    delta = hunter_target_ground_z_delta(args, client, npc, region=region)
    return delta is None or delta <= max_delta


def required_target_tokens(args: argparse.Namespace) -> list[str]:
    configured = str(getattr(args, "require_target_name", "") or "").strip()
    if not configured:
        configured = str(getattr(args, "required_target_api_name", "") or "").strip()
    return [token.strip().lower() for token in configured.split(",") if token.strip()]


def preferred_target_tokens(args: argparse.Namespace) -> list[str]:
    return [token.strip().lower() for token in getattr(args, "prefer_target_name", "").split(",") if token.strip()]


def objective_add_target_tokens(args: argparse.Namespace) -> list[str]:
    return [token.strip().lower() for token in getattr(args, "objective_add_target_name", "").split(",") if token.strip()]


def avoid_target_tokens(args: argparse.Namespace) -> list[str]:
    return [token.strip().lower() for token in getattr(args, "avoid_target_name", "").split(",") if token.strip()]


def normalize_target_name(value: str) -> str:
    return " ".join(str(value or "").replace("’", "'").lower().split())


def required_target_name_matches(target_name: str, token: str) -> bool:
    target_name = normalize_target_name(target_name)
    token = normalize_target_name(token)
    if not target_name or not token or token not in target_name:
        return False

    start = target_name.find(token)
    suffix = target_name[start + len(token) :]
    if target_name == token:
        return True

    # Boss summons often inherit the boss name ("X's minion"). Treat those as
    # adds/rescue targets, not as completion objectives.
    if suffix.startswith(("'s", "’s", "s'")):
        return False

    add_suffixes = (
        " add",
        " adds",
        " ally",
        " guardian",
        " helper",
        " messenger",
        " minion",
        " pet",
        " spawn",
    )
    if any(suffix.startswith(add_suffix) for add_suffix in add_suffixes):
        return False

    return True


def required_target_name_matches_exact(target_name: str, token: str) -> bool:
    return bool(normalize_target_name(target_name) == normalize_target_name(token))


def ascii_words(value: str) -> list[str]:
    return [word.lower() for word in re.findall(r"[a-z0-9]+", normalize_target_name(value))]


def required_target_name_matches_exact_or_mojibake_tail(target_name: str, token: str) -> bool:
    if required_target_name_matches_exact(target_name, token):
        return True

    normalized_name = normalize_target_name(target_name)
    if "\ufffd" not in normalized_name and "?" not in normalized_name:
        return False

    token_words = ascii_words(token)
    return bool(token_words and ascii_words(normalized_name) == token_words)


def dynamic_quest_requires_exact_required_target_name(args: argparse.Namespace) -> bool:
    return dynamic_quest_return_enabled(args) and bool(required_target_tokens(args))


def required_target_name_matches_for_args(args: argparse.Namespace, target_name: str, token: str) -> bool:
    if dynamic_quest_requires_exact_required_target_name(args):
        return required_target_name_matches_exact_or_mojibake_tail(target_name, token)
    return required_target_name_matches(target_name, token)


def name_matches_objective_add_target(args: argparse.Namespace, target_name: str) -> bool:
    normalized_name = normalize_target_name(target_name)
    return bool(
        normalized_name
        and any(required_target_name_matches(normalized_name, token) for token in objective_add_target_tokens(args))
    )


def is_objective_add_target(args: argparse.Namespace, npc) -> bool:
    return bool(npc is not None and name_matches_objective_add_target(args, str(getattr(npc, "name", "") or "")))


def name_matches_avoid_target(args: argparse.Namespace, target_name: str) -> bool:
    normalized_name = normalize_target_name(target_name)
    return bool(normalized_name and any(normalize_target_name(token) in normalized_name for token in avoid_target_tokens(args)))


def is_avoid_target(args: argparse.Namespace, npc) -> bool:
    return bool(npc is not None and name_matches_avoid_target(args, str(getattr(npc, "name", "") or "")))


def party_objective_name_tokens(args: argparse.Namespace, party_snapshot: dict[str, int | float | str] | None) -> list[str]:
    tokens: list[str] = []

    if party_snapshot is not None:
        leader_target_name = normalize_target_name(str(party_snapshot.get("leader_target_name", "") or ""))
        if leader_target_name:
            tokens.append(leader_target_name)

    tokens.extend(normalize_target_name(token) for token in required_target_tokens(args))
    return sorted({token for token in tokens if token}, key=len, reverse=True)


def npc_name_matches_party_objective_add(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
) -> bool:
    npc_name = normalize_target_name(str(getattr(npc, "name", "") or ""))
    if not npc_name:
        return False

    if name_matches_objective_add_target(args, npc_name):
        return True

    possessive_suffixes = ("'s", "s'")
    add_suffixes = (
        " add",
        " adds",
        " ally",
        " guardian",
        " helper",
        " messenger",
        " minion",
        " pet",
        " spawn",
    )

    for token in party_objective_name_tokens(args, party_snapshot):
        if npc_name == token:
            continue

        token_index = npc_name.find(token)
        if token_index < 0:
            continue

        suffix = npc_name[token_index + len(token) :]
        if suffix.startswith(possessive_suffixes):
            return True

        if any(suffix.startswith(add_suffix) for add_suffix in add_suffixes):
            return True

    return False


def is_required_target(args: argparse.Namespace, npc) -> bool:
    tokens = required_target_tokens(args)
    return bool(tokens and any(required_target_name_matches_for_args(args, npc.name, token) for token in tokens))


def name_matches_preferred_target(args: argparse.Namespace, target_name: str) -> bool:
    normalized_name = normalize_target_name(target_name)
    return bool(
        normalized_name
        and any(required_target_name_matches(normalized_name, token) for token in preferred_target_tokens(args))
    )


def is_preferred_target(args: argparse.Namespace, npc) -> bool:
    return bool(npc is not None and name_matches_preferred_target(args, str(getattr(npc, "name", "") or "")))


def is_route_objective_target(args: argparse.Namespace, npc) -> bool:
    if is_required_target(args, npc):
        return True
    return bool(not required_target_tokens(args) and is_preferred_target(args, npc))


def behavior_state_value(state: DummyBehaviorState | str) -> str:
    return state.value if isinstance(state, DummyBehaviorState) else str(state or "")


def target_intent_value(intent: TargetIntent | str) -> str:
    return intent.value if isinstance(intent, TargetIntent) else str(intent or "")


def target_source_value(source: TargetSource | str) -> str:
    return source.value if isinstance(source, TargetSource) else str(source or "")


def should_use_engagement_gate_for_target_source(source: TargetSource | str) -> bool:
    return target_source_value(source) in {item.value for item in TargetSource}


def required_target_api_candidate(
    args: argparse.Namespace,
    observed,
) -> EngagementCandidate:
    return EngagementCandidate(
        object_id=int(getattr(observed, "object_id", 0) or 0),
        name=str(getattr(observed, "name", "") or ""),
        level=int(getattr(observed, "level", 0) or 0),
        x=int(getattr(observed, "x", 0) or 0),
        y=int(getattr(observed, "y", 0) or 0),
        z=int(getattr(observed, "z", 0) or 0),
        source=TargetSource.current_target_api_refresh,
        intent=TargetIntent.required_retaliation if is_required_target(args, observed) else TargetIntent.objective,
        npc=observed,
    )


def _target_gate_actor(candidate: EngagementCandidate):
    if candidate.npc is not None:
        return candidate.npc
    return SimpleNamespace(
        object_id=candidate.object_id,
        name=candidate.name,
        level=candidate.level,
        x=candidate.x,
        y=candidate.y,
        z=candidate.z,
        flags=0,
    )


def engagement_candidate_from_actor(
    npc,
    *,
    source: TargetSource | str,
    intent: TargetIntent | str,
) -> EngagementCandidate:
    return EngagementCandidate(
        object_id=int(getattr(npc, "object_id", 0) or 0),
        name=str(getattr(npc, "name", "") or ""),
        level=int(getattr(npc, "level", 0) or 0),
        x=int(getattr(npc, "x", 0) or 0),
        y=int(getattr(npc, "y", 0) or 0),
        z=int(getattr(npc, "z", 0) or 0),
        source=source,
        intent=intent,
        npc=npc,
    )


def _target_decision(
    *,
    allowed: bool,
    candidate: EngagementCandidate,
    intent: TargetIntent | str,
    source: TargetSource | str,
    priority: int = 0,
    reject_reason: str = "",
    should_target_object: bool = False,
    should_update_current_target: bool = False,
    should_publish_party_leader_target: bool = False,
    should_mark_leader_engaged: bool = False,
    should_publish_party_shared_target: bool = False,
    should_publish_party_shared_engaged: bool = False,
) -> TargetDecision:
    return TargetDecision(
        allowed=allowed,
        candidate=candidate,
        intent=intent,
        source=source,
        priority=priority,
        reject_reason=reject_reason,
        should_target_object=should_target_object,
        should_update_current_target=should_update_current_target,
        should_publish_party_leader_target=should_publish_party_leader_target,
        should_mark_leader_engaged=should_mark_leader_engaged,
        should_publish_party_shared_target=should_publish_party_shared_target,
        should_publish_party_shared_engaged=should_publish_party_shared_engaged,
    )


def _reject_engagement_candidate(
    candidate: EngagementCandidate,
    *,
    intent: TargetIntent | str,
    source: TargetSource | str,
    reason: str,
) -> TargetDecision:
    return _target_decision(
        allowed=False,
        candidate=candidate,
        intent=intent,
        source=source,
        reject_reason=reason,
    )


def engagement_candidate_level_allowed(args: argparse.Namespace, client, actor) -> bool:
    return required_target_level_allowed(args, actor) or preferred_low_con_fallback_allowed(args, client, actor)


def evaluate_engagement_candidate(
    candidate: EngagementCandidate,
    context: EngagementContext,
    client,
    args: argparse.Namespace,
    party_snapshot,
) -> TargetDecision:
    source = candidate.source
    intent = candidate.intent
    intent_name = target_intent_value(intent)
    source_name = target_source_value(source)
    leader_objective_reacquire = bool(
        source_name == TargetSource.leader_target_reacquire.value
        and intent_name == TargetIntent.objective.value
        and context.is_party_leader
    )
    ready_objective_party_assist = bool(
        source_name == TargetSource.party_assist.value
        and intent_name == TargetIntent.objective.value
        and context.is_party_follower
        and context.leader_engaged
    )
    leader_engaged_objective_party_assist = bool(
        source_name in {TargetSource.party_assist.value, TargetSource.leader_target_reacquire.value}
        and intent_name in {TargetIntent.objective.value, TargetIntent.party_assist.value}
        and context.is_party_follower
        and context.leader_engaged
    )
    active_current_target_preserve = bool(
        source_name == TargetSource.current_target_preserve.value
        and int(context.current_target or 0) == int(candidate.object_id or 0)
        and intent_name
        in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_assist.value,
            TargetIntent.party_rescue.value,
            TargetIntent.current_target_confirm.value,
        }
    )
    actor = _target_gate_actor(candidate)
    candidate_name = str(getattr(actor, "name", "") or candidate.name or "")
    leader_engaged_unknown_objective_party_assist = bool(
        leader_engaged_objective_party_assist
        and not target_position_known(actor)
        and (
            name_matches_required_target(args, candidate_name)
            or name_matches_objective_add_target(args, candidate_name)
        )
    )
    leader_engaged_party_action = bool(
        context.leader_engaged
        and (
            source_name
            in {
                TargetSource.party_assist.value,
                TargetSource.leader_target_reacquire.value,
                TargetSource.party_rescue.value,
            }
            or (
                source_name == TargetSource.local_rescue.value
                and intent_name
                in {
                    TargetIntent.party_rescue.value,
                    TargetIntent.required_retaliation.value,
                }
            )
        )
    )
    leader_engaged_party_rescue_target = bool(
        leader_engaged_party_action
        and intent_name
        in {
            TargetIntent.party_rescue.value,
            TargetIntent.required_retaliation.value,
        }
        and should_accept_party_rescue_target(args, actor)
    )
    accepted_party_rescue_target = bool(
        (
            intent_name == TargetIntent.party_rescue.value
            or (
                source_name == TargetSource.party_rescue.value
                and intent_name == TargetIntent.required_retaliation.value
            )
        )
        and should_accept_party_rescue_target(args, actor)
    )
    active_tank_party_pressure_target = bool(
        context.is_party_follower
        and context.is_active_tank
        and context.leader_engaged
        and source_name
        in {
            TargetSource.party_assist.value,
            TargetSource.party_rescue.value,
            TargetSource.leader_target_reacquire.value,
            TargetSource.current_target_preserve.value,
        }
        and intent_name
        in {
            TargetIntent.objective.value,
            TargetIntent.party_assist.value,
            TargetIntent.party_rescue.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.current_target_confirm.value,
        }
        and target_within_combat_home_leash_or_unknown(args, actor)
    )

    if int(candidate.object_id or 0) <= 0:
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="invalid_target")

    if not should_use_engagement_gate_for_target_source(source):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="non_hostile_target_source")

    if (
        source_name in {TargetSource.party_assist.value, TargetSource.leader_target_reacquire.value}
        and not party_snapshot_leader_target_attackable(party_snapshot)
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="leader_target_not_attackable")

    if context.flee_active:
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="flee_active")

    if context.rest_active or behavior_state_value(context.behavior_state) == DummyBehaviorState.RestRecover.value:
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="rest_active")

    if context.drop_aggro_active or behavior_state_value(context.behavior_state) == DummyBehaviorState.DropAggroAndRecover.value:
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="drop_aggro_active")

    if not can_select_hostile_target(context.behavior_state):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="state_blocks_hostile_commit")

    if should_ignore_non_objective_target(context.behavior_state, intent) and not leader_engaged_party_action:
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="travel_non_objective")

    if (
        context.is_party_follower
        and bool(getattr(args, "party_assist_only", False))
        and source_name == TargetSource.hunter_selection.value
        and not leader_engaged_party_action
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="party_assist_only")

    if (
        context.is_party_follower
        and bool(getattr(args, "party_require_leader_engaged", False))
        and not context.leader_engaged
        and name_matches_required_or_party_objective(args, party_snapshot, candidate_name)
        and intent_name
        in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_rescue.value,
            TargetIntent.travel_aggro.value,
            TargetIntent.party_assist.value,
            TargetIntent.current_target_confirm.value,
        }
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="leader_not_engaged_objective")

    if (
        source_name in {TargetSource.party_assist.value, TargetSource.leader_target_reacquire.value}
        and not can_party_assist(context.behavior_state)
        and not (leader_objective_reacquire or ready_objective_party_assist or active_tank_party_pressure_target)
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="state_blocks_party_assist")

    if (
        not engagement_candidate_level_allowed(args, client, actor)
        and not leader_engaged_party_action
        and not accepted_party_rescue_target
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="level_filter")

    if not target_within_required_home(args, actor) and not (
        leader_engaged_party_rescue_target
        or active_tank_party_pressure_target
        or leader_engaged_unknown_objective_party_assist
        or (leader_engaged_objective_party_assist and target_within_combat_home_leash(args, actor))
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="target_home_max_distance")

    if not target_within_selection_distance(client, args, actor) and not (
        (
            leader_engaged_party_rescue_target
            or leader_engaged_objective_party_assist
            or active_tank_party_pressure_target
            or active_current_target_preserve
            or leader_engaged_unknown_objective_party_assist
        )
        and (
            target_within_combat_home_leash(args, actor)
            or leader_engaged_unknown_objective_party_assist
            or (active_tank_party_pressure_target and not target_position_known(actor))
        )
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="max_target_distance")

    leash_violated, leash_kind, _leash_distance = target_home_leash_violation(client, args, actor)
    if leash_violated and not (
        (leader_engaged_party_action or accepted_party_rescue_target)
        and leash_kind == "player"
        and target_within_combat_home_leash(args, actor)
    ) and not (
        leader_engaged_unknown_objective_party_assist
        and leash_kind == "target"
    ) and not (
        active_tank_party_pressure_target
        and leash_kind == "target"
        and not target_position_known(actor)
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="combat_home_leash")

    if (
        required_target_home_destination(args) is not None
        and intent_name in {TargetIntent.objective.value, TargetIntent.required_retaliation.value}
        and not leader_engaged_objective_party_assist
        and not active_tank_party_pressure_target
        and not active_current_target_preserve
        and not (context.objective_home_reached or context.objective_hunt_ready)
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="objective_home_not_ready")

    if (
        source_name in {TargetSource.party_assist.value, TargetSource.leader_target_reacquire.value}
        and not context.party_ready
        and not leader_engaged_objective_party_assist
        and not active_tank_party_pressure_target
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="party_not_ready")

    if (
        source_name in {TargetSource.party_assist.value, TargetSource.leader_target_reacquire.value}
        and bool(getattr(args, "party_require_leader_engaged", False))
        and context.is_party_follower
        and not context.leader_engaged
    ):
        return _reject_engagement_candidate(candidate, intent=intent, source=source, reason="leader_not_engaged")

    should_publish_leader_target = bool(
        context.is_party_leader
        and intent_name
        in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_assist.value,
            TargetIntent.current_target_confirm.value,
        }
    )
    priority = 100
    if intent_name == TargetIntent.required_retaliation.value:
        priority = 120
    elif intent_name == TargetIntent.party_rescue.value:
        priority = 90
    elif intent_name in {TargetIntent.travel_aggro.value, TargetIntent.avoided_add.value}:
        priority = 10

    return _target_decision(
        allowed=True,
        candidate=candidate,
        intent=intent,
        source=source,
        priority=priority,
        should_target_object=True,
        should_update_current_target=True,
        should_publish_party_leader_target=should_publish_leader_target,
        should_mark_leader_engaged=False,
    )


def evaluate_required_target_api_observation(
    args: argparse.Namespace,
    observed,
    context: EngagementContext,
    client,
    party_snapshot,
) -> TargetDecision:
    return evaluate_engagement_candidate(
        required_target_api_candidate(args, observed),
        context,
        client,
        args,
        party_snapshot,
    )


def evaluate_objective_pressure_interrupt_candidate(
    args: argparse.Namespace,
    npc,
    *,
    source: TargetSource | str,
    intent: TargetIntent | str,
    current_health_percent: int,
    required_home_hunt_ready: bool,
    context: EngagementContext,
    client,
    party_snapshot,
) -> TargetDecision | None:
    if not should_interrupt_drop_aggro_for_required_objective_pressure(
        args,
        context.behavior_state,
        npc,
        intent,
        current_health_percent=current_health_percent,
        required_home_hunt_ready=required_home_hunt_ready,
    ):
        return None

    interrupt_context = replace(
        context,
        behavior_state=DummyBehaviorState.HuntObjective,
        drop_aggro_active=False,
        rest_active=False,
        flee_active=False,
    )
    return evaluate_engagement_candidate(
        engagement_candidate_from_actor(npc, source=source, intent=intent),
        interrupt_context,
        client,
        args,
        party_snapshot,
    )


def evaluate_active_combat_focus_commit(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
    context: EngagementContext,
    client,
    party_snapshot,
) -> TargetDecision:
    actor = actor_from_active_combat(active_combat)
    active_intent = active_combat_intent(active_combat)
    if not active_intent or active_intent == TargetIntent.none.value:
        active_intent = target_intent_value(context.current_target_intent)
    if not active_intent or active_intent == TargetIntent.none.value:
        active_intent = TargetIntent.party_rescue.value

    decision = evaluate_engagement_candidate(
        engagement_candidate_from_actor(
            actor,
            source=TargetSource.current_target_preserve,
            intent=active_intent,
        ),
        context,
        client,
        args,
        party_snapshot,
    )
    if not decision.allowed:
        return decision

    return replace(
        decision,
        should_publish_party_leader_target=False,
        should_mark_leader_engaged=False,
    )


def leader_target_actor_from_snapshot(party_snapshot: dict[str, int | float | str]):
    target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    if target_id <= 0:
        return None

    return SimpleNamespace(
        object_id=target_id,
        name=str(party_snapshot.get("leader_target_name", "") or "leader target"),
        x=int(party_snapshot.get("leader_target_x", 0) or 0),
        y=int(party_snapshot.get("leader_target_y", 0) or 0),
        z=int(party_snapshot.get("leader_target_z", 0) or 0),
        level=int(party_snapshot.get("leader_target_level", 0) or 0),
        flags=0,
        target_can_attack=parse_optional_bool(party_snapshot.get("leader_target_can_attack")),
        target_relation=str(party_snapshot.get("leader_target_relation", "") or ""),
        target_type=str(party_snapshot.get("leader_target_type", "") or ""),
    )


def evaluate_party_assist_leader_target(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    context: EngagementContext,
    client,
) -> TargetDecision:
    return evaluate_engagement_candidate(
        engagement_candidate_from_actor(
            leader_target_actor_from_snapshot(party_snapshot),
            source=TargetSource.party_assist,
            intent=TargetIntent.party_assist,
        ),
        context,
        client,
        args,
        party_snapshot,
    )


def _target_gate_reject_action_name(reason: str) -> str:
    suffix = re.sub(r"[^a-z0-9_]+", "_", str(reason or "unknown").strip().lower()).strip("_")
    return f"target_gate_rejected_{suffix or 'unknown'}"


QUIET_TARGET_GATE_REJECT_REASONS = {"party_assist_only"}


def leader_current_target_republish_decision(decision: TargetDecision) -> TargetDecision:
    if not decision.allowed:
        return decision

    return replace(
        decision,
        should_target_object=False,
        should_update_current_target=False,
        should_publish_party_leader_target=True,
        should_mark_leader_engaged=False,
    )


def party_shared_target_publish_decision(decision: TargetDecision, *, engaged: bool = False) -> TargetDecision:
    if not decision.allowed:
        return decision

    return replace(
        decision,
        should_target_object=False,
        should_update_current_target=False,
        should_publish_party_leader_target=False,
        should_mark_leader_engaged=False,
        should_publish_party_shared_target=True,
        should_publish_party_shared_engaged=bool(engaged),
    )


def mark_party_leader_target_engaged(party_state, target_id: int) -> bool:
    if party_state is None or not hasattr(party_state, "mark_leader_target_engaged"):
        return False

    target_id = int(target_id or 0)
    if target_id <= 0:
        return False

    party_state.mark_leader_target_engaged(target_id)
    return True


def commit_target(
    decision: TargetDecision,
    client,
    party_state,
    *,
    now: float,
    current_target: int,
    current_target_since: float,
    current_target_last_visible_at: float,
    current_target_intent: TargetIntent | str,
    action_counts: dict[str, int] | None = None,
    log_event=None,
    examine: bool | None = None,
) -> TargetCommitResult:
    candidate = decision.candidate

    if not decision.allowed:
        quiet_reject = str(decision.reject_reason or "") in QUIET_TARGET_GATE_REJECT_REASONS
        if action_counts is not None and not quiet_reject:
            add_action(action_counts, "target_gate_rejected")
            add_action(action_counts, _target_gate_reject_action_name(decision.reject_reason))
        if log_event is not None and not quiet_reject:
            log_event(
                "target_gate_rejected",
                now,
                target_id=int(candidate.object_id or 0),
                target_name=str(candidate.name or ""),
                target_level=int(candidate.level or 0),
                target_source=target_source_value(decision.source),
                target_intent=target_intent_value(decision.intent),
                reject_reason=str(decision.reject_reason or ""),
            )
        return TargetCommitResult(
            current_target=current_target,
            current_target_since=current_target_since,
            current_target_last_visible_at=current_target_last_visible_at,
            current_target_intent=current_target_intent,
            target_object_called=False,
            current_target_updated=False,
            party_leader_target_published=False,
            party_shared_target_published=False,
        )

    target_object_called = False
    if decision.should_target_object:
        if examine is None:
            client.target_object(candidate.object_id)
        else:
            client.target_object(candidate.object_id, examine=examine)
        target_object_called = True

    updated_current_target = current_target
    updated_current_target_since = current_target_since
    updated_current_target_last_visible_at = current_target_last_visible_at
    updated_current_target_intent = current_target_intent
    current_target_updated = False
    if decision.should_update_current_target:
        updated_current_target = int(candidate.object_id or 0)
        updated_current_target_since = now
        updated_current_target_last_visible_at = now
        updated_current_target_intent = decision.intent
        current_target_updated = True

    party_leader_target_published = False
    if decision.should_publish_party_leader_target and party_state is not None:
        target_actor = candidate.npc if candidate.npc is not None else _target_gate_actor(candidate)
        party_state.update_leader(client, target_actor)
        party_leader_target_published = True

    if (
        decision.should_mark_leader_engaged
        and party_state is not None
    ):
        mark_party_leader_target_engaged(party_state, candidate.object_id)

    party_shared_target_published = False
    if decision.should_publish_party_shared_target and party_state is not None:
        target_actor = candidate.npc if candidate.npc is not None else _target_gate_actor(candidate)
        party_state.update_shared_target(target_actor, engaged=decision.should_publish_party_shared_engaged)
        party_shared_target_published = True

    return TargetCommitResult(
        current_target=updated_current_target,
        current_target_since=updated_current_target_since,
        current_target_last_visible_at=updated_current_target_last_visible_at,
        current_target_intent=updated_current_target_intent,
        target_object_called=target_object_called,
        current_target_updated=current_target_updated,
        party_leader_target_published=party_leader_target_published,
        party_shared_target_published=party_shared_target_published,
    )


def is_objective_travel_state(state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(state) in {
        DummyBehaviorState.TravelToObjective.value,
        DummyBehaviorState.ReturnToObjective.value,
    }


def can_select_hostile_target(state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(state) not in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }


def can_party_assist(state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(state) == DummyBehaviorState.HuntObjective.value


def should_ignore_non_objective_target(
    state: DummyBehaviorState | str,
    current_target_intent: TargetIntent | str,
) -> bool:
    if not is_objective_travel_state(state):
        return False

    return target_intent_value(current_target_intent) not in {
        TargetIntent.objective.value,
        TargetIntent.required_retaliation.value,
        TargetIntent.party_rescue.value,
        TargetIntent.current_target_confirm.value,
    }


def can_start_or_refresh_flee(state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(state) not in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }


def can_rest_recover(state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(state) not in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }


def should_extend_round_for_safe_exit(
    args: argparse.Namespace,
    state: DummyBehaviorState | str,
    *,
    now: float,
    end_time: float,
    safe_exit_deadline: float,
    health_percent: int,
    current_target: int,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
    flee_until: float,
    rest_until: float,
    active_threat: bool = False,
) -> bool:
    if now < end_time:
        return False

    if max(0.0, float(getattr(args, "safe_exit_max_seconds", 0.0) or 0.0)) <= 0.0:
        return False

    if now >= safe_exit_deadline:
        return False

    state_value = behavior_state_value(state)
    if state_value in {
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.HandleTravelAggro.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }:
        return True

    if flee_until > now:
        return True

    if current_target > 0:
        return True

    if active_threat:
        return True

    health = int(health_percent or 0)
    resume_threshold = int(getattr(args, "low_health_rest_resume_percent", 0) or 0)
    if health <= 0 or (resume_threshold > 0 and health < resume_threshold):
        return True

    if state_value == DummyBehaviorState.RestRecover.value and rest_until > now:
        return True

    damage_grace = max(0.0, float(getattr(args, "safe_exit_recent_damage_grace", 0.0) or 0.0))
    if damage_grace > 0.0:
        last_damage_at = max(float(last_damage_taken_at or 0.0), float(last_incoming_damage_at or 0.0))
        if last_damage_at > 0.0 and 0.0 <= now - last_damage_at <= damage_grace:
            return True

    return False


def should_extend_round_for_dynamic_quest_return(
    *,
    dynamic_quest_return_pending: bool,
    dynamic_quest_return_completed: bool,
) -> bool:
    return bool(dynamic_quest_return_pending and not dynamic_quest_return_completed)


def recent_safe_exit_damage_age(
    *,
    now: float,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
) -> float | None:
    last_damage_at = max(float(last_damage_taken_at or 0.0), float(last_incoming_damage_at or 0.0))
    if last_damage_at <= 0.0:
        return None
    return max(0.0, float(now or 0.0) - last_damage_at)


def required_target_completion_needs_safe_exit(
    args: argparse.Namespace,
    *,
    now: float,
    health_percent: int,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
) -> bool:
    if max(0.0, float(getattr(args, "safe_exit_max_seconds", 0.0) or 0.0)) <= 0.0:
        return False

    health = int(health_percent or 0)
    resume_threshold = int(getattr(args, "low_health_rest_resume_percent", 0) or 0)
    if health <= 0 or (resume_threshold > 0 and health < resume_threshold):
        return True

    damage_grace = max(0.0, float(getattr(args, "safe_exit_recent_damage_grace", 0.0) or 0.0))
    if damage_grace <= 0.0:
        return False

    recent_damage_age = recent_safe_exit_damage_age(
        now=now,
        last_damage_taken_at=last_damage_taken_at,
        last_incoming_damage_at=last_incoming_damage_at,
    )
    return bool(recent_damage_age is not None and recent_damage_age <= damage_grace)


def required_target_completion_should_wait_for_safe_exit(
    args: argparse.Namespace,
    *,
    now: float,
    health_percent: int,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
) -> bool:
    if int(health_percent or 0) > 0 and dynamic_quest_return_enabled(args):
        return False

    return required_target_completion_needs_safe_exit(
        args,
        now=now,
        health_percent=health_percent,
        last_damage_taken_at=last_damage_taken_at,
        last_incoming_damage_at=last_incoming_damage_at,
    )


def required_target_completion_safe_after_removed(
    args: argparse.Namespace,
    state: DummyBehaviorState | str,
    *,
    now: float,
    health_percent: int,
    current_target: int,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
    flee_until: float,
    rest_until: float,
) -> bool:
    if int(current_target or 0) > 0:
        return False
    if flee_until > now or rest_until > now:
        return False
    if behavior_state_value(state) in {
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.HandleTravelAggro.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }:
        return False

    return not required_target_completion_needs_safe_exit(
        args,
        now=now,
        health_percent=health_percent,
        last_damage_taken_at=last_damage_taken_at,
        last_incoming_damage_at=last_incoming_damage_at,
    )


def should_disengage_current_target_for_safe_exit(
    args: argparse.Namespace,
    state: DummyBehaviorState | str,
    *,
    current_target: int,
    health_percent: int,
    recent_damage_age_seconds: float | None,
) -> bool:
    if int(current_target or 0) <= 0:
        return False
    if not can_start_or_refresh_flee(state):
        return False
    if behavior_state_value(state) == DummyBehaviorState.DropAggroAndRecover.value:
        return False
    if not bool(getattr(args, "safe_exit_disengage_current_target", True)):
        return False

    resume_threshold = max(1, int(getattr(args, "low_health_rest_resume_percent", 0) or 0))
    if int(health_percent or 0) < resume_threshold:
        return True

    damage_grace = max(1.0, float(getattr(args, "safe_exit_recent_damage_grace", 0.0) or 0.0))
    if recent_damage_age_seconds is not None and float(recent_damage_age_seconds) <= damage_grace:
        return True

    return True


def refresh_safe_exit_deadline_after_target_removed(
    args: argparse.Namespace,
    *,
    safe_exit_active: bool,
    safe_exit_deadline: float,
    now: float,
) -> float:
    return refresh_safe_exit_deadline_for_recovery(
        args,
        safe_exit_active=safe_exit_active,
        safe_exit_deadline=safe_exit_deadline,
        now=now,
    )


def refresh_safe_exit_deadline_for_recovery(
    args: argparse.Namespace,
    *,
    safe_exit_active: bool,
    safe_exit_deadline: float,
    now: float,
) -> float:
    if not safe_exit_active:
        return safe_exit_deadline

    recovery_window = max(0.0, float(getattr(args, "safe_exit_max_seconds", 0.0) or 0.0))
    if recovery_window <= 0.0:
        return safe_exit_deadline

    existing_deadline = float(safe_exit_deadline or 0.0)
    if existing_deadline > 0.0:
        return existing_deadline

    return float(now or 0.0) + recovery_window


def safe_exit_deadline_can_complete_recovered(
    args: argparse.Namespace,
    state: DummyBehaviorState | str,
    *,
    now: float,
    health_percent: int,
    current_target: int,
    flee_until: float,
    last_damage_taken_at: float,
    last_incoming_damage_at: float,
    rest_until: float = 0.0,
) -> bool:
    if int(current_target or 0) > 0 or float(flee_until or 0.0) > float(now or 0.0):
        return False

    if behavior_state_value(state) not in {
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.ReturnToObjective.value,
        DummyBehaviorState.HuntObjective.value,
    }:
        return False

    damage_grace = max(0.0, float(getattr(args, "safe_exit_recent_damage_grace", 0.0) or 0.0))
    recent_damage_age = recent_safe_exit_damage_age(
        now=now,
        last_damage_taken_at=last_damage_taken_at,
        last_incoming_damage_at=last_incoming_damage_at,
    )
    if (
        behavior_state_value(state) == DummyBehaviorState.RestRecover.value
        and float(rest_until or 0.0) > float(now or 0.0)
        and int(health_percent or 0) > 0
        and (recent_damage_age is None or recent_damage_age > damage_grace)
    ):
        return True

    recovery_floor = max(1, int(getattr(args, "low_health_rest_percent", 0) or 0))
    if int(health_percent or 0) < recovery_floor:
        return False

    return bool(recent_damage_age is None or recent_damage_age > damage_grace)


def should_drop_new_damage_during_safe_exit(
    *,
    safe_exit_active: bool,
    current_target: int,
    current_health_percent: int,
    previous_health_percent: int,
    last_damage_attacker_name: str = "",
    objective_damage: bool = False,
) -> bool:
    return bool(
        safe_exit_active
        and current_target <= 0
        and current_health_percent > 0
        and previous_health_percent > 0
        and current_health_percent < previous_health_percent
        and str(last_damage_attacker_name or "").strip()
        and not objective_damage
    )


def should_replace_flee_plan(
    current_plan: FleePlan | None,
    *,
    now: float,
    priority: int,
) -> bool:
    if current_plan is None:
        return True
    if float(current_plan.locked_until or 0.0) <= float(now or 0.0):
        return True
    return int(priority or 0) > int(current_plan.priority or 0)


def flee_damage_replan_priority(args: argparse.Namespace, health_percent: int) -> int:
    critical_threshold = int(getattr(args, "flee_critical_health_percent", 0) or 0)
    if critical_threshold > 0 and 0 < int(health_percent or 0) <= critical_threshold:
        return 120
    return 100


def _fsm_recovery_floor(args: argparse.Namespace) -> int:
    return max(
        int(getattr(args, "required_target_recover_before_home_health_percent", 0) or 0),
        int(getattr(args, "low_health_rest_resume_percent", 0) or 0),
        int(getattr(args, "party_melee_survival_resume_health_percent", 0) or 0),
    )


def can_objective_pressure_interrupt(
    state: DummyBehaviorState | str,
    health_percent: int,
    context,
    args: argparse.Namespace,
) -> bool:
    if behavior_state_value(state) != DummyBehaviorState.DropAggroAndRecover.value:
        return False
    if not bool(getattr(context, "required_home_hunt_ready", False)):
        return False

    commit_floor = int(getattr(args, "required_target_tank_commit_health_percent", 0) or 0)
    if commit_floor > 0 and int(health_percent or 0) <= commit_floor:
        return False

    recovery_floor = _fsm_recovery_floor(args)
    if recovery_floor > 0 and int(health_percent or 0) < recovery_floor:
        return False

    return int(health_percent or 0) > 0


def can_preserve_committed_hostile_target(
    behavior_state: DummyBehaviorState | str,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    *,
    flee_active: bool = False,
    rest_active: bool = False,
    drop_aggro_active: bool = False,
) -> bool:
    if flee_active or rest_active or drop_aggro_active:
        return False

    state_value = behavior_state_value(behavior_state)
    if state_value in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }:
        return False

    if is_objective_travel_state(state_value):
        return target_intent_value(current_target_intent) in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_rescue.value,
            TargetIntent.current_target_confirm.value,
        }

    return True


def can_enable_hostile_attack_mode(
    behavior_state: DummyBehaviorState | str,
    current_target: int,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    *,
    flee_active: bool = False,
    rest_active: bool = False,
    drop_aggro_active: bool = False,
) -> bool:
    if int(current_target or 0) <= 0:
        return False

    return can_preserve_committed_hostile_target(
        behavior_state,
        current_target_intent,
        flee_active=flee_active,
        rest_active=rest_active,
        drop_aggro_active=drop_aggro_active,
    )


def can_commit_required_retaliation(
    state: DummyBehaviorState | str,
    health_percent: int,
    context,
    args: argparse.Namespace,
) -> bool:
    if behavior_state_value(state) in {
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }:
        return False
    if int(health_percent or 0) <= 0:
        return False

    required_home_hunt_ready = bool(getattr(context, "required_home_hunt_ready", False))
    party_ready_for_objective = bool(getattr(context, "party_ready_for_objective", True))
    direct_required_damage_to_active_tank = bool(getattr(context, "direct_required_damage_to_active_tank", False))
    objective_pressure_active = bool(getattr(context, "objective_pressure_active", False))
    is_party_follower = bool(getattr(context, "is_party_follower", False))
    leader_engaged = bool(getattr(context, "leader_engaged", True))
    return should_commit_required_retaliation_for_objective(
        args,
        state,
        required_home_hunt_ready=required_home_hunt_ready,
        party_ready_for_objective=party_ready_for_objective,
        direct_required_damage_to_active_tank=direct_required_damage_to_active_tank,
        objective_pressure_active=objective_pressure_active,
        is_party_follower=is_party_follower,
        leader_engaged=leader_engaged,
    )


def should_allow_scheduled_rest(behavior_state: DummyBehaviorState | str, current_target: int) -> bool:
    if current_target:
        return False
    return behavior_state_value(behavior_state) not in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.TravelToObjective.value,
        DummyBehaviorState.HandleTravelAggro.value,
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.ReturnToObjective.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }


def should_complete_timed_rest_recovery(
    behavior_state: DummyBehaviorState | str,
    *,
    rest_until: float,
    stand_after_rest: bool,
    now: float,
) -> bool:
    return bool(
        behavior_state_value(behavior_state) == DummyBehaviorState.RestRecover.value
        and rest_until > 0.0
        and now >= rest_until
        and not stand_after_rest
    )


def next_state_after_rest_recovery_completion(
    args: argparse.Namespace,
    client,
    *,
    is_party_leader: bool,
    current_target: int,
) -> DummyBehaviorState:
    if (
        should_approach_required_target_home(args, is_party_leader=is_party_leader, current_target=current_target)
        and not required_target_home_hunt_ready(client, args)
    ):
        return DummyBehaviorState.ReturnToObjective

    return DummyBehaviorState.HuntObjective


def target_intent_for_selected_npc(
    args: argparse.Namespace,
    npc,
    *,
    selected_npc_is_rescue: bool,
    behavior_state: DummyBehaviorState | str = DummyBehaviorState.HuntObjective,
    recent_incoming_attacker_name: str = "",
) -> TargetIntent:
    if npc is None:
        return TargetIntent.none

    if is_required_target(args, npc):
        if (
            behavior_state_value(behavior_state) == DummyBehaviorState.HandleTravelAggro.value
            or name_matches_required_target(args, recent_incoming_attacker_name)
        ):
            return TargetIntent.required_retaliation
        return TargetIntent.objective

    if not required_target_tokens(args) and is_preferred_target(args, npc):
        return TargetIntent.objective

    if is_objective_add_target(args, npc):
        if (
            behavior_state_value(behavior_state) == DummyBehaviorState.HandleTravelAggro.value
            or name_matches_objective_add_target(args, recent_incoming_attacker_name)
        ):
            return TargetIntent.required_retaliation
        return TargetIntent.party_rescue

    if is_objective_travel_state(behavior_state) and is_avoid_target(args, npc):
        return TargetIntent.avoided_add

    if is_objective_travel_state(behavior_state):
        return TargetIntent.travel_aggro

    if selected_npc_is_rescue:
        return TargetIntent.party_rescue

    return TargetIntent.objective


def should_suppress_travel_aggro_for_party_healer_support(
    args: argparse.Namespace,
    *,
    action_rotation: str = "",
) -> bool:
    rotation = str(action_rotation or getattr(args, "action_rotation", "") or "").strip()
    if rotation == "auto":
        return False
    return bool(getattr(args, "party_assist_only", False) and rotation == "healer-support")


def should_handle_travel_aggro_target(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    npc,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    *,
    action_rotation: str = "",
) -> bool:
    if should_suppress_travel_aggro_for_party_healer_support(args, action_rotation=action_rotation):
        return False

    if not is_objective_travel_state(behavior_state):
        return False

    intent = target_intent_value(current_target_intent)
    if intent in {TargetIntent.objective.value, TargetIntent.required_retaliation.value}:
        return False

    if npc is not None and is_route_objective_target(args, npc):
        return False

    if npc is not None and is_objective_add_target(args, npc):
        return False

    return npc is not None or intent == TargetIntent.travel_aggro.value


def should_handle_travel_aggro_damage(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    attacker_name: str,
    *,
    attacker_level: int = 0,
    player_level: int = 0,
    health_percent: int = 100,
    previous_health_percent: int = 100,
    action_rotation: str = "",
) -> bool:
    if not (
        is_objective_travel_state(behavior_state)
        and attacker_name
        and not name_matches_required_target(args, attacker_name)
        and (required_target_tokens(args) or not name_matches_preferred_target(args, attacker_name))
        and not name_matches_objective_add_target(args, attacker_name)
    ):
        return False

    low_level_delta = int(getattr(args, "travel_aggro_ignore_low_level_delta", 8) or 0)
    minor_drop_percent = int(getattr(args, "travel_aggro_minor_health_drop_percent", 5) or 0)
    pressure_health_percent = int(getattr(args, "flee_pressure_health_percent", 0) or 0)
    health_drop = max(0, int(previous_health_percent or 0) - int(health_percent or 0))
    if (
        low_level_delta > 0
        and minor_drop_percent > 0
        and int(attacker_level or 0) > 0
        and int(player_level or 0) > 0
        and int(player_level) - int(attacker_level) >= low_level_delta
        and health_drop <= minor_drop_percent
        and (pressure_health_percent <= 0 or int(health_percent or 0) > pressure_health_percent)
    ):
        return False

    return True


def visible_npc_level_by_name(npcs, target_name: str) -> int:
    target_key = normalize_target_name(target_name)
    if not target_key:
        return 0

    levels = [
        int(getattr(npc, "level", 0) or 0)
        for npc in npcs
        if normalize_target_name(str(getattr(npc, "name", "") or "")) == target_key
    ]
    return max(levels, default=0)


def should_suppress_passive_travel_target(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    npc,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    *,
    current_target: int = 0,
    now: float = 0.0,
    last_damage_taken_at: float = 0.0,
) -> bool:
    if not is_objective_travel_state(behavior_state):
        return False
    if target_intent_value(current_target_intent) not in {
        TargetIntent.avoided_add.value,
        TargetIntent.travel_aggro.value,
    }:
        return False
    if npc is None or is_route_objective_target(args, npc) or is_objective_add_target(args, npc):
        return False
    if current_target:
        return False

    damage_grace = max(0.0, float(getattr(args, "incoming_damage_melee_grace", 4.0) or 0.0))
    if last_damage_taken_at > 0.0 and now - last_damage_taken_at <= damage_grace:
        return False

    return True


def should_suppress_passive_avoided_travel_target(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    npc,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    *,
    current_target: int = 0,
    now: float = 0.0,
    last_damage_taken_at: float = 0.0,
) -> bool:
    return should_suppress_passive_travel_target(
        args,
        behavior_state,
        npc,
        current_target_intent,
        current_target=current_target,
        now=now,
        last_damage_taken_at=last_damage_taken_at,
    )


def should_allow_target_selection_for_behavior_state(
    behavior_state: DummyBehaviorState | str,
    args: argparse.Namespace,
    npc,
    current_target_intent: TargetIntent | str = TargetIntent.none,
) -> bool:
    if not can_select_hostile_target(behavior_state):
        return False

    if should_ignore_non_objective_target(behavior_state, current_target_intent):
        return False

    if should_handle_travel_aggro_target(args, behavior_state, npc, current_target_intent):
        return False

    return True


def should_allow_counterattack_for_behavior_state(
    behavior_state: DummyBehaviorState | str,
    args: argparse.Namespace,
    npc,
    current_target_intent: TargetIntent | str = TargetIntent.none,
) -> bool:
    return should_allow_target_selection_for_behavior_state(behavior_state, args, npc, current_target_intent)


def should_allow_party_assist_for_behavior_state(behavior_state: DummyBehaviorState | str) -> bool:
    return can_party_assist(behavior_state)


def should_clear_party_ready_for_behavior_state(behavior_state: DummyBehaviorState | str) -> bool:
    return behavior_state_value(behavior_state) in {
        DummyBehaviorState.HandleTravelAggro.value,
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }


def should_send_party_assist_command(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    leader_target_id: int,
    leader_engaged: bool,
    leader_target_name: str = "",
    leader_target_can_attack: bool | None = None,
    leader_target_relation: str = "",
    leader_target_type: str = "",
) -> bool:
    if not getattr(args, "party_use_assist_command", False):
        return False

    if not should_allow_party_assist_for_behavior_state(behavior_state):
        return False

    if int(leader_target_id or 0) <= 0:
        return False

    if not leader_party_assist_target_attackable(
        target_name=leader_target_name,
        target_can_attack=leader_target_can_attack,
        target_relation=leader_target_relation,
        target_type=leader_target_type,
    ):
        return False

    if getattr(args, "party_require_leader_engaged", False) and not leader_engaged:
        return False

    return True


def should_enter_hunt_for_party_assist_leader_target(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    is_party_follower: bool,
    action_rotation: str,
    leader_target_id: int,
    leader_engaged: bool,
    leader_target_name: str = "",
    leader_target_can_attack: bool | None = None,
    leader_target_relation: str = "",
    leader_target_type: str = "",
    required_home_hunt_ready: bool,
    party_ready_for_objective: bool,
) -> bool:
    if not is_party_follower or not getattr(args, "party_assist_only", False):
        return False

    if (
        str(action_rotation or "") == "healer-support"
        and (
            getattr(args, "required_target_home", None) is not None
            or bool(str(getattr(args, "require_target_name", "") or "").strip())
        )
    ):
        return False

    if not is_objective_travel_state(behavior_state):
        return False

    if int(leader_target_id or 0) <= 0 or not leader_engaged:
        return False

    if not leader_party_assist_target_attackable(
        target_name=leader_target_name,
        target_can_attack=leader_target_can_attack,
        target_relation=leader_target_relation,
        target_type=leader_target_type,
    ):
        return False

    if getattr(args, "required_target_home", None) is not None and not required_home_hunt_ready:
        return False

    return bool(party_ready_for_objective)


def clear_party_leader_target_on_abandon(
    party_state: PartyState | None,
    *,
    is_party_leader: bool,
    target_id: int = 0,
) -> bool:
    if party_state is None or not is_party_leader:
        return False

    if target_id:
        return party_state.clear_leader_target_if_match(target_id)

    party_state.clear_leader_target()
    return True


def should_preserve_shared_target_for_active_tank_on_leader_abandon(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    *,
    target_id: int = 0,
) -> bool:
    snapshot = party_snapshot or {}
    leader_target_id = int(snapshot.get("leader_target_id", 0) or 0)
    if leader_target_id <= 0:
        return False

    if int(target_id or leader_target_id) != leader_target_id:
        return False

    active_tank_name = str(snapshot.get("active_tank_name", "") or "").strip()
    active_tank_object_id = int(snapshot.get("active_tank_object_id", 0) or 0)
    if not active_tank_name and active_tank_object_id <= 0:
        return False

    leader_name = normalize_target_name(str(snapshot.get("leader_name", "") or ""))
    if leader_name and normalize_target_name(active_tank_name) == leader_name:
        return False

    target_name = str(snapshot.get("leader_target_name", "") or "")
    return name_matches_required_or_party_objective(args, snapshot, target_name)


def clear_party_leader_target_on_removed_object(
    party_state: PartyState | None,
    *,
    is_party_leader: bool,
    party_assist_only: bool,
    removed_object_id: int,
) -> bool:
    if party_state is None or (not is_party_leader and not party_assist_only):
        return False

    if not is_party_leader:
        snapshot = party_state.snapshot()
        if (
            int(snapshot.get("leader_target_id", 0) or 0) == int(removed_object_id or 0)
            and float(snapshot.get("leader_target_engaged_at", 0.0) or 0.0) > 0.0
        ):
            return False

    if not party_state.clear_leader_target_if_match(removed_object_id):
        return False

    party_state.clear_rescue_target(removed_object_id)
    return True


def should_commit_required_retaliation_for_objective(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    required_home_hunt_ready: bool,
    party_ready_for_objective: bool,
    direct_required_damage_to_active_tank: bool = False,
    objective_pressure_active: bool = False,
    is_party_follower: bool = False,
    leader_engaged: bool = True,
) -> bool:
    state = behavior_state_value(behavior_state)
    if state == DummyBehaviorState.DropAggroAndRecover.value:
        return False

    if (
        is_party_follower
        and bool(getattr(args, "party_require_leader_engaged", False))
        and not leader_engaged
        and is_objective_travel_state(state)
    ):
        return False

    block_unready_travel_retaliation = (
        bool(getattr(args, "party_block_solo_required_retaliation", False))
        and is_objective_travel_state(state)
        and not party_ready_for_objective
    )
    allow_direct_tank_retaliation = (
        direct_required_damage_to_active_tank
        and required_home_hunt_ready
        and not block_unready_travel_retaliation
    )
    allow_objective_pressure_retaliation = (
        objective_pressure_active
        and required_home_hunt_ready
        and not block_unready_travel_retaliation
    )
    if (
        not party_ready_for_objective
        and not allow_direct_tank_retaliation
        and not allow_objective_pressure_retaliation
    ):
        return False

    if state in {
        DummyBehaviorState.Startup.value,
        DummyBehaviorState.TravelToObjective.value,
        DummyBehaviorState.ReturnToObjective.value,
        DummyBehaviorState.HandleTravelAggro.value,
        DummyBehaviorState.RestRecover.value,
    }:
        return bool(required_home_hunt_ready)

    return True


def should_publish_damage_counterattack_as_leader_target(
    *,
    is_party_leader: bool,
    party_state: PartyState | None,
    current_target_intent: TargetIntent | str,
) -> bool:
    return bool(
        is_party_leader
        and party_state is not None
        and target_intent_value(current_target_intent)
        in {TargetIntent.objective.value, TargetIntent.required_retaliation.value}
    )


def should_publish_combat_start_as_leader_target(
    *,
    is_party_leader: bool,
    party_state: PartyState | None,
    current_target_intent: TargetIntent | str,
) -> bool:
    return bool(
        is_party_leader
        and party_state is not None
        and target_intent_value(current_target_intent)
        in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_rescue.value,
            TargetIntent.enemy_player.value,
        }
    )


def publish_combat_start_as_leader_target(
    party_state: PartyState | None,
    client,
    target,
    *,
    is_party_leader: bool,
    current_target_intent: TargetIntent | str,
) -> bool:
    if not should_publish_combat_start_as_leader_target(
        is_party_leader=is_party_leader,
        party_state=party_state,
        current_target_intent=current_target_intent,
    ):
        return False

    target_id = int(getattr(target, "object_id", 0) or 0)
    snapshot = party_state.snapshot()
    if target_id <= 0 or int(snapshot.get("leader_target_id", 0) or 0) != target_id:
        return False

    party_state.update_leader(client)
    return mark_party_leader_target_engaged(party_state, target_id)


def should_hold_initial_required_retaliation_multi_aggro(
    args: argparse.Namespace,
    active_combat,
    *,
    current_target_intent: TargetIntent | str,
    is_active_tank: bool,
    health_percent: int,
    now: float,
) -> bool:
    if active_combat is None or not is_active_tank:
        return False

    if target_intent_value(current_target_intent) != TargetIntent.required_retaliation.value:
        return False

    flee_health_percent = int(getattr(args, "flee_health_percent", 0) or 0)
    if flee_health_percent > 0 and health_percent <= flee_health_percent:
        return False

    started = float(active_combat.get("started", 0.0) or 0.0)
    if started <= 0.0:
        return False

    assist_after = float(getattr(args, "party_rescue_assist_after", 0.0) or 0.0)
    hold_grace = max(3.0, assist_after + 2.0)
    return now - started <= hold_grace


def should_delay_target_selection_until_objective_ready(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    selected_target_intent: TargetIntent | str,
    *,
    current_target: int,
    required_home_hunt_ready: bool,
    party_ready_for_objective: bool,
    is_party_follower: bool = False,
    leader_engaged: bool = True,
    objective_pressure_active: bool = False,
    force_pull_active: bool = False,
) -> bool:
    if force_pull_active:
        return False

    if getattr(args, "required_target_home", None) is None:
        return False

    if not is_objective_travel_state(behavior_state):
        return False

    target_intent = target_intent_value(selected_target_intent)
    if target_intent not in {
        TargetIntent.objective.value,
        TargetIntent.required_retaliation.value,
        TargetIntent.party_rescue.value,
    }:
        return False

    if current_target > 0 and target_intent == TargetIntent.party_rescue.value:
        return False

    if (
        is_party_follower
        and leader_engaged
        and target_intent
        in {
            TargetIntent.objective.value,
            TargetIntent.party_rescue.value,
            TargetIntent.required_retaliation.value,
        }
    ):
        return False

    if (
        objective_pressure_active
        and required_home_hunt_ready
        and target_intent == TargetIntent.required_retaliation.value
    ):
        if bool(getattr(args, "party_block_solo_required_retaliation", False)) and not party_ready_for_objective:
            return True
        return False

    if (
        is_party_follower
        and getattr(args, "party_require_leader_engaged", False)
        and target_intent
        in {
            TargetIntent.objective.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.party_rescue.value,
        }
        and not leader_engaged
    ):
        return True

    return not (required_home_hunt_ready and party_ready_for_objective)


def should_enter_hunt_for_objective_area_rescue(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    selected_npc_is_rescue: bool,
    selected_npc_is_required: bool = False,
    selected_target_intent: TargetIntent | str = TargetIntent.party_rescue,
    is_party_follower: bool = False,
    is_active_tank: bool = False,
    leader_engaged: bool = True,
    required_home_hunt_ready: bool,
    party_ready_for_objective: bool,
) -> bool:
    if target_intent_value(selected_target_intent) == TargetIntent.travel_aggro.value:
        return False

    if (
        is_party_follower
        and getattr(args, "party_require_leader_engaged", False)
        and not leader_engaged
    ):
        return False

    if selected_npc_is_required and is_party_follower and not is_active_tank:
        return False

    return bool(
        selected_npc_is_rescue
        and getattr(args, "required_target_home", None) is not None
        and is_objective_travel_state(behavior_state)
        and required_home_hunt_ready
        and party_ready_for_objective
    )


def should_healer_support_suppress_hostile_commit(
    args: argparse.Namespace,
    action_rotation: str,
    npc,
    selected_target_intent: TargetIntent | str,
    party_snapshot: dict[str, int | float | str] | None,
    *,
    command_attack_active: bool = False,
) -> bool:
    if command_attack_active:
        return False
    if action_rotation != "healer-support":
        return False
    target_name = str(getattr(npc, "name", "") or "")
    if not (
        is_required_target(args, npc)
        or name_matches_required_or_party_objective(args, party_snapshot, target_name)
    ):
        return False
    if is_objective_add_target(args, npc):
        return False
    if target_intent_value(selected_target_intent) not in {
        TargetIntent.objective.value,
        TargetIntent.party_assist.value,
        TargetIntent.required_retaliation.value,
    }:
        return False
    snapshot = party_snapshot or {}
    return bool(
        int(snapshot.get("leader_target_id", 0) or 0) > 0
        or str(snapshot.get("active_tank_name", "") or "").strip()
    )


def should_healer_support_suppress_hostile_rotation(
    args: argparse.Namespace,
    active_combat: dict[str, object] | object | None,
    party_snapshot: dict[str, int | float | str] | None,
) -> bool:
    snapshot = party_snapshot or {}
    if bool(snapshot.get("companion_command_attack_active")):
        return False
    target_name = active_combat_target_name(active_combat) or str(snapshot.get("leader_target_name", "") or "")
    if not target_name:
        return False

    normalized_target_name = normalize_target_name(target_name)
    if not name_matches_required_or_party_objective(args, snapshot, target_name):
        return False
    for add_name in parse_name_list(getattr(args, "objective_add_target_name", "")):
        normalized_add_name = normalize_target_name(add_name)
        if normalized_add_name and (
            normalized_add_name in normalized_target_name or normalized_target_name in normalized_add_name
        ):
            return False

    return bool(
        int(snapshot.get("leader_target_id", 0) or 0) > 0
        or str(snapshot.get("active_tank_name", "") or "").strip()
    )


def should_drop_objective_wait_for_recent_damage(
    behavior_state: DummyBehaviorState | str,
    selected_target_intent: TargetIntent | str,
    *,
    last_damage_taken_at: float,
    now: float,
    damage_grace_seconds: float = 3.0,
) -> bool:
    if not is_objective_travel_state(behavior_state):
        return False

    if last_damage_taken_at <= 0.0 or now - last_damage_taken_at > max(0.0, damage_grace_seconds):
        return False

    return False


def should_drop_required_retaliation_before_objective_ready(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    required_home_hunt_ready: bool,
    party_ready_for_objective: bool,
    is_party_follower: bool = False,
    leader_engaged: bool = True,
) -> bool:
    return bool(
        is_objective_travel_state(behavior_state)
        and not should_commit_required_retaliation_for_objective(
            args,
            behavior_state,
            required_home_hunt_ready=required_home_hunt_ready,
            party_ready_for_objective=party_ready_for_objective,
            is_party_follower=is_party_follower,
            leader_engaged=leader_engaged,
        )
    )


def should_mark_leader_target_engaged(
    args: argparse.Namespace,
    action_rotation: str,
    *,
    attack_enabled: bool,
    action_distance: float,
) -> bool:
    if not attack_enabled:
        return False

    if is_melee_rotation(action_rotation):
        attack_range = float(getattr(args, "attack_range", 0.0) or 0.0)
        if action_distance <= attack_range:
            return True
        if not getattr(args, "party_mark_pull_engaged", False):
            return False
        pull_distance = float(getattr(args, "party_pull_engage_distance", 0.0) or 0.0)
        if pull_distance <= 0.0:
            pull_distance = float(getattr(args, "melee_stick_attack_distance", 0.0) or 0.0)
        return pull_distance > 0.0 and action_distance <= pull_distance

    return True


def state_after_flee_start(behavior_state: DummyBehaviorState | str) -> DummyBehaviorState:
    if behavior_state_value(behavior_state) == DummyBehaviorState.DeadReleaseRecover.value:
        return DummyBehaviorState.DeadReleaseRecover
    return DummyBehaviorState.DropAggroAndRecover


def should_escape_after_death_recovery(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "flee_dynamic_safe_point", False) or getattr(args, "flee_home", None) is not None)


def should_allow_untracked_damage_counterattack(
    behavior_state: DummyBehaviorState | str,
    *,
    flee_until: float,
    now: float,
) -> bool:
    if now < flee_until:
        return False
    return behavior_state_value(behavior_state) not in {
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
    }


def should_healer_escape_direct_pressure(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    health_percent: int,
    party_snapshot: dict[str, int | float | str] | None = None,
    member_name: str = "",
    action_rotation: str = "",
) -> bool:
    if action_rotation != "healer-support":
        return False
    if behavior_state_value(behavior_state) != DummyBehaviorState.HuntObjective.value:
        return False

    threshold = int(getattr(args, "healer_focused_self_health_percent", 0) or 0)
    return bool(
        threshold > 0
        and 0 < int(health_percent or 0) <= threshold
        and healer_under_direct_party_pressure(party_snapshot, member_name)
    )


def should_force_drop_aggro_for_critical_health(
    args: argparse.Namespace,
    behavior_state: DummyBehaviorState | str,
    *,
    health_percent: int,
    party_snapshot: dict[str, int | float | str] | None = None,
    member_name: str = "",
    action_rotation: str = "",
    current_target: int = 0,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    now: float = 0.0,
    active_combat: dict[str, float | int | str] | None = None,
    current_target_removed_preserve_count: int = 0,
    last_damage_attacker_name: str = "",
) -> bool:
    critical_health = int(getattr(args, "flee_critical_health_percent", 0) or 0)
    commit_floor = int(getattr(args, "required_target_tank_commit_health_percent", 0) or 0)
    current_intent = target_intent_value(current_target_intent)
    if should_healer_escape_direct_pressure(
        args,
        behavior_state,
        health_percent=health_percent,
        party_snapshot=party_snapshot,
        member_name=member_name,
        action_rotation=action_rotation,
    ):
        return True

    if (
        critical_health > 0
        and commit_floor > 0
        and commit_floor < int(health_percent or 0) <= critical_health
        and current_target > 0
        and current_intent in {TargetIntent.party_rescue.value, TargetIntent.required_retaliation.value}
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
        and party_member_is_active_tank(party_snapshot, member_name)
    ):
        return False

    if (
        critical_health > 0
        and commit_floor > 0
        and commit_floor < int(health_percent or 0) <= critical_health
        and current_target > 0
        and current_intent
        in {
            TargetIntent.objective.value,
            TargetIntent.party_assist.value,
            TargetIntent.party_rescue.value,
            TargetIntent.required_retaliation.value,
        }
        and action_rotation == "melee-basic"
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
        and should_preserve_party_target_on_loss(args)
    ):
        return False

    if (
        critical_health > 0
        and commit_floor > 0
        and commit_floor < int(health_percent or 0) <= critical_health
        and current_target <= 0
        and int(current_target_removed_preserve_count or 0) > 0
        and action_rotation == "melee-basic"
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
        and name_matches_required_or_party_objective(args, party_snapshot, last_damage_attacker_name)
    ):
        return False

    snapshot = party_snapshot or {}
    healer_hold_floor = max(
        int(getattr(args, "flee_melee_counterattack_health_floor", 0) or 0),
        int(getattr(args, "required_target_tank_commit_health_percent", 0) or 0),
    )
    rescue_stabilize_floor = max(25, min(45, healer_hold_floor - 10 if healer_hold_floor > 10 else 25))
    normalized_member_name = normalize_target_name(member_name)
    active_tank_name = normalize_target_name(str(snapshot.get("active_tank_name", "") or ""))
    rescue_member_name = normalize_target_name(str(snapshot.get("rescue_member_name", "") or ""))
    active_tank_health = int(snapshot.get("active_tank_health_percent", 0) or 0)
    if (
        critical_health > 0
        and rescue_stabilize_floor > 0
        and rescue_stabilize_floor < int(health_percent or 0) <= critical_health
        and int(snapshot.get("rescue_target_id", 0) or 0) > 0
        and rescue_member_name == normalized_member_name
        and active_tank_name
        and active_tank_name != normalized_member_name
        and active_tank_health > rescue_stabilize_floor
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
    ):
        return False

    if (
        critical_health > 0
        and healer_hold_floor > 0
        and healer_hold_floor < int(health_percent or 0) <= critical_health
        and action_rotation == "healer-support"
        and int(snapshot.get("rescue_target_id", 0) or 0) > 0
        and int(snapshot.get("active_tank_health_percent", 0) or 0) > healer_hold_floor
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
    ):
        return False

    if (
        critical_health > 0
        and 0 < int(health_percent or 0) <= critical_health
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
        and should_party_tank_hold_required_objective_for_healer(
            args,
            party_snapshot,
            member_name,
            active_combat
            or {
                "target_id": int(current_target or 0),
                "target_name": str((party_snapshot or {}).get("leader_target_name", "") or ""),
                "intent": target_intent_value(current_target_intent),
            },
            health_percent=health_percent,
            now=now,
            action_rotation=action_rotation,
        )
    ):
        return False

    return bool(
        critical_health > 0
        and 0 < health_percent <= critical_health
        and behavior_state_value(behavior_state) == DummyBehaviorState.HuntObjective.value
    )


def next_state_after_drop_aggro_recovery(
    args: argparse.Namespace,
    *,
    health_percent: int,
    now: float,
    last_damage_taken_at: float,
    active_threat: bool,
) -> DummyBehaviorState:
    if active_threat:
        return DummyBehaviorState.DropAggroAndRecover

    clear_grace = drop_aggro_damage_clear_grace(args, health_percent=health_percent)
    if last_damage_taken_at > 0.0 and now - last_damage_taken_at < clear_grace:
        return DummyBehaviorState.DropAggroAndRecover

    if should_rest_after_flee_recovery(args, health_percent=health_percent):
        return DummyBehaviorState.RestRecover

    return DummyBehaviorState.ReturnToObjective


def drop_aggro_damage_clear_grace(args: argparse.Namespace, *, health_percent: int | None = None) -> float:
    clear_grace = float(getattr(args, "travel_aggro_clear_grace", 3.0) or 0.0)
    if (
        health_percent is not None
        and clear_grace >= 20.0
        and should_rest_after_flee_recovery(args, health_percent=health_percent)
    ):
        return max(clear_grace, clear_grace * 2.5)
    return clear_grace


def drop_aggro_clear_grace_remaining(
    args: argparse.Namespace,
    *,
    now: float,
    last_damage_taken_at: float,
    health_percent: int | None = None,
) -> float:
    clear_grace = drop_aggro_damage_clear_grace(args, health_percent=health_percent)
    if clear_grace <= 0.0 or last_damage_taken_at <= 0.0:
        return 0.0

    return max(0.0, clear_grace - (now - last_damage_taken_at))


def drop_aggro_recovery_duration(args: argparse.Namespace, *, health_percent: int | None = None) -> float:
    durations = [
        1.0,
        float(getattr(args, "flee_duration", 0.0) or 0.0),
        float(getattr(args, "travel_aggro_clear_grace", 0.0) or 0.0),
    ]
    if health_percent is None or should_rest_after_flee_recovery(args, health_percent=health_percent):
        durations.append(float(getattr(args, "low_health_rest_min", 0.0) or 0.0))

    return max(durations)


def drop_aggro_clear_hold_duration(
    args: argparse.Namespace,
    *,
    clear_remaining: float,
    health_percent: int,
) -> float:
    if should_rest_after_flee_recovery(args, health_percent=health_percent):
        return max(float(clear_remaining or 0.0), float(getattr(args, "low_health_rest_min", 0.0) or 0.0), 1.0)

    return max(float(clear_remaining or 0.0), 0.5)


def point_to_segment_distance(
    px: int | float,
    py: int | float,
    ax: int | float,
    ay: int | float,
    bx: int | float,
    by: int | float,
) -> float:
    abx = float(bx) - float(ax)
    aby = float(by) - float(ay)
    apx = float(px) - float(ax)
    apy = float(py) - float(ay)
    length_sq = abx * abx + aby * aby
    if length_sq <= 0.0:
        return math.hypot(apx, apy)

    t = max(0.0, min(1.0, (apx * abx + apy * aby) / length_sq))
    closest_x = float(ax) + abx * t
    closest_y = float(ay) + aby * t
    return math.hypot(float(px) - closest_x, float(py) - closest_y)


def travel_aggro_detour_destination(
    args: argparse.Namespace,
    client,
    objective: MovementDestination | None,
    *,
    danger_x: int,
    danger_y: int,
    danger_z: int,
    attempt_count: int = 1,
) -> MovementDestination | None:
    if client is None or objective is None or danger_x <= 0 or danger_y <= 0:
        return None

    origin_x = int(getattr(client, "x", 0) or 0)
    origin_y = int(getattr(client, "y", 0) or 0)
    origin_z = int(getattr(client, "z", 0) or danger_z or 0)
    if origin_x <= 0 or origin_y <= 0:
        return None

    avoid_radius = float(getattr(args, "travel_aggro_avoid_radius", 0.0) or 0.0)
    if avoid_radius <= 0.0:
        avoid_radius = max(2600.0, float(getattr(args, "flee_safe_threat_radius", 0.0) or 0.0) * 0.65)

    path_distance = point_to_segment_distance(
        danger_x,
        danger_y,
        origin_x,
        origin_y,
        objective.x,
        objective.y,
    )
    if path_distance > avoid_radius:
        return None

    route_x = float(objective.x - danger_x)
    route_y = float(objective.y - danger_y)
    route_len = math.hypot(route_x, route_y)
    if route_len <= 0.0:
        return None

    detour_distance = float(getattr(args, "travel_aggro_detour_distance", 0.0) or 0.0)
    if detour_distance <= 0.0:
        detour_distance = max(
            avoid_radius * 1.35,
            float(getattr(args, "flee_safe_point_distance", 0.0) or 0.0) * 0.75,
        )
    detour_distance *= 1.0 + max(0, int(attempt_count) - 1) * 0.25

    perp_x = -route_y / route_len
    perp_y = route_x / route_len
    sign = 1.0 if (
        (int(danger_x) // 100 + int(danger_y) // 100 + int(objective.x) // 100 + int(objective.y) // 100) % 2 == 0
    ) else -1.0
    best_x, best_y = (
        int(danger_x + perp_x * detour_distance * sign),
        int(danger_y + perp_y * detour_distance * sign),
    )
    return destination_from_point("travel-aggro-detour", best_x, best_y, origin_z, bucket=100)


def should_clear_travel_aggro_avoid_memory(
    args: argparse.Namespace,
    client,
    *,
    now: float,
    danger_until: float,
    danger_x: int,
    danger_y: int,
    last_damage_taken_at: float,
) -> bool:
    if client is None or danger_until <= 0.0 or now >= danger_until:
        return False

    if danger_x <= 0 or danger_y <= 0:
        return False

    clear_grace = float(getattr(args, "travel_aggro_clear_grace", 3.0) or 0.0)
    if last_damage_taken_at > 0.0 and now - last_damage_taken_at <= max(0.0, clear_grace):
        return False

    current_x = int(getattr(client, "x", 0) or 0)
    current_y = int(getattr(client, "y", 0) or 0)
    if current_x <= 0 or current_y <= 0:
        return False

    avoid_radius = float(getattr(args, "travel_aggro_avoid_radius", 0.0) or 0.0)
    if avoid_radius <= 0.0:
        avoid_radius = max(2600.0, float(getattr(args, "flee_safe_threat_radius", 0.0) or 0.0) * 0.65)

    detour_distance = float(getattr(args, "travel_aggro_detour_distance", 0.0) or 0.0)
    threat_radius = float(getattr(args, "flee_safe_threat_radius", 0.0) or 0.0)
    clear_distance = max(avoid_radius * 1.1, 3200.0)
    if detour_distance > 0.0:
        clear_distance = max(clear_distance, min(detour_distance, avoid_radius * 1.35))
    if threat_radius > 0.0:
        clear_distance = max(clear_distance, threat_radius * 0.75)

    return horizontal_distance_between_points(current_x, current_y, danger_x, danger_y) >= clear_distance


WATCHER_TRAVEL_AGGRO_FEEDBACK = {
    "bad_target_choice",
    "target_stuck",
    "wrong_target",
    "wrong-target",
}


def state_after_watcher_feedback(
    behavior_state: DummyBehaviorState | str,
    feedback_reason: str,
) -> DummyBehaviorState | str:
    if is_objective_travel_state(behavior_state) and str(feedback_reason or "").strip().lower() in WATCHER_TRAVEL_AGGRO_FEEDBACK:
        return DummyBehaviorState.HandleTravelAggro

    return behavior_state


def first_configured_target_name(*values: str) -> str:
    for value in values:
        for part in str(value or "").split(","):
            token = part.strip()
            if token:
                return token
    return ""


def passes_required_target_filter(args: argparse.Namespace, npc) -> bool:
    tokens = required_target_tokens(args)
    return not tokens or any(required_target_name_matches_for_args(args, npc.name, token) for token in tokens)


def passes_hunter_target_level_filter(args: argparse.Namespace, npc) -> bool:
    if npc is None:
        return False
    min_level = int(getattr(args, "min_target_level", 0) or 0)
    max_level = int(getattr(args, "max_target_level", -1) or -1)
    if max_level < 0:
        max_level = int(getattr(args, "player_level", 0) or 0) + int(getattr(args, "max_target_level_delta", 0) or 0)
    npc_level = int(getattr(npc, "level", 0) or 0)
    return npc_level >= min_level and (max_level < 0 or npc_level <= max_level)


def preferred_low_con_fallback_allowed(args: argparse.Namespace, client, npc) -> bool:
    if npc is None or not getattr(args, "allow_preferred_low_con_fallback", False):
        return False
    prefer_tokens = preferred_target_tokens(args)
    if not prefer_tokens or not any(token in str(getattr(npc, "name", "") or "").lower() for token in prefer_tokens):
        return False
    min_level = int(getattr(args, "preferred_low_con_min_level", 0) or 0)
    npc_level = int(getattr(npc, "level", 0) or 0)
    if npc_level < min_level:
        return False
    if getattr(args, "max_target_distance", 0.0) > 0 and combat_distance_to(client, npc) > float(args.max_target_distance):
        return False
    target_home = getattr(args, "required_target_home", None)
    target_home_max_distance = float(getattr(args, "target_home_max_distance", 0.0) or 0.0)
    if target_home is not None and target_home_max_distance > 0.0:
        home_distance = horizontal_distance_between_points(
            int(getattr(target_home, "x", 0) or 0),
            int(getattr(target_home, "y", 0) or 0),
            int(getattr(npc, "x", 0) or 0),
            int(getattr(npc, "y", 0) or 0),
        )
        if home_distance > target_home_max_distance:
            return False
    if not hunter_target_ground_z_aligned(args, client, npc):
        return False
    max_level = int(getattr(args, "max_target_level", -1) or -1)
    if max_level < 0:
        max_level = int(getattr(args, "player_level", 0) or 0) + int(getattr(args, "max_target_level_delta", 0) or 0)
    return max_level < 0 or npc_level <= max_level


def should_accept_party_rescue_target(args: argparse.Namespace, npc) -> bool:
    if npc is None or is_foreign_required_test_clone(args, npc):
        return False

    player_level = int(getattr(args, "player_level", 0) or 0)
    npc_level = int(getattr(npc, "level", 0) or 0)
    low_level_delta = int(getattr(args, "party_rescue_ignore_low_level_delta", 8) or 0)
    if (
        low_level_delta > 0
        and player_level > 0
        and npc_level > 0
        and player_level - npc_level >= low_level_delta
        and not is_required_target(args, npc)
        and not is_objective_add_target(args, npc)
    ):
        return False

    if getattr(args, "party_encounter_mode", "standard") == "standard":
        if player_level > 0:
            max_level = int(getattr(args, "max_target_level", -1) or -1)
            if max_level < 0:
                max_level = player_level + int(getattr(args, "max_target_level_delta", 0) or 0)
            if max_level >= 0 and int(getattr(npc, "level", 0) or 0) > max_level:
                return False

    return True


def is_foreign_required_test_clone(args: argparse.Namespace, npc) -> bool:
    name = str(getattr(npc, "name", "") or "")
    return bool(name.startswith("KDAOC_TEST_") and not is_required_target(args, npc))


def horizontal_distance_between_points(ax: int | float, ay: int | float, bx: int | float, by: int | float) -> float:
    return math.hypot(float(ax) - float(bx), float(ay) - float(by))


def party_objective_distance_to_npc(party_snapshot: dict[str, int | float | str], npc) -> float:
    return horizontal_distance_between_points(
        int(party_snapshot.get("leader_target_x", 0) or 0),
        int(party_snapshot.get("leader_target_y", 0) or 0),
        int(getattr(npc, "x", 0) or 0),
        int(getattr(npc, "y", 0) or 0),
    )


def is_rescue_threat_near_party_objective(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
) -> bool:
    max_distance = float(getattr(args, "party_rescue_objective_max_distance", 0.0) or 0.0)
    if max_distance <= 0 or party_snapshot is None:
        return False

    if int(party_snapshot.get("leader_target_id", 0) or 0) <= 0:
        return False

    if int(party_snapshot.get("leader_target_x", 0) or 0) == 0 and int(party_snapshot.get("leader_target_y", 0) or 0) == 0:
        return False

    return party_objective_distance_to_npc(party_snapshot, npc) <= max_distance


def is_party_objective_add_rescue_threat(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
) -> bool:
    if is_foreign_required_test_clone(args, npc):
        return False

    if is_objective_add_target(args, npc):
        return True

    return bool(
        is_rescue_threat_near_party_objective(args, party_snapshot, npc)
        and npc_name_matches_party_objective_add(args, party_snapshot, npc)
    )


def party_objective_add_rescue_max_distance(args: argparse.Namespace) -> float:
    return max(
        float(getattr(args, "party_rescue_objective_max_distance", 0.0) or 0.0),
        float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0),
        float(getattr(args, "max_target_distance", 2200.0) or 0.0),
    )


def is_party_objective_add_rescue_threat_in_range(
    client,
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
    *,
    proven_objective_add: bool = False,
) -> bool:
    if not proven_objective_add and not is_party_objective_add_rescue_threat(args, party_snapshot, npc):
        return False

    if is_rescue_threat_near_party_objective(args, party_snapshot, npc):
        return True

    max_distance = party_objective_add_rescue_max_distance(args)
    return max_distance <= 0.0 or combat_distance_to(client, npc) <= max_distance


def is_party_combat_proven_encounter_add(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
) -> bool:
    if party_snapshot is None or npc is None:
        return False

    if int(party_snapshot.get("leader_target_id", 0) or 0) <= 0:
        return False

    if float(party_snapshot.get("leader_target_engaged_at", 0.0) or 0.0) <= 0.0:
        return False

    return bool(
        not is_required_target(args, npc)
        and not is_foreign_required_test_clone(args, npc)
        and should_accept_party_rescue_target(args, npc)
    )


def is_combat_proven_party_objective_add(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    npc,
) -> bool:
    return bool(
        is_party_objective_add_rescue_threat(args, party_snapshot, npc)
        or is_party_combat_proven_encounter_add(args, party_snapshot, npc)
    )


def choose_party_rescue_attacker(
    client,
    args: argparse.Namespace,
    leader_target_id: int,
    party_snapshot: dict[str, int | float | str] | None = None,
    objective_scan_only: bool = False,
):
    rescue_candidates = [
        npc
        for npc in client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args))
        if npc.object_id != leader_target_id
        and not is_required_target(args, npc)
        and should_accept_party_rescue_target(args, npc)
        and (
            is_party_objective_add_rescue_threat_in_range(client, args, party_snapshot, npc)
            if objective_scan_only
            else is_rescue_threat_in_range(
                client,
                npc,
                args,
                args.party_rescue_max_distance,
                party_snapshot=party_snapshot,
            )
        )
    ]

    if not rescue_candidates:
        return None

    return min(
        rescue_candidates,
        key=lambda npc: (
            0 if is_party_objective_add_rescue_threat(args, party_snapshot, npc) else 1,
            combat_distance_to(client, npc),
        ),
    )


PARTY_ATTACK_PATTERNS = (
    re.compile(
        r"^(?P<attacker>.+?)\s+attacks\s+(?P<victim>.+?)\s+and\s+"
        r"(?:hits|misses|is\s+blocked|is\s+parried|is\s+evaded)!?$",
        re.IGNORECASE,
    ),
)


KOREAN_INCOMING_DAMAGE_ATTACKER_PATTERN = re.compile(
    r"^(?P<attacker>.+?)(?:이\(가\)|이|가)\s*당신(?:의\s*.+?(?:에게|에)|에게)\s+(?P<amount>\d+)(?:\s*\([^)]*\))?\s*피해를\s+입혔습니다!?\s*$",
    re.IGNORECASE,
)


INCOMING_ATTACK_ATTEMPT_PATTERNS = (
    re.compile(
        r"^(?P<attacker>.+?)\s+attacks\s+you\s+and\s+"
        r"(?:hits|misses|is\s+blocked|is\s+parried|is\s+evaded)!?(?:\s+\([^)]*\))?$",
        re.IGNORECASE,
    ),
    re.compile(
        "^(?P<attacker>.+?)(?:\uc774\\(\uac00\\)|\uac00|\uc774)\\s+"
        "\uacf5\uaca9\ud588\uc9c0\ub9cc\\s+"
        "\ube57\ub098\uac14\uc2b5\ub2c8\ub2e4!?(?:\\s+\\([^)]*\\))?$",
        re.IGNORECASE,
    ),
)


def parse_incoming_damage_attacker_name(text: str) -> str:
    match = KOREAN_INCOMING_DAMAGE_ATTACKER_PATTERN.match(str(text or "").strip())
    if match is None:
        return ""

    return match.group("attacker").strip()


def parse_incoming_attack_attacker_name(text: str) -> str:
    damage_attacker = parse_incoming_damage_attacker_name(text)
    if damage_attacker:
        return damage_attacker

    normalized = str(text or "").strip()
    for pattern in INCOMING_ATTACK_ATTEMPT_PATTERNS:
        match = pattern.match(normalized)
        if match is not None:
            return match.group("attacker").strip()

    return ""


def latest_aggro_pressure_at(*, last_damage_taken_at: float, last_incoming_damage_at: float) -> float:
    return max(float(last_damage_taken_at or 0.0), float(last_incoming_damage_at or 0.0))


def parse_korean_incoming_damage_amount(text: str) -> int:
    match = KOREAN_INCOMING_DAMAGE_ATTACKER_PATTERN.match(str(text or "").strip())
    if match is None:
        return 0

    return int(match.group("amount"))


def parse_party_attack_message(text: str, member_names: list[str]) -> PartyAttackMessage | None:
    normalized = str(text or "").strip()
    if not normalized:
        return None

    member_names_by_normalized = {
        normalize_target_name(member_name): member_name
        for member_name in member_names
        if normalize_target_name(member_name)
    }

    if not member_names_by_normalized:
        return None

    for pattern in PARTY_ATTACK_PATTERNS:
        match = pattern.match(normalized)
        if match is None:
            continue

        victim_name = member_names_by_normalized.get(normalize_target_name(match.group("victim")))
        if not victim_name:
            return None

        return PartyAttackMessage(match.group("attacker").strip(), victim_name)

    return None


PARTY_JOIN_PATTERNS = [
    re.compile(r"^(?P<member>.+?)이\(가\) 그룹에 참가했습니다\.$", re.IGNORECASE),
    re.compile(r"^(?P<member>.+?) has joined (?:the )?group\.$", re.IGNORECASE),
    re.compile(r"^(?P<member>.+?) joins (?:the )?group\.$", re.IGNORECASE),
]


def parse_party_member_join_message(text: str) -> str:
    normalized = str(text or "").strip()
    if not normalized:
        return ""

    for pattern in PARTY_JOIN_PATTERNS:
        match = pattern.match(normalized)
        if match is not None:
            return match.group("member").strip()

    return ""


PARTY_DEATH_PATTERNS = [
    # Killed by an identified attacker (with/without location):
    #   "{0}이(가) {1}에게 사망했습니다." / "{0}이(가) {2}에서 {1}에게 사망했습니다."
    re.compile(r"^(?P<member>.+?)\uC774\(\uAC00\) .+?\uC5D0\uAC8C \uC0AC\uB9DD\uD588\uC2B5\uB2C8\uB2E4\.$", re.IGNORECASE),
    # Killer-less / environmental death (drowning, falling, GM/test kill, corpse notice):
    #   "{0}이(가) 사망했습니다!"            (Die.Killed)
    #   "{0}이(가) {1}에서 사망했습니다!"     (Die.KilledLocation)
    #   "{0}이(가) 사망했습니다. {1}의 시체가 땅에 놓여 있습니다."  (Die.CorpseLies)
    re.compile(r"^(?P<member>.+?)\uC774\(\uAC00\) (?:.+?\uC5D0\uC11C )?\uC0AC\uB9DD\uD588\uC2B5\uB2C8\uB2E4[.!]", re.IGNORECASE),
    # English killed-by (optionally "just", with/without location):
    #   "{0} was just killed by {1}." / "{0} was just killed by {1} in {2}."
    re.compile(r"^(?P<member>.+?) was (?:just )?killed by .+", re.IGNORECASE),
    # English killer-less / environmental death:
    #   "{0} was just killed!" / "{0} was just killed in {1}!" / "{0} just died. ..."
    re.compile(r"^(?P<member>.+?) (?:was just killed|just died)(?: in .+)?[.!]", re.IGNORECASE),
]


def parse_party_member_death_message(text: str, member_names: list[str]) -> str:
    normalized = str(text or "").strip()
    if not normalized:
        return ""

    member_names_by_normalized = {
        normalize_target_name(member_name): member_name
        for member_name in member_names
        if normalize_target_name(member_name)
    }

    for pattern in PARTY_DEATH_PATTERNS:
        match = pattern.match(normalized)
        if match is None:
            continue

        member_name = member_names_by_normalized.get(normalize_target_name(match.group("member")))
        if member_name:
            return member_name

    return ""


def apply_party_member_death_message(party_state: PartyState | None, text: str) -> str:
    if party_state is None:
        return ""

    member_name = parse_party_member_death_message(text, list(party_state.member_names))
    if not member_name:
        return ""

    known_condition = party_state.member_conditions.get(member_name)
    object_id = int(getattr(known_condition, "object_id", 0) or party_state.member_object_ids.get(member_name, 0) or 0)
    x, y, z = party_state.member_positions.get(member_name, (0, 0, 0))

    party_state.update_member_condition(
        member_name,
        PlayerConditionSnapshot(
            name=member_name,
            account=str(getattr(known_condition, "account", "") or ""),
            object_id=object_id,
            level=int(getattr(known_condition, "level", 0) or 0),
            class_name=str(getattr(known_condition, "class_name", "") or ""),
            class_id=int(getattr(known_condition, "class_id", 0) or 0),
            realm=int(getattr(known_condition, "realm", 0) or 0),
            health_percent=0,
            x=int(x or 0),
            y=int(y or 0),
            z=int(z or 0),
            is_alive=False,
            is_stunned=bool(getattr(known_condition, "is_stunned", False)),
            is_mezzed=bool(getattr(known_condition, "is_mezzed", False)),
            is_diseased=bool(getattr(known_condition, "is_diseased", False)),
            is_poisoned=bool(getattr(known_condition, "is_poisoned", False)),
            is_nearsighted=bool(getattr(known_condition, "is_nearsighted", False)),
            is_silenced=bool(getattr(known_condition, "is_silenced", False)),
            target_object_id=int(getattr(known_condition, "target_object_id", 0) or 0),
            target_name=str(getattr(known_condition, "target_name", "") or ""),
            is_companion=bool(getattr(known_condition, "is_companion", False)),
            companion_role=str(getattr(known_condition, "companion_role", "") or ""),
        ),
    )
    return member_name


def choose_attack_message_rescue_attacker(
    npcs,
    client,
    args: argparse.Namespace,
    leader_target_id: int,
    attacker_name: str,
    preferred_target_id: int = 0,
):
    attacker_key = normalize_target_name(attacker_name)
    if not attacker_key:
        return None

    candidates = [
        npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
        and normalize_target_name(str(getattr(npc, "name", "") or "")) == attacker_key
        and should_accept_party_rescue_target(args, npc)
        and not target_home_leash_violation(client, args, npc)[0]
        and (
            float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0) <= 0.0
            or combat_distance_to(client, npc) <= float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0)
        )
    ]

    if not candidates:
        return None

    return min(
        candidates,
        key=lambda npc: (
            0 if int(getattr(npc, "object_id", 0) or 0) == preferred_target_id else 1,
            0 if int(getattr(npc, "object_id", 0) or 0) == leader_target_id else 1,
            combat_distance_to(client, npc),
        ),
    )


def choose_named_rescue_attacker(
    npcs,
    client,
    args: argparse.Namespace,
    leader_target_id: int,
    attacker_name: str,
    preferred_target_id: int = 0,
):
    attacker_key = normalize_target_name(attacker_name)
    if not attacker_key:
        return None

    candidates = [
        npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
        and normalize_target_name(str(getattr(npc, "name", "") or "")) == attacker_key
        and should_accept_party_rescue_target(args, npc)
        and not target_home_leash_violation(client, args, npc)[0]
    ]

    if not candidates:
        return None

    return min(
        candidates,
        key=lambda npc: (
            0 if int(getattr(npc, "object_id", 0) or 0) == preferred_target_id else 1,
            0 if int(getattr(npc, "object_id", 0) or 0) == leader_target_id else 1,
            combat_distance_to(client, npc),
        ),
    )


def refresh_exact_rescue_threat_from_attacker_name(
    party_state: PartyState | None,
    client,
    args: argparse.Namespace,
    party_member_name: str,
    attacker_name: str,
) -> bool:
    if party_state is None or not attacker_name:
        return False

    party_snapshot = party_state.snapshot()
    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    preferred_target_id = int(party_snapshot.get("rescue_target_id", 0) or 0) or leader_target_id
    attacker = choose_named_rescue_attacker(
        client.visible_npcs(max_age=args.npc_max_age, include_peace=should_scan_peace_npcs(args)),
        client,
        args,
        leader_target_id,
        attacker_name,
        preferred_target_id=preferred_target_id,
    )
    if attacker is None:
        return False

    objective_add = is_combat_proven_party_objective_add(args, party_snapshot, attacker)
    if party_state.request_rescue(
        party_member_name,
        attacker,
        leader_target_id=leader_target_id,
        min_hold=args.party_rescue_min_hold,
        objective_add=objective_add,
    ):
        return True

    return party_state.record_rescue_threat(party_member_name, attacker, objective_add=objective_add)


def should_party_member_use_local_rescue_target(args: argparse.Namespace, action_rotation: str, health_percent: int) -> bool:
    if not getattr(args, "party_local_rescue_target", False):
        return False

    if action_rotation == "healer-support":
        if should_preserve_party_target_on_loss(args):
            return False

        threshold = int(getattr(args, "party_healer_local_rescue_health_percent", 0) or 0)
        return threshold > 0 and 0 < health_percent <= threshold

    if action_rotation == "caster-basic":
        return bool(getattr(args, "party_caster_assist_rescue_target", False))

    return True


def local_rescue_window_active(now: float, local_rescue_until: float) -> bool:
    return local_rescue_until > 0 and now <= local_rescue_until


def should_hold_party_assist_for_local_rescue(
    args: argparse.Namespace,
    *,
    now: float,
    local_rescue_until: float,
    current_target: int,
    leader_target_id: int,
) -> bool:
    return bool(
        getattr(args, "party_local_rescue_target", False)
        and local_rescue_window_active(now, local_rescue_until)
        and current_target > 0
        and current_target != leader_target_id
    )


def should_hold_party_assist_for_rescue_target(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    *,
    now: float,
    current_target: int,
    party_member_name: str,
    action_rotation: str,
    health_percent: int,
) -> bool:
    if not getattr(args, "party_rescue_aggro", False) or current_target <= 0:
        return False

    rescue_target_id = int(party_snapshot.get("rescue_target_id", 0) or 0)
    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)

    if rescue_target_id <= 0 or current_target != rescue_target_id or current_target == leader_target_id:
        return False

    rescue_age = party_rescue_target_age(party_snapshot, rescue_target_id, now)
    max_age = max(0.0, float(getattr(args, "party_rescue_max_age", 0.0) or 0.0))

    if rescue_age < 0.0 or (max_age > 0.0 and rescue_age > max_age):
        return False

    return should_party_member_handle_rescue_target(
        args,
        party_snapshot,
        party_member_name,
        action_rotation,
        health_percent,
        rescue_age=rescue_age,
    )


def choose_party_rescue_threat_target(
    npcs,
    client,
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    *,
    member_name: str,
    action_rotation: str,
    health_percent: int,
    now: float,
    current_target: int = 0,
):
    if not getattr(args, "party_rescue_aggro", False):
        return None

    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    visible_by_id = {
        int(getattr(npc, "object_id", 0) or 0): npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
    }
    max_age = max(0.0, float(getattr(args, "party_rescue_max_age", 0.0) or 0.0))
    max_distance = max(0.0, float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0))
    candidates: list[dict[str, object]] = []

    for threat in party_snapshot.get("rescue_threats", []) or []:
        if not isinstance(threat, dict):
            continue

        threat_id = int(threat.get("object_id", 0) or 0)
        if threat_id <= 0 or threat_id == leader_target_id:
            continue

        requested_at = float(threat.get("requested_at", 0.0) or 0.0)
        threat_age = now - requested_at
        if threat_age < 0.0 or (max_age > 0.0 and threat_age > max_age):
            continue

        npc = visible_by_id.get(threat_id)
        if npc is None or not should_accept_party_rescue_target(args, npc):
            continue

        objective_add = bool(threat.get("objective_add", True))
        distance = combat_distance_to(client, npc)
        if objective_add:
            if not is_party_objective_add_rescue_threat_in_range(
                client,
                args,
                party_snapshot,
                npc,
                proven_objective_add=True,
            ):
                continue
        elif max_distance > 0.0 and distance > max_distance:
            continue

        candidates.append(
            {
                "id": threat_id,
                "age": threat_age,
                "objective_add": objective_add,
                "member_name": str(threat.get("member_name", "") or ""),
                "victim_role": party_member_role(party_snapshot, str(threat.get("member_name", "") or "")),
                "distance": distance,
                "npc": npc,
            }
        )

    if not candidates:
        return None

    def can_handle(candidate: dict[str, object], name: str, role: str, hp: int) -> bool:
        if leader_target_id <= 0 and is_party_tank_role(role):
            return True

        victim_name = str(candidate.get("member_name", "") or "")
        victim_role = str(candidate.get("victim_role", "") or "")
        victim_health = party_member_health_percent(party_snapshot, victim_name)
        peer_rescue_threshold = int(getattr(args, "party_rescue_peer_health_percent", 0) or 0)
        peer_rescue_is_urgent = bool(
            victim_name
            and peer_rescue_threshold > 0
            and 0 < victim_health <= peer_rescue_threshold
        )

        if (
            bool(candidate["objective_add"])
            and (party_member_is_rescue_tank(party_snapshot, name) or role in {"melee-basic", "hybrid"})
            and not should_party_member_hold_shared_objective(args, party_snapshot, name)
            and (
                not victim_name
                or is_support_pressure_role(victim_role)
                or peer_rescue_is_urgent
            )
        ):
            return True

        return should_party_member_handle_rescue_target(
            args,
            {
                **party_snapshot,
                "rescue_target_objective_add": bool(candidate["objective_add"]),
                "rescue_member_name": victim_name,
            },
            name,
            role,
            hp,
            rescue_age=float(candidate["age"]),
        )

    if current_target:
        current_candidate = next(
            (
                candidate
                for candidate in candidates
                if int(candidate["id"]) == current_target
                and str(candidate.get("member_name", "") or "")
                and can_handle(candidate, member_name, action_rotation, health_percent)
            ),
            None,
        )
        if current_candidate is not None:
            return current_candidate["npc"]

    support_focus_candidates = [
        candidate
        for candidate in candidates
        if should_assist_dangerous_support_rescue_threat(
            args,
            action_rotation,
            float(candidate["age"]),
            str(candidate.get("victim_role", "") or ""),
        )
    ]
    if (
        support_focus_candidates
        and not should_party_member_hold_shared_objective(args, party_snapshot, member_name)
    ):
        return min(
            support_focus_candidates,
            key=lambda candidate: (
                0 if current_target and int(candidate["id"]) == current_target else 1,
                -float(candidate["age"]),
                float(candidate["distance"]),
                int(candidate["id"]),
            ),
        )["npc"]

    if not can_handle(
        min(candidates, key=lambda candidate: (float(candidate["distance"]), int(candidate["id"]))),
        member_name,
        action_rotation,
        health_percent,
    ) and not any(can_handle(candidate, member_name, action_rotation, health_percent) for candidate in candidates):
        return None

    members = party_snapshot.get("members", []) or []
    if isinstance(members, list) and len(members) > 1:
        eligible_names: list[str] = []

        for member in members:
            if not isinstance(member, dict):
                continue

            candidate_name = str(member.get("name", "") or "")
            candidate_role = str(member.get("role", "") or "")
            candidate_health = int(member.get("health_percent", 0) or 0)
            if not candidate_name or candidate_health <= 0:
                continue

            if any(can_handle(candidate, candidate_name, candidate_role, candidate_health) for candidate in candidates):
                eligible_names.append(candidate_name)

        if member_name not in eligible_names:
            return None

        member_index = eligible_names.index(member_name)
        assigned_candidates = [
            candidate
            for index, candidate in enumerate(sorted(candidates, key=lambda item: int(item["id"])))
            if index % len(eligible_names) == member_index
        ]
        for candidate in assigned_candidates:
            if can_handle(candidate, member_name, action_rotation, health_percent):
                return candidate["npc"]

        return None

    fallback_candidates = [
        (
            0 if current_target and int(candidate["id"]) == current_target else 1,
            float(candidate["distance"]),
            int(candidate["id"]),
            candidate["npc"],
        )
        for candidate in candidates
        if can_handle(candidate, member_name, action_rotation, health_percent)
    ]
    if not fallback_candidates:
        return None

    return min(fallback_candidates, key=lambda candidate: (candidate[0], candidate[1], candidate[2]))[3]


def current_target_is_party_rescue_target(party_snapshot: dict[str, int | float | str], current_target: int) -> bool:
    return bool(current_target > 0 and int(party_snapshot.get("rescue_target_id", 0) or 0) == current_target)


def active_combat_has_contact(active_combat: dict[str, float | int | str] | None) -> bool:
    if active_combat is None:
        return False

    return any(
        int(active_combat.get(key, 0) or 0) > 0
        for key in ("attacks", "skills", "damage_done", "damage_taken")
    )


def active_combat_intent(active_combat: dict[str, float | int | str] | None) -> str:
    return str((active_combat or {}).get("target_intent", "") or "")


def current_target_bypasses_target_home_leash(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    current_target: int,
    *,
    current_target_intent: TargetIntent | str = TargetIntent.none,
    npc=None,
    active_combat: dict[str, float | int | str] | None = None,
    leash_reason: str = "",
) -> bool:
    if not getattr(args, "party_rescue_aggro", False) or current_target <= 0:
        return False

    if leash_reason and leash_reason != "player":
        return False

    if npc is not None and not target_within_combat_home_leash(args, npc):
        return False

    if current_target_is_party_rescue_target(party_snapshot, current_target):
        return True

    current_intent = target_intent_value(current_target_intent)
    rescue_intents = {TargetIntent.party_rescue.value, TargetIntent.required_retaliation.value}
    shared_objective_intents = {
        TargetIntent.objective.value,
        TargetIntent.party_assist.value,
        TargetIntent.current_target_confirm.value,
        *rescue_intents,
    }
    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    leader_engaged = float(party_snapshot.get("leader_target_engaged_at", 0.0) or 0.0) > 0.0
    if leader_engaged and current_target == leader_target_id and current_intent in shared_objective_intents:
        return True

    active_target_id = int((active_combat or {}).get("target_id", 0) or 0)
    return bool(
        current_intent in rescue_intents
        and active_target_id == current_target
        and active_combat_has_contact(active_combat)
    )


def should_preserve_active_party_rescue_focus(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
    current_target: int,
    current_target_intent: TargetIntent | str,
) -> bool:
    if active_combat is None:
        return False

    active_target_id = int(active_combat.get("target_id", 0) or 0)
    if active_target_id <= 0:
        return False

    if current_target > 0 and active_target_id != current_target:
        return False

    intent = target_intent_value(current_target_intent) or active_combat_intent(active_combat)
    if intent == TargetIntent.none.value:
        intent = active_combat_intent(active_combat)
    if intent not in {TargetIntent.party_rescue.value, TargetIntent.required_retaliation.value} and not active_combat_matches_required_target(args, active_combat):
        return False

    return active_combat_has_contact(active_combat)


def active_combat_matches_preferred_target(args: argparse.Namespace, active_combat: dict[str, float | int | str] | None) -> bool:
    if active_combat is None:
        return False

    target_name = str(active_combat.get("target_name", "")).lower()
    tokens = preferred_target_tokens(args)
    return bool(target_name and tokens and any(required_target_name_matches(target_name, token) for token in tokens))


def should_block_active_combat_target_switch(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
    *,
    candidate_target_id: int,
    candidate_target_intent: TargetIntent | str,
    current_target: int,
    current_target_intent: TargetIntent | str,
    behavior_state: DummyBehaviorState | str,
    flee_active: bool,
    rest_active: bool,
    drop_aggro_active: bool,
) -> bool:
    if active_combat is None:
        return False

    active_target_id = int(active_combat.get("target_id", 0) or 0)
    if active_target_id <= 0 or int(candidate_target_id or 0) <= 0:
        return False
    if int(candidate_target_id) == active_target_id:
        return False

    state = behavior_state_value(behavior_state)
    if (
        flee_active
        or rest_active
        or drop_aggro_active
        or state
        in {
            DummyBehaviorState.DropAggroAndRecover.value,
            DummyBehaviorState.RestRecover.value,
            DummyBehaviorState.DeadReleaseRecover.value,
        }
    ):
        return False

    if not active_combat_has_contact(active_combat):
        return False

    rescue_intents = {TargetIntent.party_rescue.value, TargetIntent.required_retaliation.value}
    active_intent = active_combat_intent(active_combat)
    if active_intent == TargetIntent.none.value:
        active_intent = ""
    if not active_intent:
        active_intent = target_intent_value(current_target_intent)

    candidate_intent = target_intent_value(candidate_target_intent)
    if (
        active_intent == TargetIntent.objective.value
        and active_combat_matches_preferred_target(args, active_combat)
        and candidate_intent
        in {
            TargetIntent.objective.value,
            TargetIntent.party_assist.value,
            TargetIntent.party_rescue.value,
            TargetIntent.required_retaliation.value,
            TargetIntent.current_target_confirm.value,
        }
    ):
        return True

    if not getattr(args, "party_rescue_aggro", False):
        return False

    return bool(
        active_intent in rescue_intents
        or active_combat_matches_required_target(args, active_combat)
    )


def should_abandon_party_rescue_counterattack_for_flee(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    *,
    current_target: int,
    current_health_percent: int,
    previous_health_percent: int,
    member_name: str = "",
) -> bool:
    health_floor = int(getattr(args, "flee_melee_counterattack_health_floor", 0) or 0)
    target_name = ""
    if int(party_snapshot.get("leader_target_id", 0) or 0) == int(current_target or 0):
        target_name = str(party_snapshot.get("leader_target_name", "") or "")
    elif int(party_snapshot.get("rescue_target_id", 0) or 0) == int(current_target or 0):
        target_name = str(party_snapshot.get("rescue_target_name", "") or "")

    critical_health = int(getattr(args, "flee_critical_health_percent", 0) or 0)
    if (
        name_matches_required_target(args, target_name)
        and party_member_is_active_tank(party_snapshot, member_name)
        and party_snapshot_has_live_healer_support(party_snapshot, exclude_name=member_name)
        and (critical_health <= 0 or int(current_health_percent or 0) > critical_health)
    ):
        return False

    return bool(
        health_floor > 0
        and current_target_bypasses_target_home_leash(args, party_snapshot, current_target)
        and previous_health_percent > 0
        and current_health_percent > 0
        and current_health_percent < previous_health_percent
        and current_health_percent <= health_floor
    )


def party_member_role(snapshot: dict[str, int | float | str], member_name: str) -> str:
    if not member_name:
        return ""

    for member in snapshot.get("members", []) or []:
        if not isinstance(member, dict):
            continue

        if str(member.get("name", "") or "") == member_name:
            return str(member.get("role", "") or "")

    return ""


def party_member_health_percent(snapshot: dict[str, int | float | str], member_name: str) -> int:
    if not member_name:
        return 0

    for member in snapshot.get("members", []) or []:
        if not isinstance(member, dict):
            continue

        if str(member.get("name", "") or "") == member_name:
            return int(member.get("health_percent", 0) or 0)

    return 0


def is_support_pressure_role(role: str) -> bool:
    return role in {"healer-support", "caster-basic"}


def party_rescue_threat_victim_role(
    snapshot: dict[str, int | float | str],
    target_id: int,
) -> str:
    threat = party_rescue_threat_snapshot(snapshot, target_id)
    if threat is None:
        return ""

    return party_member_role(snapshot, str(threat.get("member_name", "") or ""))


def should_assist_dangerous_support_rescue_threat(
    args: argparse.Namespace,
    action_rotation: str,
    rescue_age: float,
    victim_role: str,
) -> bool:
    if action_rotation == "healer-support" or not is_support_pressure_role(victim_role):
        return False

    if action_rotation == "caster-basic" and not getattr(args, "party_caster_assist_rescue_target", False):
        return False

    if not is_party_tank_role(action_rotation) and action_rotation != "caster-basic":
        return False

    assist_after = max(0.0, float(getattr(args, "party_rescue_emergency_assist_after", 0.0) or 0.0))
    if assist_after <= 0.0:
        return False

    return rescue_age >= assist_after


def is_rescue_threat_in_range(
    client,
    npc,
    args: argparse.Namespace,
    max_distance: float,
    party_snapshot: dict[str, int | float | str] | None = None,
) -> bool:
    distance = combat_distance_to(client, npc)

    if max_distance > 0 and distance > max_distance:
        return False

    engaged_distance = float(getattr(args, "party_rescue_engaged_distance", 0.0) or 0.0)
    return engaged_distance <= 0 or distance <= engaged_distance or is_party_objective_add_rescue_threat(args, party_snapshot, npc)


def choose_local_rescue_target(npcs, client, args: argparse.Namespace, leader_target_id: int, current_target: int = 0):
    max_distance = float(getattr(args, "party_local_rescue_max_distance", 0.0) or 0.0)
    rescue_candidates = [
        npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
        and npc.object_id != leader_target_id
        and not is_required_target(args, npc)
        and should_accept_party_rescue_target(args, npc)
        and is_rescue_threat_in_range(client, npc, args, max_distance)
    ]

    if not rescue_candidates:
        return None

    if current_target:
        for npc in rescue_candidates:
            if npc.object_id == current_target:
                return npc

    return min(rescue_candidates, key=lambda npc: combat_distance_to(client, npc))


def choose_party_support_evasion_threat(
    npcs,
    client,
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    *,
    action_rotation: str,
    now: float,
    local_rescue_until: float,
    precast_movement_hold: bool = False,
):
    if not bool(getattr(args, "party_support_evasion", False)):
        return None

    del precast_movement_hold

    if action_rotation not in {"caster-basic", "healer-support"}:
        return None

    if not getattr(args, "party_rescue_aggro", False):
        return None

    if should_preserve_party_target_on_loss(args) and float(party_snapshot.get("leader_target_engaged_at", 0.0) or 0.0) <= 0.0:
        return None

    local_rescue_active = local_rescue_window_active(now, local_rescue_until)
    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    max_age = max(0.0, float(getattr(args, "party_rescue_max_age", 0.0) or 0.0))
    max_distance = max(0.0, float(getattr(args, "party_rescue_max_distance", 0.0) or 0.0))
    visible_by_id = {
        int(getattr(npc, "object_id", 0) or 0): npc
        for npc in npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
    }
    candidates = []

    for threat in party_snapshot.get("rescue_threats", []) or []:
        if not isinstance(threat, dict):
            continue

        threat_id = int(threat.get("object_id", 0) or 0)
        if threat_id <= 0 or threat_id == leader_target_id:
            continue

        requested_at = float(threat.get("requested_at", 0.0) or 0.0)
        threat_age = now - requested_at
        if threat_age < 0.0 or (max_age > 0.0 and threat_age > max_age):
            continue

        npc = visible_by_id.get(threat_id)
        if npc is None or is_required_target(args, npc) or not should_accept_party_rescue_target(args, npc):
            continue

        objective_add = bool(threat.get("objective_add", False))
        if not local_rescue_active and not objective_add:
            continue

        distance = combat_distance_to(client, npc)
        if objective_add:
            if not is_party_objective_add_rescue_threat_in_range(
                client,
                args,
                party_snapshot,
                npc,
                proven_objective_add=True,
            ):
                continue
        elif max_distance > 0.0 and distance > max_distance:
            continue

        candidates.append((distance, threat_id, npc))

    if not candidates:
        return None

    return min(candidates, key=lambda candidate: (candidate[0], candidate[1]))[2]


def party_support_peel_anchor(party_snapshot: dict[str, int | float | str]) -> tuple[int, int, int]:
    active_x = int(party_snapshot.get("active_tank_x", 0) or 0)
    active_y = int(party_snapshot.get("active_tank_y", 0) or 0)
    active_z = int(party_snapshot.get("active_tank_z", 0) or 0)
    if active_x or active_y:
        return active_x, active_y, active_z
    return (
        int(party_snapshot.get("leader_x", 0) or 0),
        int(party_snapshot.get("leader_y", 0) or 0),
        int(party_snapshot.get("leader_z", 0) or 0),
    )


def party_support_peel_kite_destination(
    args: argparse.Namespace,
    client,
    threat,
    party_snapshot: dict[str, int | float | str],
) -> MovementDestination | None:
    anchor_x, anchor_y, anchor_z = party_support_peel_anchor(party_snapshot)
    if not (anchor_x or anchor_y):
        return None

    threat_x = int(getattr(threat, "x", 0) or 0)
    threat_y = int(getattr(threat, "y", 0) or 0)
    if not (threat_x or threat_y):
        return None

    radius = max(250.0, float(getattr(args, "party_support_peel_kite_radius", 850.0) or 850.0))
    desired_threat_distance = max(
        radius + 250.0,
        float(getattr(args, "party_support_peel_kite_threat_distance", 1200.0) or 1200.0),
    )
    dx = anchor_x - threat_x
    dy = anchor_y - threat_y
    length = math.hypot(dx, dy)
    if length <= 0.0:
        current_dx = int(getattr(client, "x", anchor_x) or anchor_x) - anchor_x
        current_dy = int(getattr(client, "y", anchor_y) or anchor_y) - anchor_y
        length = math.hypot(current_dx, current_dy)
        dx, dy = (current_dx, current_dy) if length > 0.0 else (1.0, 0.0)
        length = max(1.0, length)

    base_angle = math.atan2(dy, dx)
    current_x = int(getattr(client, "x", anchor_x) or anchor_x)
    current_y = int(getattr(client, "y", anchor_y) or anchor_y)
    candidates: list[tuple[float, int, int]] = []
    for offset in (0.0, math.pi / 4, -math.pi / 4, math.pi / 2, -math.pi / 2):
        angle = base_angle + offset
        candidate_x = int(anchor_x + math.cos(angle) * radius)
        candidate_y = int(anchor_y + math.sin(angle) * radius)
        threat_distance = horizontal_distance_between_points(candidate_x, candidate_y, threat_x, threat_y)
        if threat_distance < desired_threat_distance:
            continue
        current_distance = horizontal_distance_between_points(current_x, current_y, candidate_x, candidate_y)
        anchor_distance = horizontal_distance_between_points(anchor_x, anchor_y, candidate_x, candidate_y)
        candidates.append((current_distance + abs(anchor_distance - radius) * 0.15, candidate_x, candidate_y))

    if not candidates:
        target_x = int(anchor_x + dx / length * radius)
        target_y = int(anchor_y + dy / length * radius)
    else:
        _, target_x, target_y = min(candidates)

    return destination_from_point("party-support-peel-kite", target_x, target_y, anchor_z)


def should_use_party_support_tactical_peel(
    args: argparse.Namespace,
    action_rotation: str,
    party_snapshot: dict[str, int | float | str],
    tactical_backoff_reason: str,
) -> bool:
    if action_rotation not in {"caster-basic", "healer-support"}:
        return False

    if not bool(getattr(args, "party_support_evasion", False)):
        return False

    if tactical_backoff_reason not in {"boss_ranged", "ranged_target", "party_focus_target", "party_focus_pressure"}:
        return False

    anchor_x, anchor_y, _ = party_support_peel_anchor(party_snapshot)
    return bool(anchor_x or anchor_y)


def should_run_smooth_combat_movement(
    args: argparse.Namespace,
    action_rotation: str,
    current_target: int,
    party_state,
) -> bool:
    if current_target:
        return True

    return bool(
        party_state is not None
        and action_rotation in {"caster-basic", "healer-support"}
        and getattr(args, "party_support_evasion", False)
        and getattr(args, "party_rescue_aggro", False)
    )


def choose_follow_player(client, args: argparse.Namespace):
    candidates = client.visible_players(max_age=args.player_state_max_age)

    if args.follow_player_max_distance > 0:
        candidates = [player for player in candidates if client.distance_to(player) <= args.follow_player_max_distance]

    if not candidates:
        return None

    name_token = args.follow_player_name.strip().lower()

    if name_token:
        for player in candidates:
            if name_token in player.name.lower():
                return player

    return min(candidates, key=lambda player: client.distance_to(player))


def choose_current_visible_player(players, current_target: int):
    if int(current_target or 0) <= 0:
        return None

    return next(
        (
            player
            for player in players
            if int(getattr(player, "object_id", 0) or 0) == int(current_target)
        ),
        None,
    )


def party_snapshot_member_object_ids(party_snapshot: dict[str, object] | None) -> set[int]:
    if not isinstance(party_snapshot, dict):
        return set()

    object_ids = {
        int(party_snapshot.get("leader_object_id", 0) or 0),
        int(party_snapshot.get("active_tank_object_id", 0) or 0),
        int(party_snapshot.get("rescue_tank_object_id", 0) or 0),
    }
    for member in party_snapshot.get("members", []) or []:
        if not isinstance(member, dict):
            continue
        object_ids.add(int(member.get("object_id", 0) or 0))

    object_ids.discard(0)
    return object_ids


def party_snapshot_member_names(party_snapshot: dict[str, object] | None) -> set[str]:
    if not isinstance(party_snapshot, dict):
        return set()

    names = {
        normalize_target_name(str(party_snapshot.get("leader_name", "") or "")),
        normalize_target_name(str(party_snapshot.get("active_tank_name", "") or "")),
        normalize_target_name(str(party_snapshot.get("rescue_tank_name", "") or "")),
    }
    for member in party_snapshot.get("members", []) or []:
        if not isinstance(member, dict):
            continue
        names.add(normalize_target_name(str(member.get("name", "") or "")))

    return {name for name in names if name}


def target_id_is_party_member(target_id: int, party_snapshot: dict[str, object] | None) -> bool:
    return int(target_id or 0) > 0 and int(target_id or 0) in party_snapshot_member_object_ids(party_snapshot)


def player_is_party_member(player, party_snapshot: dict[str, object] | None) -> bool:
    object_id = int(getattr(player, "object_id", 0) or 0)
    if object_id > 0 and object_id in party_snapshot_member_object_ids(party_snapshot):
        return True

    player_name = normalize_target_name(str(getattr(player, "name", "") or ""))
    return bool(player_name and player_name in party_snapshot_member_names(party_snapshot))


def player_is_rvr_enemy_candidate(
    client,
    args: argparse.Namespace,
    player,
    *,
    own_realm: int,
    party_snapshot: dict[str, object] | None = None,
    rejected_targets: dict[int, float] | None = None,
    now: float = 0.0,
) -> bool:
    object_id = int(getattr(player, "object_id", 0) or 0)
    if object_id <= 0:
        return False
    if object_id == int(getattr(client, "player_object_id", 0) or 0):
        return False
    if rejected_targets is not None and float(rejected_targets.get(object_id, 0.0) or 0.0) > float(now or 0.0):
        return False

    player_realm = int(getattr(player, "realm", 0) or 0)
    if player_realm <= 0 or int(own_realm or 0) <= 0 or player_realm == int(own_realm):
        return False
    if player_is_party_member(player, party_snapshot):
        return False

    max_distance = float(getattr(args, "rvr_enemy_player_max_distance", 0.0) or 0.0)
    if max_distance > 0.0 and combat_distance_to(client, player) > max_distance:
        return False

    min_level = int(getattr(args, "rvr_enemy_player_min_level", 0) or 0)
    if min_level > 0 and int(getattr(player, "level", 0) or 0) < min_level:
        return False

    max_level = int(getattr(args, "rvr_enemy_player_max_level", 0) or 0)
    if max_level > 0 and int(getattr(player, "level", 0) or 0) > max_level:
        return False

    name_token = normalize_target_name(str(getattr(args, "rvr_enemy_player_name", "") or ""))
    if name_token:
        player_name = normalize_target_name(str(getattr(player, "name", "") or ""))
        if name_token not in player_name:
            return False

    return True


def choose_rvr_enemy_player(
    client,
    args: argparse.Namespace,
    *,
    own_realm: int,
    party_snapshot: dict[str, object] | None = None,
    rejected_targets: dict[int, float] | None = None,
    now: float = 0.0,
    prefer_object_id: int = 0,
):
    candidates = [
        player
        for player in client.visible_players(max_age=getattr(args, "player_state_max_age", 30.0))
        if player_is_rvr_enemy_candidate(
            client,
            args,
            player,
            own_realm=own_realm,
            party_snapshot=party_snapshot,
            rejected_targets=rejected_targets,
            now=now,
        )
    ]

    preferred_id = int(prefer_object_id or 0)
    if preferred_id > 0:
        preferred = choose_current_visible_player(candidates, preferred_id)
        if preferred is not None:
            return preferred

    if not candidates:
        return None

    return min(candidates, key=lambda player: client.distance_to(player))


def choose_named_rvr_enemy_player(
    client,
    args: argparse.Namespace,
    attacker_name: str,
    *,
    own_realm: int,
    party_snapshot: dict[str, object] | None = None,
    rejected_targets: dict[int, float] | None = None,
    now: float = 0.0,
):
    attacker_key = normalize_target_name(attacker_name)
    if not attacker_key:
        return None

    candidates = []
    for player in client.visible_players(max_age=getattr(args, "player_state_max_age", 30.0)):
        player_name = normalize_target_name(str(getattr(player, "name", "") or ""))
        if not player_name or (player_name != attacker_key and attacker_key not in player_name):
            continue
        if player_is_rvr_enemy_candidate(
            client,
            args,
            player,
            own_realm=own_realm,
            party_snapshot=party_snapshot,
            rejected_targets=rejected_targets,
            now=now,
        ):
            candidates.append(player)

    if not candidates:
        return None

    return min(candidates, key=lambda player: client.distance_to(player))


def rvr_enemy_player_actor_from_condition_snapshot(snapshot: PlayerConditionSnapshot | None):
    if snapshot is None or not snapshot.is_alive or int(snapshot.object_id or 0) <= 0:
        return None

    return SimpleNamespace(
        object_id=int(snapshot.object_id),
        name=str(snapshot.name or ""),
        level=int(snapshot.level or 0),
        realm=int(snapshot.realm or 0),
        x=int(snapshot.x or 0),
        y=int(snapshot.y or 0),
        z=int(snapshot.z or 0),
    )


def choose_greet_player(
    client,
    args: argparse.Namespace,
    greeted_until: dict[int, float],
    now: float,
):
    candidates = [
        player
        for player in client.visible_players(max_age=args.player_state_max_age)
        if client.distance_to(player) <= args.player_greet_distance
        and greeted_until.get(player.object_id, 0.0) <= now
    ]

    if not candidates:
        return None

    return min(candidates, key=lambda player: client.distance_to(player))


def find_visible_party_member_player(client, args: argparse.Namespace, member_name: str):
    member_key = normalize_target_name(member_name)
    if not member_key:
        return None

    for player in client.visible_players(max_age=getattr(args, "player_state_max_age", 30.0)):
        if normalize_target_name(getattr(player, "name", "")) == member_key:
            return player

    return None


def party_state_member_health_percent(party_state: PartyState, member_name: str, default: int = 100) -> int:
    if member_name not in party_state.member_health_percents:
        return default
    return int(party_state.member_health_percents[member_name])


def party_member_needs_resurrection_visibility_sync(party_state: PartyState, member_name: str) -> bool:
    if party_state_member_health_percent(party_state, member_name) > 0:
        return False

    object_id = int(party_state.member_object_ids.get(member_name, 0) or 0)
    x, y, _z = party_state.member_positions.get(member_name, (0, 0, 0))
    return object_id <= 0 or (x == 0 and y == 0)


def sync_party_member_from_visible_players(
    party_state: PartyState | None,
    client,
    args: argparse.Namespace,
    member_name: str,
    *,
    preserve_dead: bool = False,
) -> bool:
    if party_state is None or not member_name:
        return False

    player = find_visible_party_member_player(client, args, member_name)
    if player is None:
        return False

    known_condition = party_state.member_conditions.get(member_name)
    marked_dead = party_state_member_health_percent(party_state, member_name) <= 0
    preserve_dead = preserve_dead or marked_dead
    visible_health = int(getattr(player, "health_percent", 100) or 100)
    is_dead = preserve_dead or visible_health <= 0
    health_percent = 0 if is_dead else visible_health

    party_state.update_member_condition(
        member_name,
        PlayerConditionSnapshot(
            name=member_name,
            account=str(getattr(known_condition, "account", "") or getattr(player, "account", "") or ""),
            object_id=int(getattr(player, "object_id", 0) or getattr(player, "player_object_id", 0) or 0),
            level=int(getattr(known_condition, "level", 0) or getattr(player, "level", 0) or 0),
            class_name=str(getattr(known_condition, "class_name", "") or getattr(player, "class_name", "") or ""),
            class_id=int(getattr(known_condition, "class_id", 0) or getattr(player, "class_id", 0) or 0),
            realm=int(getattr(known_condition, "realm", 0) or getattr(player, "realm", 0) or 0),
            health_percent=health_percent,
            x=int(getattr(player, "x", 0) or 0),
            y=int(getattr(player, "y", 0) or 0),
            z=int(getattr(player, "z", 0) or 0),
            is_alive=not is_dead,
            is_stunned=bool(getattr(known_condition, "is_stunned", False)),
            is_mezzed=bool(getattr(known_condition, "is_mezzed", False)),
            is_diseased=bool(getattr(known_condition, "is_diseased", False)),
            is_poisoned=bool(getattr(known_condition, "is_poisoned", False)),
            is_nearsighted=bool(getattr(known_condition, "is_nearsighted", False)),
            is_silenced=bool(getattr(known_condition, "is_silenced", False)),
            target_object_id=int(getattr(known_condition, "target_object_id", 0) or 0),
            target_name=str(getattr(known_condition, "target_name", "") or ""),
            is_companion=bool(getattr(known_condition, "is_companion", False)),
            companion_role=str(getattr(known_condition, "companion_role", "") or ""),
        ),
    )
    return True


def sync_party_member_from_condition_api(
    party_state: PartyState | None,
    args: argparse.Namespace,
    member_name: str,
    *,
    preserve_dead: bool = False,
    fetch_condition=None,
) -> bool:
    if party_state is None or not member_name or not getattr(args, "combat_usable_api", False):
        return False

    if fetch_condition is None:
        fetch_condition = fetch_player_condition_snapshot_for_player

    known_condition = party_state.member_conditions.get(member_name)
    account = str(getattr(known_condition, "account", "") or "")
    if not account:
        account = probable_account_from_character_name(member_name)

    condition = fetch_condition(args, member_name, account)
    if condition is None:
        return False

    marked_dead = party_state_member_health_percent(party_state, member_name) <= 0
    preserve_dead = preserve_dead or marked_dead
    condition_health = int(getattr(condition, "health_percent", 100) or 100)
    is_dead = preserve_dead or not bool(getattr(condition, "is_alive", True)) or condition_health <= 0
    health_percent = 0 if is_dead else condition_health
    object_id = int(getattr(condition, "object_id", 0) or 0)
    if object_id <= 0:
        object_id = int(party_state.member_object_ids.get(member_name, 0) or 0)

    party_state.update_member_condition(
        member_name,
        PlayerConditionSnapshot(
            name=member_name,
            account=str(getattr(condition, "account", "") or account),
            object_id=object_id,
            level=int(getattr(condition, "level", 0) or 0),
            class_name=str(getattr(condition, "class_name", "") or ""),
            class_id=int(getattr(condition, "class_id", 0) or 0),
            realm=int(getattr(condition, "realm", 0) or 0),
            health_percent=health_percent,
            x=int(getattr(condition, "x", 0) or 0),
            y=int(getattr(condition, "y", 0) or 0),
            z=int(getattr(condition, "z", 0) or 0),
            is_alive=not is_dead,
            is_stunned=bool(getattr(condition, "is_stunned", False)),
            is_mezzed=bool(getattr(condition, "is_mezzed", False)),
            is_diseased=bool(getattr(condition, "is_diseased", False)),
            is_poisoned=bool(getattr(condition, "is_poisoned", False)),
            is_nearsighted=bool(getattr(condition, "is_nearsighted", False)),
            is_silenced=bool(getattr(condition, "is_silenced", False)),
            target_object_id=int(getattr(condition, "target_object_id", 0) or 0),
            target_name=str(getattr(condition, "target_name", "") or ""),
            is_companion=bool(getattr(condition, "is_companion", False)),
            companion_role=str(getattr(condition, "companion_role", "") or ""),
        ),
    )
    return object_id > 0


def ensure_party_member_resurrection_identity(
    party_state: PartyState | None,
    client,
    args: argparse.Namespace,
    member_name: str,
    *,
    preserve_dead: bool = False,
    fetch_condition=None,
) -> str:
    if party_state is None or not member_name:
        return ""

    if party_state_member_health_percent(party_state, member_name) > 0:
        return ""

    object_id = int(party_state.member_object_ids.get(member_name, 0) or 0)
    if object_id > 0 and not party_member_needs_resurrection_visibility_sync(party_state, member_name):
        return ""

    if sync_party_member_from_visible_players(
        party_state,
        client,
        args,
        member_name,
        preserve_dead=True,
    ):
        return "visible"

    if sync_party_member_from_condition_api(
        party_state,
        args,
        member_name,
        preserve_dead=preserve_dead,
        fetch_condition=fetch_condition,
    ):
        return "condition"

    return ""


def refresh_dead_party_resurrection_targets_from_visible_players(
    party_state: PartyState | None,
    client,
    args: argparse.Namespace,
) -> int:
    if party_state is None:
        return 0

    updated = 0
    for member_name in list(party_state.member_names):
        if party_state_member_health_percent(party_state, member_name) > 0:
            continue
        sync_source = ensure_party_member_resurrection_identity(
            party_state,
            client,
            args,
            member_name,
            preserve_dead=True,
        )
        if sync_source:
            updated += 1

    return updated


def update_external_party_members_from_visible_players(
    party_state: PartyState | None,
    client,
    args: argparse.Namespace,
) -> int:
    if party_state is None:
        return 0

    configured_names = {
        normalize_target_name(member_name): member_name
        for member_name in getattr(args, "party_external_member_names", []) or []
        if normalize_target_name(member_name)
    }
    if getattr(args, "party_auto_external_members", False):
        for member_name in party_state.snapshot().get("external_member_names", []) or []:
            normalized_name = normalize_target_name(member_name)
            if not normalized_name or normalized_name in configured_names:
                continue
            configured_names[normalized_name] = str(member_name)
    if not configured_names:
        return 0

    updated = 0
    for player in client.visible_players(max_age=getattr(args, "player_state_max_age", 30.0)):
        configured_name = configured_names.get(normalize_target_name(getattr(player, "name", "")))
        if not configured_name:
            continue

        if party_state_member_health_percent(party_state, configured_name) <= 0:
            if sync_party_member_from_visible_players(
                party_state,
                client,
                args,
                configured_name,
                preserve_dead=True,
            ):
                updated += 1
            continue

        party_state.update_external_member(configured_name, player, role="external")
        updated += 1

    return updated


def choose_ai_persona_name(args: argparse.Namespace, account: DummyAccount, index: int) -> str:
    if not args.ai_player or args.ai_persona == "none":
        return "none"

    if args.ai_persona != "auto":
        return args.ai_persona

    digest = hashlib.sha256(f"{args.seed}:{index}:{account.username}".encode("utf-8")).digest()
    names = sorted(AI_PERSONAS)
    return names[int.from_bytes(digest[:4], "big") % len(names)]


def clamp_chance(value: float) -> float:
    return max(0.0, min(1.0, value))


def apply_ai_persona(args: argparse.Namespace, account: DummyAccount, index: int) -> argparse.Namespace:
    persona_name = choose_ai_persona_name(args, account, index)
    tuned = argparse.Namespace(**vars(args))
    tuned.ai_persona_name = persona_name

    if persona_name == "none":
        return tuned

    persona = AI_PERSONAS[persona_name]
    tuned.social_chance = clamp_chance(args.social_chance * persona.social_chance_multiplier)
    tuned.player_greet_chance = clamp_chance(args.player_greet_chance * persona.player_greet_chance_multiplier)
    tuned.emote_chance = clamp_chance(args.emote_chance * persona.emote_chance_multiplier)
    tuned.long_rest_chance = clamp_chance(args.long_rest_chance * persona.long_rest_chance_multiplier)
    tuned.rest_chance = clamp_chance(args.rest_chance * persona.rest_chance_multiplier)
    tuned.target_examine_chance = clamp_chance(args.target_examine_chance * persona.target_examine_multiplier)
    tuned.player_follow_interval = max(0.5, args.player_follow_interval * persona.player_follow_interval_multiplier)
    tuned.player_follow_distance = max(150.0, args.player_follow_distance * persona.player_follow_distance_multiplier)
    tuned.follow_player_max_distance = max(
        tuned.player_follow_distance,
        args.follow_player_max_distance * persona.follow_player_max_distance_multiplier,
    )
    tuned.look_around_interval = max(2.0, args.look_around_interval * persona.look_around_interval_multiplier)
    tuned.think_min = max(0.0, args.think_min * persona.think_window_multiplier)
    tuned.think_max = max(tuned.think_min, args.think_max * persona.think_window_multiplier)
    return tuned


