def resolve_action_rotation(args: argparse.Namespace, party_slot: int, account: DummyAccount | None = None) -> str:
    if args.party_slot_rotations:
        rotations = args.party_slot_rotations
        return rotations[party_slot % len(rotations)]

    if args.action_rotation != "auto":
        return args.action_rotation

    if account is not None:
        profile = party_class_role_profile_from_class(account.class_name, account.class_id or 0)
        if profile.action_rotation != "external":
            return profile.action_rotation

    if args.party_size > 1 and args.party_role_strategy == "mixed":
        if party_slot == 0:
            return "melee-basic"
        if party_slot == args.party_size - 1:
            return "healer-support"
        if party_slot % 2 == 0:
            return "caster-basic"
        return "melee-burst"

    if args.behavior_profile == "party-dps":
        return "melee-burst"
    if args.behavior_profile == "cautious-solo":
        return "hybrid"
    return "melee-basic"


def dynamic_quest_required_target_melee_fallback_enabled(args: argparse.Namespace) -> bool:
    return bool(
        getattr(args, "required_target_home", None) is not None
        and (
            getattr(args, "dynamic_quest_return_after_required_target", False)
            or getattr(args, "dynamic_quest_observe_final_progress", False)
        )
        and str(getattr(args, "require_target_name", "") or "").strip()
    )


def resolve_effective_action_rotation(
    args: argparse.Namespace,
    requested_rotation: str,
    combat_plan: CombatUsablePlan,
    combat_plan_loaded: bool,
    account: DummyAccount | None = None,
) -> str:
    if requested_rotation in {"auto", "none"} or not combat_plan_loaded:
        return requested_rotation

    can_use_raw_spells = bool(getattr(args, "allow_unvalidated_spells", False))
    can_use_raw_skills = bool(getattr(args, "allow_unvalidated_skills", False))
    has_attack_spell = bool(combat_plan.attack_spells) or can_use_raw_spells
    has_heal_spell = bool(combat_plan.heal_spells) or can_use_raw_spells
    has_support_spell = bool(
        combat_plan.buff_spells
        or combat_plan.cure_spells
        or combat_plan.resurrection_spells
    )
    has_skill = bool(combat_plan.skills) or can_use_raw_skills

    if requested_rotation == "healer-support" and not has_heal_spell and not has_support_spell:
        if has_attack_spell:
            return "caster-basic"
        if has_skill:
            return "melee-basic"

    if requested_rotation in {"caster-basic", "hybrid"} and not has_attack_spell:
        if has_skill:
            return "melee-basic"

    if is_melee_rotation(requested_rotation) and not has_skill:
        if has_attack_spell and dynamic_quest_required_target_melee_fallback_enabled(args):
            return requested_rotation
        if account is not None:
            profile = party_class_role_profile_from_class(account.class_name, account.class_id or 0)
            if profile.action_rotation in {"melee-basic", "melee-burst", "hybrid"} and (
                "melee_dps" in profile.capabilities
                or "tank" in profile.capabilities
                or "shield" in profile.capabilities
            ):
                return requested_rotation
        if has_attack_spell:
            return "caster-basic"

    return requested_rotation


