def should_use_party_protection_ability(
    args: argparse.Namespace,
    combat_plan: CombatUsablePlan,
    party_state: PartyState | None,
    *,
    action_rotation: str,
    is_party_leader: bool,
    party_member_name: str,
    current_target: int,
    behavior_state: DummyBehaviorState | str,
    now: float,
    next_party_protection: float,
    current_target_intent: TargetIntent | str = TargetIntent.none,
) -> bool:
    if party_state is None or not combat_plan.party_protection_abilities:
        return False
    if float(getattr(args, "party_protection_interval", 0.0) or 0.0) <= 0.0 or now < next_party_protection:
        return False
    if action_rotation not in {"melee-basic", "melee-burst", "hybrid"}:
        return False
    if behavior_state_value(behavior_state) in {
        DummyBehaviorState.DropAggroAndRecover.value,
        DummyBehaviorState.RestRecover.value,
        DummyBehaviorState.DeadReleaseRecover.value,
    }:
        return False
    snapshot = party_state.snapshot()
    active_tank_name = normalize_target_name(str(snapshot.get("active_tank_name", "") or ""))
    is_active_tank = bool(active_tank_name and active_tank_name == normalize_target_name(party_member_name))
    leader_target_id = int(snapshot.get("leader_target_id", 0) or 0)
    if (
        is_active_tank
        and leader_target_id > 0
        and int(current_target or 0) != leader_target_id
        and float(snapshot.get("leader_target_engaged_at", 0.0) or 0.0) > 0.0
    ):
        return False

    focus_name = normalize_target_name(str(snapshot.get("leader_target_focus_name", "") or ""))
    if (
        is_active_tank
        and focus_name
        and focus_name != active_tank_name
        and party_focus_is_recent(args, snapshot, now=now)
    ):
        return False
    return bool(is_party_leader or str(snapshot.get("active_tank_name", "") or "") == party_member_name)


def should_use_crowd_control_for_multi_aggro(
    args: argparse.Namespace,
    combat_plan: CombatUsablePlan,
    active_combat: dict[str, object] | None,
    *,
    current_target: int,
    health_percent: int,
    now: float,
    next_crowd_control: float,
    behavior_state: DummyBehaviorState | str,
    party_snapshot: dict[str, int | float | str] | None = None,
    observed_npcs: list[object] | None = None,
) -> bool:
    if not combat_plan.crowd_control_spells:
        return False
    if float(getattr(args, "crowd_control_interval", 0.0) or 0.0) <= 0.0 or now < next_crowd_control:
        return False
    if not can_select_hostile_target(behavior_state):
        return False
    health_floor = int(getattr(args, "crowd_control_health_floor", 0) or 0)
    if health_floor > 0 and health_percent <= health_floor:
        return False
    if current_target <= 0:
        min_threats = max(1, int(getattr(args, "crowd_control_preemptive_min_threats", 2) or 2))
        proactive_threats = [
            npc
            for npc in observed_npcs or []
            if npc_is_party_aggro_threat(npc, party_snapshot or {}, current_target=0)
            and should_accept_party_rescue_target(args, npc)
        ]
        return len(proactive_threats) >= min_threats
    if active_combat is None:
        return False
    if any(
        npc_is_party_aggro_threat(npc, party_snapshot or {}, current_target=current_target)
        for npc in observed_npcs or []
    ):
        return True
    return bool(
        int(active_combat.get("off_target_damage_taken", 0) or 0) > 0
        or str(active_combat.get("off_target_attacker_name", "") or "").strip()
    )


def should_attempt_multi_aggro_crowd_control(
    *,
    crowd_control_due: bool,
    multi_aggro_counterattack_hold: bool,
) -> bool:
    return bool(crowd_control_due and not multi_aggro_counterattack_hold)


def crowd_control_retry_delay(args: argparse.Namespace) -> float:
    interval = float(getattr(args, "crowd_control_interval", 0.0) or 0.0)
    if interval <= 0.0:
        return 1.0
    return max(1.0, min(interval, interval * 0.5))


def choose_multi_aggro_crowd_control_target(
    client,
    args: argparse.Namespace,
    active_combat: dict[str, object] | None,
    *,
    current_target: int,
    party_snapshot: dict[str, int | float | str] | None = None,
    api_observations: list[object] | None = None,
):
    if active_combat is None and not api_observations:
        return None

    npcs = dedupe_npcs_by_object_id(
        list(client.visible_npcs(
            max_age=float(getattr(args, "hunter_target_api_max_age", 60.0) or 60.0),
            include_peace=False,
        ))
        + list(api_observations or [])
    )
    party_snapshot = party_snapshot or {}
    attacker_name = str(active_combat.get("off_target_attacker_name", "") or "") if active_combat is not None else ""
    if attacker_name:
        exact = choose_named_rescue_attacker(npcs, client, args, current_target, attacker_name)
        if exact is not None:
            return exact

    proactive_candidates = [
        npc
        for npc in npcs
        if npc_is_party_aggro_threat(npc, party_snapshot, current_target=current_target)
        and should_accept_party_rescue_target(args, npc)
        and not target_home_leash_violation(client, args, npc)[0]
    ]
    if proactive_candidates:
        return min(
            proactive_candidates,
            key=lambda npc: (
                npc_party_aggro_priority(npc, party_snapshot),
                combat_distance_to(client, npc),
            ),
        )

    visible_npcs = client.visible_npcs(
        max_age=float(getattr(args, "hunter_target_api_max_age", 60.0) or 60.0),
        include_peace=False,
    )
    candidates = [
        npc
        for npc in visible_npcs
        if int(getattr(npc, "object_id", 0) or 0) > 0
        and int(getattr(npc, "object_id", 0) or 0) != int(current_target or 0)
        and should_accept_party_rescue_target(args, npc)
        and not target_home_leash_violation(client, args, npc)[0]
    ]
    if not candidates:
        return None

    return min(candidates, key=lambda npc: combat_distance_to(client, npc))


def party_member_name_keys(party_snapshot: dict[str, int | float | str] | None) -> set[str]:
    if not party_snapshot:
        return set()

    names: set[str] = set()
    for member in party_snapshot.get("members", []) or []:
        if not isinstance(member, dict):
            continue
        object_id = int(member.get("object_id", 0) or 0)
        health_percent = int(member.get("health_percent", 0) or 0)
        if object_id <= 0 or health_percent <= 0:
            continue
        name = normalize_target_name(str(member.get("name", "") or ""))
        if name:
            names.add(name)
    return names


def npc_targets_party_member(npc, party_snapshot: dict[str, int | float | str] | None) -> bool:
    target_name = normalize_target_name(str(getattr(npc, "target", "") or ""))
    if not target_name:
        return False

    return any(
        target_name == member_name or target_name in member_name or member_name in target_name
        for member_name in party_member_name_keys(party_snapshot)
    )


def npc_is_party_aggro_threat(
    npc,
    party_snapshot: dict[str, int | float | str] | None,
    *,
    current_target: int,
) -> bool:
    if npc is None:
        return False
    if int(getattr(npc, "object_id", 0) or 0) <= 0:
        return False
    if int(getattr(npc, "object_id", 0) or 0) == int(current_target or 0):
        return False
    if npc_is_crowd_controlled(npc):
        return False
    if npc_targets_party_member(npc, party_snapshot):
        return True
    return bool(getattr(npc, "has_aggro", False) or getattr(npc, "in_combat", False))


def npc_party_aggro_priority(npc, party_snapshot: dict[str, int | float | str] | None) -> int:
    if npc_targets_party_member(npc, party_snapshot):
        return 0
    if bool(getattr(npc, "has_aggro", False)):
        return 1
    if bool(getattr(npc, "in_combat", False)):
        return 2
    return 3


def npc_is_crowd_controlled(npc) -> bool:
    return bool(getattr(npc, "is_mezzed", False) or getattr(npc, "is_stunned", False))


def dedupe_npcs_by_object_id(npcs: list[object]) -> list[object]:
    seen: set[int] = set()
    deduped: list[object] = []
    for npc in npcs:
        object_id = int(getattr(npc, "object_id", 0) or 0)
        if object_id <= 0 or object_id in seen:
            continue
        seen.add(object_id)
        deduped.append(npc)
    return deduped


def crowd_control_spell_kind(spell: UsableSpellRef) -> str:
    spell_type = normalized_spell_type(spell)
    if "stun" in spell_type:
        return "stun"
    if "mez" in spell_type or "mesmerize" in spell_type:
        return "mez"
    if (
        "root" in spell_type
        or "speeddecrease" in spell_type
        or spell_type.endswith("snare")
        or spell_type in {"preventflight", "fear"}
    ):
        return "root"
    if spell_type in {"amnesia", "befriend", "confusion", "silence"}:
        return "soft"
    return "other"


def choose_crowd_control_spell(
    args: argparse.Namespace,
    spells: list[UsableSpellRef],
    target,
    *,
    party_snapshot: dict[str, int | float | str] | None = None,
) -> UsableSpellRef | None:
    if not spells:
        return None

    pool_size = max(1, int(getattr(args, "combat_plan_spell_pool", 3) or 3))
    pool = spells[: min(len(spells), pool_size)]
    urgent_party_target = npc_targets_party_member(target, party_snapshot)
    order = (
        {"stun": 0, "mez": 1, "root": 2, "soft": 3, "other": 4}
        if urgent_party_target
        else {"mez": 0, "root": 1, "stun": 2, "soft": 3, "other": 4}
    )

    return min(
        pool,
        key=lambda spell: (
            order.get(crowd_control_spell_kind(spell), 5),
            max(0, int(getattr(spell, "cast_time", 0) or 0)),
            -max(0, int(getattr(spell, "radius", 0) or 0)),
            -int(getattr(spell, "level", 0) or 0),
            str(getattr(spell, "name", "") or ""),
        ),
    )


def perform_crowd_control_cast(
    client,
    spell: UsableSpellRef,
    args: argparse.Namespace,
    target,
) -> str:
    client.target_object(int(getattr(target, "object_id", 0) or 0))
    cast_usable_spell(
        client,
        spell,
        target_in_view=True,
        speed=getattr(client, "last_position_speed", 0.0),
        stationary=bool(getattr(args, "stationary_cast_actions", False)),
    )
    return "validated_crowd_control_spell"


def should_send_target_start_commands(
    args: argparse.Namespace,
    current_target: int,
    sent_target_start_command_targets: set[int],
) -> bool:
    return bool(getattr(args, "target_start_command", []) and current_target > 0 and current_target not in sent_target_start_command_targets)


def should_party_member_assist_rescue_target(
    args: argparse.Namespace,
    action_rotation: str,
    rescue_age: float = 0.0,
    objective_add: bool = True,
    victim_role: str = "",
) -> bool:
    if action_rotation == "healer-support":
        return False

    if action_rotation == "caster-basic" and not getattr(args, "party_caster_assist_rescue_target", False):
        return False

    if should_assist_dangerous_support_rescue_threat(args, action_rotation, rescue_age, victim_role):
        return True

    if not objective_add:
        return False

    if getattr(args, "party_assist_rescue_target", False):
        return True

    assist_after = max(0.0, float(getattr(args, "party_rescue_assist_after", 0.0) or 0.0))
    return assist_after > 0.0 and rescue_age >= assist_after


def should_prefer_taunt_skill_for_target(
    args: argparse.Namespace,
    snapshot: dict[str, int | float | str],
    *,
    member_name: str,
    action_rotation: str,
    selected_npc_is_rescue: bool,
    selected_npc_is_required: bool,
    reaggro_taunt_due: bool,
) -> bool:
    if reaggro_taunt_due:
        return True

    if action_rotation not in {"melee-basic", "melee-burst", "hybrid"}:
        return False

    if selected_npc_is_rescue:
        return bool(
            getattr(args, "party_rescue_aggro", False)
            and (
                party_member_is_rescue_tank(snapshot, member_name)
                or (
                    is_party_tank_role(action_rotation)
                    and not should_party_member_hold_shared_objective(args, snapshot, member_name)
                )
                or should_party_member_assist_rescue_target(
                    args,
                    action_rotation,
                    rescue_age=float("inf"),
                    objective_add=True,
                )
            )
        )

    return bool(
        selected_npc_is_required
        and party_member_is_active_tank(snapshot, member_name)
    )



def should_reject_selected_target_for_required_filter(args: argparse.Namespace, npc, selected_npc_is_rescue: bool) -> bool:
    return npc is not None and not selected_npc_is_rescue and not passes_required_target_filter(args, npc)


def should_send_target_start_command_for_npc(args: argparse.Namespace, npc, selected_npc_is_rescue: bool) -> bool:
    return not selected_npc_is_rescue and passes_required_target_filter(args, npc)


def should_send_position_heartbeat_for_client(client) -> bool:
    if bool(getattr(client, "is_dead", False)):
        return False
    return float(getattr(client, "last_position_speed", 0.0) or 0.0) <= 0.0


def is_network_disconnect_exception(exc: BaseException) -> bool:
    if isinstance(exc, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError)):
        return True

    return isinstance(exc, OSError) and getattr(exc, "errno", None) in {
        errno.EPIPE,
        errno.ECONNRESET,
        errno.ECONNABORTED,
    }


def should_treat_disconnect_as_completed(
    exc: BaseException,
    client,
    death_seen: bool,
    *,
    action_counts: dict[str, int] | None = None,
    combat_metrics: list[CombatMetric] | None = None,
    dynamic_quest_e2e_enabled: bool = False,
    dynamic_quest_return_pending: bool = False,
    dynamic_quest_return_completed: bool = False,
) -> bool:
    if not is_network_disconnect_exception(exc):
        return False

    if death_seen or bool(getattr(client, "is_dead", False)):
        return not dynamic_quest_e2e_enabled

    if dynamic_quest_e2e_enabled and not dynamic_quest_return_completed:
        return False

    if dynamic_quest_return_pending and not dynamic_quest_return_completed:
        return False

    action_counts = action_counts or {}
    combat_metrics = combat_metrics or []
    target_removed_count = int(action_counts.get("target_removed", 0) or 0) + sum(
        1 for combat in combat_metrics if combat.outcome == "target_removed"
    )
    player_death_count = int(action_counts.get("death_detected", 0) or 0) + sum(
        1 for combat in combat_metrics if combat.outcome == "player_death"
    )

    return target_removed_count > 0 and player_death_count <= 0


def final_round_completion_status(
    *,
    safe_exit_failed: bool,
    safe_exit_error: str,
    dynamic_quest_return_pending: bool = False,
    dynamic_quest_return_completed: bool = False,
    dynamic_quest_e2e_enabled: bool = False,
    dynamic_quest_active_count: int = 0,
    dynamic_quest_progress_seen: bool = False,
    dynamic_quest_completion_signal_seen: bool = False,
    dynamic_quest_completed: bool = False,
    dynamic_quest_progress_error: str = "",
    dynamic_quest_timeline_error: str = "",
    dynamic_quest_final_active_allowed: bool = False,
) -> tuple[bool, str]:
    if dynamic_quest_return_pending and not dynamic_quest_return_completed:
        return False, "dynamic quest return incomplete"
    if dynamic_quest_e2e_enabled:
        progress_error = str(dynamic_quest_progress_error or "").strip()
        if progress_error:
            return False, f"dynamic quest progress check failed: {progress_error}"
        timeline_error = str(dynamic_quest_timeline_error or "").strip()
        if timeline_error:
            return False, f"dynamic quest timeline check failed: {timeline_error}"
        if dynamic_quest_completed:
            return not safe_exit_failed, safe_exit_error
        active_count = int(dynamic_quest_active_count or 0)
        progress_observed = bool(dynamic_quest_progress_seen) or active_count > 0
        if active_count > 0:
            if dynamic_quest_final_active_allowed:
                return not safe_exit_failed, safe_exit_error
            return False, "dynamic quest incomplete"
        if not progress_observed and not dynamic_quest_completion_signal_seen:
            return False, "dynamic quest never became active"
    return not safe_exit_failed, safe_exit_error


def party_snapshot_has_external_leader(snapshot: dict[str, object]) -> bool:
    leader_name = normalize_target_name(str(snapshot.get("leader_name", "") or ""))
    if not leader_name:
        return False
    return any(
        normalize_target_name(str(name or "")) == leader_name
        for name in snapshot.get("external_member_names", []) or []
    )


def party_leader_anchor_from_snapshot(snapshot: dict[str, int | float | str]) -> dict[str, int | str]:
    return {
        "name": str(snapshot.get("leader_name", "")),
        "object_id": int(snapshot.get("leader_object_id", 0) or 0),
        "x": int(snapshot.get("leader_x", 0) or 0),
        "y": int(snapshot.get("leader_y", 0) or 0),
        "z": int(snapshot.get("leader_z", 0) or 0),
    }


def party_anchor_from_snapshot(
    snapshot: dict[str, int | float | str],
    *,
    member_name: str = "",
) -> dict[str, int | str]:
    if party_snapshot_has_external_leader(snapshot):
        leader_anchor = party_leader_anchor_from_snapshot(snapshot)
        if int(leader_anchor["object_id"] or 0) > 0 and (int(leader_anchor["x"] or 0) or int(leader_anchor["y"] or 0)):
            return leader_anchor

    active_tank_id = int(snapshot.get("active_tank_object_id", 0) or 0)
    active_tank_x = int(snapshot.get("active_tank_x", 0) or 0)
    active_tank_y = int(snapshot.get("active_tank_y", 0) or 0)
    active_tank_z = int(snapshot.get("active_tank_z", 0) or 0)

    if (
        active_tank_id
        and (active_tank_x != 0 or active_tank_y != 0)
        and not party_member_is_active_tank(snapshot, member_name)
    ):
        return {
            "name": str(snapshot.get("active_tank_name", "")),
            "object_id": active_tank_id,
            "x": active_tank_x,
            "y": active_tank_y,
            "z": active_tank_z,
        }

    return party_leader_anchor_from_snapshot(snapshot)


def party_leader_anchor_position_valid(snapshot: dict[str, int | float | str]) -> bool:
    return bool(
        int(snapshot.get("leader_object_id", 0) or 0) > 0
        and (
            int(snapshot.get("leader_x", 0) or 0) != 0
            or int(snapshot.get("leader_y", 0) or 0) != 0
        )
    )


def party_anchor_position_valid(
    snapshot: dict[str, int | float | str],
    *,
    member_name: str = "",
) -> bool:
    if (
        int(snapshot.get("active_tank_object_id", 0) or 0) > 0
        and (
            int(snapshot.get("active_tank_x", 0) or 0) != 0
            or int(snapshot.get("active_tank_y", 0) or 0) != 0
        )
        and not party_member_is_active_tank(snapshot, member_name)
    ):
        return True

    return party_leader_anchor_position_valid(snapshot)


def party_member_is_active_tank(snapshot: dict[str, int | float | str] | None, member_name: str) -> bool:
    snapshot = snapshot or {}
    return bool(
        member_name
        and normalize_target_name(str(snapshot.get("active_tank_name", "") or ""))
        == normalize_target_name(member_name)
    )


def party_member_is_rescue_tank(snapshot: dict[str, int | float | str] | None, member_name: str) -> bool:
    snapshot = snapshot or {}
    return bool(member_name and str(snapshot.get("rescue_tank_name", "")) == member_name)


def party_damage_response_snapshots(
    party_state: PartyState | None,
    member_name: str,
) -> tuple[dict[str, int | float | str] | None, dict[str, int | float | str] | None]:
    if party_state is None:
        return None, None

    snapshot = party_state.snapshot()
    active_tank_snapshot = snapshot if party_member_is_active_tank(snapshot, member_name) else None
    return active_tank_snapshot, snapshot


def is_party_tank_role(action_rotation: str) -> bool:
    return action_rotation in {"melee-basic", "melee-burst", "hybrid"}


def should_party_member_tank_rescue_target(
    args: argparse.Namespace,
    snapshot: dict[str, int | float | str],
    member_name: str,
) -> bool:
    if not party_member_is_rescue_tank(snapshot, member_name):
        return False

    if (
        should_preserve_party_target_on_loss(args)
        and int(snapshot.get("leader_target_id", 0) or 0) > 0
        and str(snapshot.get("active_tank_name", "")) == member_name
    ):
        return False

    return True


def should_party_member_hold_shared_objective(
    args: argparse.Namespace,
    snapshot: dict[str, int | float | str],
    member_name: str,
) -> bool:
    return bool(
        should_preserve_party_target_on_loss(args)
        and int(snapshot.get("leader_target_id", 0) or 0) > 0
        and party_member_is_active_tank(snapshot, member_name)
    )


def should_party_member_handle_rescue_target(
    args: argparse.Namespace,
    snapshot: dict[str, int | float | str],
    member_name: str,
    action_rotation: str,
    health_percent: int,
    *,
    rescue_age: float,
) -> bool:
    if should_party_member_hold_shared_objective(args, snapshot, member_name):
        return False

    objective_add = bool(snapshot.get("rescue_target_objective_add", True))
    return bool(
        should_party_member_tank_rescue_target(args, snapshot, member_name)
        or should_party_member_assist_rescue_target(
            args,
            action_rotation,
            rescue_age=rescue_age,
            objective_add=objective_add,
            victim_role=party_member_role(snapshot, str(snapshot.get("rescue_member_name", "") or "")),
        )
        or (
            (not objective_add or not should_preserve_party_target_on_loss(args))
            and should_party_member_use_local_rescue_target(args, action_rotation, health_percent)
        )
    )


def choose_incoming_damage_counterattack_target(
    npcs,
    client,
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    *,
    member_name: str,
    action_rotation: str,
    health_percent: int,
    attacker_name: str,
    current_target: int,
    behavior_state: DummyBehaviorState | str,
    rejected_targets: dict[int, float] | None = None,
    now: float = 0.0,
    active_combat=None,
):
    if current_target > 0 or party_snapshot is None or not attacker_name:
        return None

    if not getattr(args, "party_rescue_aggro", False):
        return None

    if not party_member_is_active_tank(party_snapshot, member_name):
        return None

    if not is_melee_rotation(action_rotation):
        return None

    health_floor = int(getattr(args, "flee_melee_counterattack_health_floor", 0) or 0)
    if health_floor > 0 and health_percent <= health_floor:
        return None

    party_objective_attacker = name_matches_required_or_party_objective(
        args,
        party_snapshot,
        attacker_name,
    ) or name_matches_active_combat_target(active_combat, attacker_name)
    leader_target_id = 0 if party_objective_attacker else int(party_snapshot.get("leader_target_id", 0) or 0)
    preferred_target_id = 0
    if party_objective_attacker:
        preferred_target_id = (
            int(party_snapshot.get("rescue_target_id", 0) or 0)
            or int((active_combat or {}).get("target_id", 0) or 0)
            or int(party_snapshot.get("leader_target_id", 0) or 0)
        )
    attacker = choose_named_rescue_attacker(
        npcs,
        client,
        args,
        leader_target_id,
        attacker_name,
        preferred_target_id=preferred_target_id,
    )
    if attacker is None:
        return None

    if rejected_targets is not None and rejected_targets.get(attacker.object_id, 0.0) > now:
        return None

    if not (
        is_required_target(args, attacker)
        or is_objective_add_target(args, attacker)
        or party_objective_attacker
        or name_matches_required_or_party_objective(args, party_snapshot, str(getattr(attacker, "name", "") or ""))
    ):
        return None

    if not target_within_required_home(args, attacker):
        return None

    if not target_within_selection_distance(client, args, attacker):
        return None

    if target_home_leash_violation(client, args, attacker)[0]:
        return None

    attacker_intent = target_intent_for_selected_npc(
        args,
        attacker,
        selected_npc_is_rescue=True,
        behavior_state=behavior_state,
        recent_incoming_attacker_name=attacker_name,
    )
    if not should_allow_counterattack_for_behavior_state(
        behavior_state,
        args,
        attacker,
        attacker_intent,
    ):
        return None

    return attacker


def should_share_selected_target(
    args: argparse.Namespace,
    selected_npc_is_rescue: bool,
    *,
    is_party_leader: bool = True,
    party_snapshot: dict[str, int | float | str] | None = None,
) -> bool:
    if not should_preserve_party_target_on_loss(args) or selected_npc_is_rescue:
        return False

    if not is_party_leader and getattr(args, "party_require_leader_engaged", False):
        snapshot = party_snapshot or {}
        if float(snapshot.get("leader_target_engaged_at", 0.0) or 0.0) <= 0.0:
            return False

    return True


def should_refresh_shared_required_target(
    args: argparse.Namespace,
    target_npc,
    *,
    is_party_leader: bool = True,
    party_snapshot: dict[str, int | float | str] | None = None,
) -> bool:
    if not should_preserve_party_target_on_loss(args):
        return False

    if not is_required_target(args, target_npc):
        return False

    return should_share_selected_target(
        args,
        selected_npc_is_rescue=False,
        is_party_leader=is_party_leader,
        party_snapshot=party_snapshot,
    )


def should_update_party_objective_target(selected_npc_is_rescue: bool) -> bool:
    return not selected_npc_is_rescue


def should_clear_leader_target_after_required_filter(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    rejected_target_id: int,
) -> bool:
    if not should_preserve_party_target_on_loss(args):
        return True

    leader_target_id = int(party_snapshot.get("leader_target_id", 0) or 0)
    return bool(leader_target_id and leader_target_id == int(rejected_target_id or 0))


def should_scan_peace_npcs(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "include_peace_npcs", False) or should_preserve_party_target_on_loss(args))


def should_preserve_current_party_target(
    args: argparse.Namespace,
    party_state: PartyState | None,
    current_target: int,
    active_combat: dict[str, float | int | str] | None,
    *,
    behavior_state: DummyBehaviorState | str = DummyBehaviorState.HuntObjective,
    current_target_intent: TargetIntent | str = TargetIntent.objective,
    flee_active: bool = False,
    rest_active: bool = False,
    drop_aggro_active: bool = False,
) -> bool:
    if not should_preserve_party_target_on_loss(args) or current_target <= 0:
        return False

    if not can_preserve_committed_hostile_target(
        behavior_state,
        current_target_intent,
        flee_active=flee_active,
        rest_active=rest_active,
        drop_aggro_active=drop_aggro_active,
    ):
        return False

    if active_combat_matches_preservable_objective_target(args, active_combat):
        return True

    if should_preserve_active_party_rescue_focus(
        args,
        active_combat,
        current_target,
        TargetIntent.none,
    ):
        return True

    if active_combat is not None:
        return False

    if party_state is None:
        return False

    snapshot = party_state.snapshot()
    if int(snapshot["rescue_target_id"]) == current_target:
        return False

    return int(snapshot["leader_target_id"]) == current_target


def target_removed_preserve_allowed(
    args: argparse.Namespace,
    now: float,
    last_visible_at: float,
    preserve_count: int,
) -> bool:
    grace = max(0.0, float(getattr(args, "party_target_loss_grace", 0.0)))
    if grace > 0 and last_visible_at > 0 and now - last_visible_at > grace:
        return False

    limit = max(0, int(getattr(args, "party_target_removed_preserve_limit", 0)))
    if limit > 0 and preserve_count >= limit:
        return False

    return True


def should_preserve_removed_party_target(
    args: argparse.Namespace,
    party_state: PartyState | None,
    current_target: int,
    active_combat: dict[str, float | int | str] | None,
    stop_after_removed: bool,
    now: float,
    last_visible_at: float,
    preserve_count: int,
    *,
    behavior_state: DummyBehaviorState | str = DummyBehaviorState.HuntObjective,
    current_target_intent: TargetIntent | str = TargetIntent.objective,
    flee_active: bool = False,
    rest_active: bool = False,
    drop_aggro_active: bool = False,
) -> bool:
    if stop_after_removed:
        return False

    return (
        should_preserve_current_party_target(
            args,
            party_state,
            current_target,
            active_combat,
            behavior_state=behavior_state,
            current_target_intent=current_target_intent,
            flee_active=flee_active,
            rest_active=rest_active,
            drop_aggro_active=drop_aggro_active,
        )
        and target_removed_preserve_allowed(args, now, last_visible_at, preserve_count)
    )


def should_preserve_unshared_party_target(
    args: argparse.Namespace,
    current_target: int,
    active_combat: dict[str, float | int | str] | None,
    *,
    behavior_state: DummyBehaviorState | str = DummyBehaviorState.HuntObjective,
    current_target_intent: TargetIntent | str = TargetIntent.objective,
    flee_active: bool = False,
    rest_active: bool = False,
    drop_aggro_active: bool = False,
) -> bool:
    return (
        should_preserve_party_target_on_loss(args)
        and current_target > 0
        and can_preserve_committed_hostile_target(
            behavior_state,
            current_target_intent,
            flee_active=flee_active,
            rest_active=rest_active,
            drop_aggro_active=drop_aggro_active,
        )
        and (
            active_combat_matches_preservable_objective_target(args, active_combat)
            or should_preserve_active_party_rescue_focus(
                args,
                active_combat,
                current_target,
                TargetIntent.none,
            )
        )
    )


def active_combat_matches_required_target(args: argparse.Namespace, active_combat: dict[str, float | int | str] | None) -> bool:
    if active_combat is None:
        return False

    target_name = str(active_combat.get("target_name", "")).lower()
    tokens = required_target_tokens(args)
    if tokens:
        return bool(target_name and any(required_target_name_matches_for_args(args, target_name, token) for token in tokens))

    if getattr(args, "party_encounter_mode", "standard") != "standard":
        return int(active_combat.get("target_id", 0) or 0) > 0

    return False


def active_combat_matches_dynamic_quest_followup_target(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
) -> bool:
    if active_combat is None:
        return False

    followup_target = normalize_target_name(str(getattr(args, "dynamic_quest_followup_target_name", "") or ""))
    target_name = normalize_target_name(str(active_combat.get("target_name", "") or ""))
    return bool(
        followup_target
        and target_name
        and (
            target_name == followup_target
            or target_name in followup_target
            or followup_target in target_name
        )
    )


def active_combat_matches_preservable_objective_target(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
) -> bool:
    return bool(
        active_combat_matches_required_target(args, active_combat)
        or active_combat_matches_dynamic_quest_followup_target(args, active_combat)
    )


def name_matches_required_target(args: argparse.Namespace, target_name: str) -> bool:
    normalized_name = normalize_target_name(target_name)
    tokens = required_target_tokens(args)
    return bool(
        normalized_name
        and tokens
        and any(required_target_name_matches_for_args(args, normalized_name, token) for token in tokens)
    )


def name_matches_required_or_party_objective(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str] | None,
    target_name: str,
) -> bool:
    normalized_name = normalize_target_name(target_name)
    if not normalized_name:
        return False
    if name_matches_required_target(args, normalized_name):
        return True

    snapshot = party_snapshot or {}
    for key in ("leader_target_name", "rescue_target_name", "leader_target_focus_name"):
        objective_name = normalize_target_name(str(snapshot.get(key, "") or ""))
        if objective_name and (
            normalized_name == objective_name
            or normalized_name in objective_name
            or objective_name in normalized_name
        ):
            return True

    return False


def active_combat_target_name(active_combat) -> str:
    if active_combat is None:
        return ""
    if isinstance(active_combat, dict):
        return str(active_combat.get("target_name", "") or "")
    return str(getattr(active_combat, "target_name", "") or "")


def name_matches_active_combat_target(active_combat, target_name: str) -> bool:
    active_target_name = normalize_target_name(active_combat_target_name(active_combat))
    normalized_name = normalize_target_name(target_name)
    return bool(
        active_target_name
        and normalized_name
        and (
            normalized_name == active_target_name
            or normalized_name in active_target_name
            or active_target_name in normalized_name
        )
    )


def should_allow_party_rescue_before_objective_engaged(
    args: argparse.Namespace,
    party_snapshot: dict[str, int | float | str],
    active_combat: dict[str, float | int | str] | None,
    now: float | None = None,
    *,
    urgent: bool = False,
) -> bool:
    if getattr(args, "party_rescue_before_objective_engaged", False):
        return True

    if urgent:
        return True

    if active_combat_matches_required_target(args, active_combat):
        return True

    rescue_target_id = int(party_snapshot.get("rescue_target_id", 0) or 0)
    if rescue_target_id > 0:
        rescue_age = party_rescue_target_age(
            party_snapshot,
            rescue_target_id,
            time.monotonic() if now is None else now,
        )
        max_age = max(0.0, float(getattr(args, "party_rescue_max_age", 0.0) or 0.0))
        if rescue_age >= 0.0 and (max_age <= 0.0 or rescue_age <= max_age):
            return True

    if not should_preserve_party_target_on_loss(args) or not required_target_tokens(args):
        return True

    engaged_at = float(party_snapshot.get("leader_target_engaged_at", 0.0) or 0.0)
    if engaged_at <= 0.0:
        return False

    grace = max(0.0, float(getattr(args, "party_rescue_objective_engaged_grace", 0.0) or 0.0))
    if grace > 0.0:
        current_time = time.monotonic() if now is None else now
        if current_time - engaged_at < grace:
            return False

    return True


def should_stop_after_required_target_removed(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
    removed_object_id: int = 0,
) -> bool:
    if removed_object_id > 0 and active_combat is not None:
        active_target_id = int(active_combat.get("target_id", 0) or 0)
        if active_target_id > 0 and active_target_id != removed_object_id:
            return False

    return bool(
        getattr(args, "stop_after_required_target_removed", False)
        and active_combat_matches_required_target(args, active_combat)
    )


def required_target_removed_api_confirms_completion(
    args: argparse.Namespace,
    active_combat: dict[str, float | int | str] | None,
    observation: RequiredTargetObservation | None,
    removed_object_id: int = 0,
) -> bool:
    if not getattr(args, "required_target_api", False):
        return True

    if active_combat is None or observation is None or observation.object_id <= 0:
        return False

    active_target_id = int(active_combat.get("target_id", 0) or 0)
    if removed_object_id > 0 and active_target_id > 0 and removed_object_id != active_target_id:
        return False

    active_target_name = str(active_combat.get("target_name", "") or "")
    if (
        active_target_id > 0
        and observation.object_id != active_target_id
        and active_target_name
        and not required_target_name_matches(observation.name, active_target_name)
    ):
        return False

    if observation.is_alive is False:
        return True

    if observation.max_health > 0 and observation.health <= 0:
        return True

    return False


def smooth_movement_step(args: argparse.Namespace) -> float:
    return max(1.0, args.movement_speed * args.smooth_move_interval)


def combat_chase_movement_speed(args: argparse.Namespace, action_rotation: str, distance: float) -> float:
    base_speed = float(dummy_state_movement_cap(args) or getattr(args, "movement_speed", 0.0) or 0.0)
    if (
        is_melee_rotation(action_rotation)
        and distance > combat_chase_melee_stop_distance(args)
        and base_speed > 0.0
    ):
        return max(base_speed, float(getattr(args, "combat_chase_sprint_speed", 600.0) or 600.0))

    return base_speed


def combat_chase_melee_stop_distance(args: argparse.Namespace) -> float:
    if all(hasattr(args, name) for name in ("minimum_melee_stop_distance", "attack_range", "melee_range_buffer")):
        return melee_stop_distance(args)

    attack_range = float(getattr(args, "attack_range", 125.0) or 125.0)
    melee_range_buffer = float(getattr(args, "melee_range_buffer", 25.0) or 25.0)
    minimum_stop = float(getattr(args, "minimum_melee_stop_distance", 70.0) or 70.0)
    return max(minimum_stop, attack_range - melee_range_buffer)


def combat_chase_step(args: argparse.Namespace, action_rotation: str, distance: float, base_step: float) -> float:
    speed = combat_chase_movement_speed(args, action_rotation, distance)
    return max(base_step, speed * float(getattr(args, "smooth_move_interval", 0.0) or 0.0))


def active_tank_reaggro_chase_step(
    args: argparse.Namespace,
    snapshot: dict[str, int | float | str],
    member_name: str,
    action_rotation: str,
    target_npc,
    *,
    distance: float,
    base_step: float,
    now: float,
) -> float:
    if not party_member_is_active_tank(snapshot, member_name):
        return base_step

    if not is_melee_rotation(action_rotation):
        return base_step

    target_id = int(getattr(target_npc, "object_id", 0) or 0)
    pressure_member = party_reaggro_pressure_member_name(args, snapshot, now=now, target_id=target_id)
    active_tank_name = normalize_target_name(str(snapshot.get("active_tank_name", "") or ""))
    if not pressure_member or pressure_member == active_tank_name:
        return base_step

    if distance <= combat_chase_melee_stop_distance(args):
        return base_step

    return max(base_step, base_step * 4.0)


def waypoint_distance_from_client(client, waypoint: Waypoint) -> float:
    return path_distance(PathPoint(int(client.x), int(client.y), int(client.z)), PathPoint(waypoint.x, waypoint.y, waypoint.z))


def advance_continuous_waypoint_index(client, args: argparse.Namespace, waypoint_index: int) -> int:
    if not getattr(args, "waypoint_continuous_turns", False) or not args.waypoints:
        return waypoint_index

    configured_distance = getattr(args, "waypoint_advance_distance", 0.0)
    advance_distance = configured_distance if configured_distance > 0 else args.waypoint_stop_distance
    max_advances = len(args.waypoints)

    for _ in range(max_advances):
        waypoint = args.waypoints[waypoint_index]

        if waypoint_distance_from_client(client, waypoint) > advance_distance:
            break

        if args.waypoint_mode == "random":
            waypoint_index = random.randrange(0, len(args.waypoints))
        else:
            waypoint_index = (waypoint_index + 1) % len(args.waypoints)

    return waypoint_index


def parse_int_list(value: str) -> list[int]:
    numbers: list[int] = []

    for part in value.split(","):
        part = part.strip()

        if not part:
            continue

        numbers.append(int(part))

    if not numbers:
        raise ValueError("empty integer list")

    return numbers


def parse_optional_int_list(value: str) -> list[int]:
    if not value.strip():
        return []

    return parse_int_list(value)


def flatten_int_groups(groups: list[list[int]] | None) -> list[int]:
    return [value for group in (groups or []) for value in group]


def parse_text_list(value: str) -> list[str]:
    return [part.strip() for part in value.split("|") if part.strip()]


def parse_name_list(value: str) -> list[str]:
    return [part.strip() for part in re.split(r"[|,]", value) if part.strip()]


def parse_waypoints(value: str) -> list[Waypoint]:
    waypoints: list[Waypoint] = []

    for part in value.split("|"):
        part = part.strip()

        if not part:
            continue

        pieces = [piece.strip() for piece in part.split(",")]

        if len(pieces) != 3:
            raise ValueError(f"invalid waypoint '{part}', expected x,y,z")

        waypoints.append(Waypoint(int(pieces[0]), int(pieces[1]), int(pieces[2])))

    return waypoints


def parse_waypoint(value: str) -> Waypoint:
    waypoints = parse_waypoints(value)

    if len(waypoints) != 1:
        raise ValueError(f"invalid point '{value}', expected one x,y,z coordinate")

    return waypoints[0]


def resolve_path_graph_path(value: str) -> Path:
    graph_path = Path(value)

    if graph_path.is_absolute() and graph_path.exists():
        return graph_path

    candidates = [
        Path.cwd() / graph_path,
        Path(__file__).resolve().parents[1] / graph_path,
        Path(__file__).resolve().parent / graph_path,
    ]

    for candidate in candidates:
        if candidate.exists():
            return candidate

    return graph_path


def load_path_graph(value: str):
    if not value:
        return None

    graph_path = resolve_path_graph_path(value)
    cache_key = str(graph_path.resolve()) if graph_path.exists() else str(graph_path)

    with PATH_GRAPH_CACHE_LOCK:
        if cache_key not in PATH_GRAPH_CACHE:
            PATH_GRAPH_CACHE[cache_key] = PathGraph.from_file(graph_path)

        return PATH_GRAPH_CACHE[cache_key]


def load_ground_z_sampler(value: str, z_offset: int = 0):
    if not value:
        return None

    map_path = resolve_path_graph_path(value)
    base_cache_key = str(map_path.resolve()) if map_path.exists() else str(map_path)
    cache_key = f"{base_cache_key}|z_offset={z_offset}"

    with GROUND_Z_MAP_CACHE_LOCK:
        if cache_key in GROUND_Z_MAP_CACHE:
            return GROUND_Z_MAP_CACHE[cache_key]

        payload = json.loads(map_path.read_text(encoding="utf-8"))
        if str(payload.get("type", "")).lower() == "daoc-client-zone-mpk":
            sampler = daoc_zone_heightmap.ClientZoneHeightSampler.from_config(map_path)
            base_sample = sampler.sample

            def sample_with_offset(x: int, y: int, zone_id: int) -> int | None:
                sampled = base_sample(x, y, zone_id)
                return None if sampled is None else sampled + z_offset

            GROUND_Z_MAP_CACHE[cache_key] = sample_with_offset
            return sample_with_offset

        max_distance = float(payload.get("max_distance", 600.0))
        method = str(payload.get("method", "nearest")).lower()
        sample_count = max(1, int(payload.get("sample_count", 4)))
        points = [
            (int(point["x"]), int(point["y"]), int(point["z"]))
            for point in payload.get("points", [])
            if all(key in point for key in ("x", "y", "z"))
        ]

        def sample(x: int, y: int, zone_id: int) -> int | None:
            if not points:
                return None

            nearest_points = sorted(points, key=lambda point: (point[0] - x) ** 2 + (point[1] - y) ** 2)[:sample_count]
            nearest = nearest_points[0]
            distance = ((nearest[0] - x) ** 2 + (nearest[1] - y) ** 2) ** 0.5

            if distance > max_distance:
                return None

            if method == "idw":
                weighted_z = 0.0
                total_weight = 0.0

                for point_x, point_y, point_z in nearest_points:
                    point_distance = max(1.0, ((point_x - x) ** 2 + (point_y - y) ** 2) ** 0.5)
                    weight = 1.0 / (point_distance * point_distance)
                    weighted_z += point_z * weight
                    total_weight += weight

                if total_weight > 0:
                    return int(round(weighted_z / total_weight))

            return nearest[2]

        if z_offset:
            base_sample = sample

            def sample_with_offset(x: int, y: int, zone_id: int) -> int | None:
                sampled = base_sample(x, y, zone_id)
                return None if sampled is None else sampled + z_offset

            GROUND_Z_MAP_CACHE[cache_key] = sample_with_offset
            return sample_with_offset

        GROUND_Z_MAP_CACHE[cache_key] = sample
        return sample


def load_client_grid_nav(args: argparse.Namespace):
    value = getattr(args, "client_grid_nav_map", "")

    if not value:
        return None

    map_path = resolve_path_graph_path(value)
    base_cache_key = str(map_path.resolve()) if map_path.exists() else str(map_path)
    cache_key = "|".join(
        [
            base_cache_key,
            f"cell={getattr(args, 'client_grid_nav_cell_size', 256)}",
            f"max_step_z={getattr(args, 'client_grid_nav_max_step_z', 240)}",
            f"water={getattr(args, 'client_grid_nav_allow_water', False)}",
            f"fixture={getattr(args, 'client_grid_nav_fixture_padding', 160)}",
            f"visited={getattr(args, 'client_grid_nav_max_visited', 20000)}",
        ]
    )

    with CLIENT_GRID_NAV_CACHE_LOCK:
        if cache_key not in CLIENT_GRID_NAV_CACHE:
            CLIENT_GRID_NAV_CACHE[cache_key] = daoc_lightweight_navgrid.ClientNavGridPathfinder(
                map_path,
                cell_size=getattr(args, "client_grid_nav_cell_size", 256),
                max_step_z=getattr(args, "client_grid_nav_max_step_z", 240),
                allow_water=getattr(args, "client_grid_nav_allow_water", False),
                fixture_padding=getattr(args, "client_grid_nav_fixture_padding", 160),
                max_visited=getattr(args, "client_grid_nav_max_visited", 20000),
            )

        return CLIENT_GRID_NAV_CACHE[cache_key]


def build_nav_path_url(args: argparse.Namespace, region: int, start: object, goal: object) -> str:
    query = urllib.parse.urlencode(
        {
            "region": region,
            "startX": int(start.x),
            "startY": int(start.y),
            "startZ": int(start.z),
            "endX": int(goal.x),
            "endY": int(goal.y),
            "endZ": int(goal.z),
            "maxNodes": args.nav_api_max_nodes,
            "snap": "true" if args.nav_api_snap else "false",
            "avoidBlockingDoors": "true" if args.nav_api_avoid_blocking_doors else "false",
        }
    )
    return f"{args.nav_api_url.rstrip('/')}/api/dummy/nav/path?{query}"


def parse_nav_point(value: object) -> object | None:
    if not isinstance(value, dict):
        return None

    try:
        return PathPoint(int(value["x"]), int(value["y"]), int(value["z"]))
    except (KeyError, TypeError, ValueError):
        return None


def same_path_point(left: object, right: object) -> bool:
    return int(left.x) == int(right.x) and int(left.y) == int(right.y) and int(left.z) == int(right.z)


def parse_nav_path_response(payload: dict[str, object]) -> NavPathResult:
    ok = bool(payload.get("ok"))
    status = str(payload.get("status", "Unknown"))
    raw_points = payload.get("points", [])
    snapped_start = parse_nav_point(payload.get("snappedStart"))
    snapped_end = parse_nav_point(payload.get("snappedEnd"))
    floor = parse_nav_point(payload.get("floor"))

    if not ok or not isinstance(raw_points, list):
        return NavPathResult(False, status, [], floor=floor, snapped_start=snapped_start, snapped_end=snapped_end)

    points: list[object] = []
    raw_point_count = 0

    for raw_point in raw_points:
        point = parse_nav_point(raw_point)

        if point is None:
            continue

        raw_point_count += 1
        points.append(point)

    if snapped_start is not None and (not points or not same_path_point(points[0], snapped_start)):
        points.insert(0, snapped_start)

    if snapped_end is not None and raw_point_count == 0 and not bool(payload.get("lineOfSight")):
        points.clear()
    elif snapped_end is not None and (not points or not same_path_point(points[-1], snapped_end)):
        points.append(snapped_end)

    return NavPathResult(
        bool(points),
        status,
        points,
        line_of_sight=bool(payload.get("lineOfSight")),
        snapped_start=snapped_start,
        snapped_end=snapped_end,
        floor=floor,
    )


def request_nav_path(args: argparse.Namespace, region: int, start: object, goal: object) -> NavPathResult:
    if not args.nav_api_url:
        return NavPathResult(False, "disabled", [])

    request = urllib.request.Request(build_nav_path_url(args, region, start, goal), headers={"Accept": "application/json"})

    try:
        with urllib.request.urlopen(request, timeout=args.nav_api_timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except Exception as exc:
        return NavPathResult(False, f"nav api error: {exc}", [])

    if not isinstance(payload, dict):
        return NavPathResult(False, "nav api returned a non-object response", [])

    return parse_nav_path_response(payload)


def build_combat_usable_api_url_for_player(args: argparse.Namespace, name: str, account: str = "") -> str:
    api_url_override = str(getattr(args, "combat_usable_api_url", "") or "")
    if api_url_override:
        base_url = api_url_override
    else:
        configured_host = str(getattr(args, "host", "127.0.0.1") or "127.0.0.1")
        api_host = configured_host if configured_host in ("127.0.0.1", "localhost", "::1") else "127.0.0.1"
        base_url = f"http://{api_host}:{getattr(args, 'api_port', 5000)}/api/dummy/combat/usable"

    query = urllib.parse.urlencode({"name": name, "account": account})
    separator = "&" if "?" in base_url else "?"
    return f"{base_url}{separator}{query}"


def build_combat_usable_api_url(args: argparse.Namespace, account: DummyAccount) -> str:
    return build_combat_usable_api_url_for_player(
        args,
        character_name_from_account(account.username),
        account.username,
    )


